INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86228, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，指好看、令人愉快。", "primary_collocate": null, "pronunciation": "měi", "ipa": "meɪ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "这里的风景真美。", "target_word": "美", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的歌声很美，大家都在听。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天的山很美，我们爬了一天。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后的天空真美！", "target_word": "美", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜里的海边很美，也很安静。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌的声音真美，我听了三遍。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天花开的时候，公园里美极了。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖边的夜景很美，很多人在拍照。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那里的日出美得让人忘了说话。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海上的日落多美啊，我们站着看了很久。", "target_word": "美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美好", "label": "复合"}, {"form": "美美", "label": "重叠"}], "register": "中性", "sense_fingerprint": "单用作谓语，形容风景、天空、声音、气氛等令人愉快、赏心悦目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c83067b8-a588-41b5-ab44-79eb0cbc0896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86228, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美", "is_correct": true, "explanation": "正确：“美”（měi，第三声）是本词，意思是好看、令人愉快。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 měi（第三声）声调不同，意思是妹妹。"}, {"text": "没", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是不、没有。"}, {"text": "煤", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是煤。"}, {"text": "买", "is_correct": false, "explanation": "mǎi 与 měi 韵母不同（ǎi 与 ěi），声调相同，意思是买。"}], "explanations": {"美": "正确：“美”（měi，第三声）是本词，意思是好看、令人愉快。", "妹": "mèi（第四声）与 měi（第三声）声调不同，意思是妹妹。", "没": "méi（第二声）与 měi（第三声）声调不同，意思是不、没有。", "煤": "méi（第二声）与 měi（第三声）声调不同，意思是煤。", "买": "mǎi 与 měi 韵母不同（ǎi 与 ěi），声调相同，意思是买。"}, "sentence_index": null, "correct_answer": "美"}, "level_3": {"options": [{"text": "吵", "is_correct": false, "explanation": "搭配：“吵”形容声音，不能用来形容风景，“风景真吵”不成立。"}, {"text": "美", "is_correct": true, "explanation": "正确：“美”形容风景好看，与“真……”的赞叹相合。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度，不用来评价风景是否好看，这里不成立。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高度，不用来评价风景是否好看，这里不成立。"}], "explanations": {"吵": "搭配：“吵”形容声音，不能用来形容风景，“风景真吵”不成立。", "美": "正确：“美”形容风景好看，与“真……”的赞叹相合。", "高": "搭配：“高”说高度，不用来评价风景是否好看，这里不成立。", "矮": "搭配：“矮”说高度，不用来评价风景是否好看，这里不成立。"}, "sentence_index": 0, "correct_answer": "美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他考得很美。", "explanation": "这里应该用〈好〉。“美”用于景色、声音等让人愉悦的外观，不用于成绩。"}, {"text": "这碗面的温度很美，我吃不下去。", "explanation": "这里应该用〈烫〉。“美”不用于温度，面太热要说“烫”。"}, {"text": "这次旅行的价格很美，我们付不起。", "explanation": "这里应该用〈贵〉。“美”不用于价格，价格高要说“贵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86228, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "美", "is_correct": true, "explanation": "正确：“美”（měi，第三声）是本词，意思是好看、令人愉快。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 měi（第三声）声母不同（b 与 m），意思是北方。"}, {"text": "眉", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是眉毛。"}, {"text": "梅", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是梅花。"}], "explanations": {"美": "正确：“美”（měi，第三声）是本词，意思是好看、令人愉快。", "北": "běi（第三声）与 měi（第三声）声母不同（b 与 m），意思是北方。", "眉": "méi（第二声）与 měi（第三声）声调不同，意思是眉毛。", "梅": "méi（第二声）与 měi（第三声）声调不同，意思是梅花。"}, "sentence_index": null, "correct_answer": "美"}, "level_3": {"options": [{"text": "黑", "is_correct": false, "explanation": "语义：“黑”指没有光，与“春天花开的时候”明亮的情景相反。"}, {"text": "重", "is_correct": false, "explanation": "搭配：“重”说重量，不能用来形容公园，这里不成立。"}, {"text": "美", "is_correct": true, "explanation": "正确：“美”形容公园的景色，与“春天花开”相合。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”说厚度，不能用来形容公园，这里不成立。"}], "explanations": {"黑": "语义：“黑”指没有光，与“春天花开的时候”明亮的情景相反。", "重": "搭配：“重”说重量，不能用来形容公园，这里不成立。", "美": "正确：“美”形容公园的景色，与“春天花开”相合。", "厚": "搭配：“厚”说厚度，不能用来形容公园，这里不成立。"}, "sentence_index": 6, "correct_answer": "美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的脚很美，走不动了。", "explanation": "这里应该用〈疼〉。“美”不用于身体的疼痛，脚疼要说“我的脚很疼”。"}, {"text": "这次比赛他的速度很美。", "explanation": "这里应该用〈快〉。“美”不用于速度，速度高要说“快”。"}, {"text": "这个包的重量很美，我拿不动。", "explanation": "这里应该用〈重〉。“美”不用于重量，东西重要说“重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里的湖面真很美。", "corrected_sentence": "夜里的湖面真美。", "error_description": "“真”和“很”都是程度副词，不能同时修饰“美”，应删去“很”，写作“真美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片海美真。", "corrected_sentence": "这片海真美。", "error_description": "“真”是程度副词，要放在“美”前面，应为“真美”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86229, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浅", "is_correct": true, "explanation": "浅：从上面到下面的距离小，与“深”互为反义。"}, {"text": "宽", "is_correct": false, "explanation": "宽：指横向距离大，与“深”不构成反义关系。"}, {"text": "重", "is_correct": false, "explanation": "重：指重量大，其反义是“轻”，与“深”没有反义关系。"}, {"text": "短", "is_correct": false, "explanation": "短：指长度小，其反义是“长”，与“深”没有反义关系。"}], "correct_answer": "浅", "explanations": {"浅": "浅：从上面到下面的距离小，与“深”互为反义。", "宽": "宽：指横向距离大，与“深”不构成反义关系。", "重": "重：指重量大，其反义是“轻”，与“深”没有反义关系。", "短": "短：指长度小，其反义是“长”，与“深”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86229, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浅", "is_correct": true, "explanation": "浅：从上面到下面的距离小，与“深”互为反义。"}, {"text": "轻", "is_correct": false, "explanation": "轻：指重量小，其反义是“重”，与“深”没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快：指速度高，其反义是“慢”，与“深”没有反义关系。"}, {"text": "软", "is_correct": false, "explanation": "软：指质地柔软，其反义是“硬”，与“深”没有反义关系。"}], "correct_answer": "浅", "explanations": {"浅": "浅：从上面到下面的距离小，与“深”互为反义。", "轻": "轻：指重量小，其反义是“重”，与“深”没有反义关系。", "快": "快：指速度高，其反义是“慢”，与“深”没有反义关系。", "软": "软：指质地柔软，其反义是“硬”，与“深”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86229, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "深是从上面到下面很远。", "primary_collocate": null, "pronunciation": "shēn", "ipa": "ʂən˥", "syllable_count": 1, "sentences": [{"text": "这条河不深。", "target_word": "深", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海水很深，鱼也很多。", "target_word": "深", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小心，这个水池很深。", "target_word": "深", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这口井比那口井深。", "target_word": "深", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他掉进了很深的坑里。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了大雪，地上的雪很深。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游泳池一边浅，一边深。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水有两米深，你别下去。", "target_word": "深", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他挖的洞比我挖的深多了。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "井太深了，看不到水。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "深深", "label": "重叠"}, {"form": "深度", "label": "复合"}], "register": "中性", "sense_fingerprint": "深：从上面到下面很远，如水深、井深、坑深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fddb6c7-4338-4064-af81-9ba45978fdd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86229, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深", "is_correct": true, "explanation": "深（shēn，第一声）：从上面到下面很远，如水深、井深、坑深。"}, {"text": "森", "is_correct": false, "explanation": "sēn（第一声）与 shēn 声母不同（s/sh），意思是“森林”。"}, {"text": "升", "is_correct": false, "explanation": "shēng 与 shēn 韵尾不同（ng/n），意思是“上升”。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shēn（第一声）声调不同，意思是“神”。"}, {"text": "慎", "is_correct": false, "explanation": "shèn（第四声）与 shēn（第一声）声调不同，意思是“谨慎”。"}], "explanations": {"深": "深（shēn，第一声）：从上面到下面很远，如水深、井深、坑深。", "森": "sēn（第一声）与 shēn 声母不同（s/sh），意思是“森林”。", "升": "shēng 与 shēn 韵尾不同（ng/n），意思是“上升”。", "神": "shén（第二声）与 shēn（第一声）声调不同，意思是“神”。", "慎": "shèn（第四声）与 shēn（第一声）声调不同，意思是“谨慎”。"}, "sentence_index": null, "correct_answer": "深"}, "level_3": {"options": [{"text": "厚", "is_correct": false, "explanation": "语义：“厚”指物体两个面之间的距离大，多用于书、墙、被子，“这条河不厚”不成立。"}, {"text": "深", "is_correct": true, "explanation": "深：从上面到下面很远。“这条河不深”指河水从上到下的距离不大。"}, {"text": "薄", "is_correct": false, "explanation": "语义：“薄”指厚度小，与河的纵深无关，“这条河不薄”不通。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高度低，河的深浅不说“矮”，“这条河不矮”不成立。"}], "explanations": {"厚": "语义：“厚”指物体两个面之间的距离大，多用于书、墙、被子，“这条河不厚”不成立。", "深": "深：从上面到下面很远。“这条河不深”指河水从上到下的距离不大。", "薄": "语义：“薄”指厚度小，与河的纵深无关，“这条河不薄”不通。", "矮": "搭配：“矮”说高度低，河的深浅不说“矮”，“这条河不矮”不成立。"}, "sentence_index": 0, "correct_answer": "深"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座塔比那座塔深。", "explanation": "这里应该用〈高〉。深指从上面到下面很远，塔的高矮要用“高”。"}, {"text": "这块木板比那块木板深。", "explanation": "这里应该用〈厚〉。深指从上面到下面很远，木板的厚薄要用“厚”。"}, {"text": "这条路比那条路深。", "explanation": "这里应该用〈长〉。深指从上面到下面很远，道路的长短要用“长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86229, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "深", "is_correct": true, "explanation": "深（shēn，第一声）：从上面到下面很远，与“浅”相对。"}, {"text": "山", "is_correct": false, "explanation": "shān 与 shēn 韵尾不同（an/en），意思是“山”。"}, {"text": "生", "is_correct": false, "explanation": "shēng 与 shēn 韵尾不同（ng/n），意思是“生长”。"}, {"text": "渗", "is_correct": false, "explanation": "shèn（第四声）与 shēn 声调不同，意思是“渗透”。"}, {"text": "审", "is_correct": false, "explanation": "shěn（第三声）与 shēn 声调不同，意思是“审查”。"}], "explanations": {"深": "深（shēn，第一声）：从上面到下面很远，与“浅”相对。", "山": "shān 与 shēn 韵尾不同（an/en），意思是“山”。", "生": "shēng 与 shēn 韵尾不同（ng/n），意思是“生长”。", "渗": "shèn（第四声）与 shēn 声调不同，意思是“渗透”。", "审": "shěn（第三声）与 shēn 声调不同，意思是“审查”。"}, "sentence_index": null, "correct_answer": "深"}, "level_3": {"options": [{"text": "冷", "is_correct": false, "explanation": "语义：“冷”指温度低，与池子的深浅无关，“一边冷”与前一分句不搭。"}, {"text": "深", "is_correct": true, "explanation": "深：从上面到下面很远。“一边浅，一边深”形成对比，指池底深浅不同。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”指质地坚实，与池子的深浅不搭，“一边硬”不成立。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说向上的高度，池子的深浅不说“高”，“一边高”不通。"}], "explanations": {"冷": "语义：“冷”指温度低，与池子的深浅无关，“一边冷”与前一分句不搭。", "深": "深：从上面到下面很远。“一边浅，一边深”形成对比，指池底深浅不同。", "硬": "语义：“硬”指质地坚实，与池子的深浅不搭，“一边硬”不成立。", "高": "搭配：“高”说向上的高度，池子的深浅不说“高”，“一边高”不通。"}, "sentence_index": 6, "correct_answer": "深"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离学校很深。", "explanation": "这里应该用〈远〉。远指两地之间水平方向的距离大，学校的远近要用“远”，“深”只指从上面到下面的距离。"}, {"text": "这支笔很深。", "explanation": "这里应该用〈长〉。长指两端之间距离大，笔的长短要用“长”，“深”只指从上面到下面的距离。"}, {"text": "这根柱子很深。", "explanation": "这里应该用〈粗〉。粗指圆周大，柱子的粗细要用“粗”，“深”只指从上面到下面的距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个水池没深，小孩可以玩。", "corrected_sentence": "这个水池不深，小孩可以玩。", "error_description": "错误：“没”不能直接否定形容词“深”，应该用“不”。正确：“这个水池不深”。“没”一般用于否定动词或“有”字句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他挖洞挖很深。", "corrected_sentence": "他挖洞挖得很深。", "error_description": "错误：“挖很深”缺少补语标记“得”。正确：“挖得很深”。动词后接形容词作补语时，中间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86230, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浅", "is_correct": true, "explanation": "浅：从上到下或从外到里距离小，与“深”互为反义。"}, {"text": "高", "is_correct": false, "explanation": "高：指向上的距离大，与“深”不构成反义，“深”的反义是“浅”。"}, {"text": "厚", "is_correct": false, "explanation": "厚：指物体两个面之间的距离大，与“深”没有反义关系。"}, {"text": "宽", "is_correct": false, "explanation": "宽：指横向距离大，与“深”不构成反义关系。"}], "correct_answer": "浅", "explanations": {"浅": "浅：从上到下或从外到里距离小，与“深”互为反义。", "高": "高：指向上的距离大，与“深”不构成反义，“深”的反义是“浅”。", "厚": "厚：指物体两个面之间的距离大，与“深”没有反义关系。", "宽": "宽：指横向距离大，与“深”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86230, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浅", "is_correct": true, "explanation": "浅：从上到下或从外到里距离小，与“深”互为反义。"}, {"text": "长", "is_correct": false, "explanation": "长：指两端之间的距离大，其反义是“短”，与“深”不构成反义。"}, {"text": "快", "is_correct": false, "explanation": "快：指速度高，其反义是“慢”，与“深”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻：指重量小，其反义是“重”，与“深”没有反义关系。"}], "correct_answer": "浅", "explanations": {"浅": "浅：从上到下或从外到里距离小，与“深”互为反义。", "长": "长：指两端之间的距离大，其反义是“短”，与“深”不构成反义。", "快": "快：指速度高，其反义是“慢”，与“深”没有反义关系。", "轻": "轻：指重量小，其反义是“重”，与“深”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86230, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "从上到下或从外到里距离大。", "primary_collocate": null, "pronunciation": "shēn", "ipa": "ʂən˥", "syllable_count": 1, "sentences": [{"text": "这条河很深。", "target_word": "深", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这口井有十米深。", "target_word": "深", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "湖水太深，小孩不能游泳。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的树林很深，人很少去。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在院子里挖了一个很深的坑。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个洞又黑又深，我们不敢进去。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪很深，走路很难。", "target_word": "深", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个山洞里面很深，要带手电筒。", "target_word": "深", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水只有一米深，大人可以站着。", "target_word": "深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把树根埋得很深，风吹不倒。", "target_word": "深", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深深", "label": "重叠"}, {"form": "深度", "label": "复合"}], "register": "中性", "sense_fingerprint": "深：从上到下或从外到里距离大，与浅相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fddb6c7-4338-4064-af81-9ba45978fdd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86230, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深", "is_correct": true, "explanation": "深（shēn，第一声）：从上到下或从外到里距离大，与“浅”相对。"}, {"text": "森", "is_correct": false, "explanation": "sēn（第一声）与 shēn 声母不同（s/sh），意思是“森林”。"}, {"text": "声", "is_correct": false, "explanation": "shēng 与 shēn 韵尾不同（ng/n），意思是“声音”。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shēn（第一声）声调不同，意思是“神”。"}, {"text": "慎", "is_correct": false, "explanation": "shèn（第四声）与 shēn（第一声）声调不同，意思是“谨慎”。"}, {"text": "山", "is_correct": false, "explanation": "shān 与 shēn 韵尾不同（an/en），意思是“山”。"}], "explanations": {"深": "深（shēn，第一声）：从上到下或从外到里距离大，与“浅”相对。", "森": "sēn（第一声）与 shēn 声母不同（s/sh），意思是“森林”。", "声": "shēng 与 shēn 韵尾不同（ng/n），意思是“声音”。", "神": "shén（第二声）与 shēn（第一声）声调不同，意思是“神”。", "慎": "shèn（第四声）与 shēn（第一声）声调不同，意思是“谨慎”。", "山": "shān 与 shēn 韵尾不同（an/en），意思是“山”。"}, "sentence_index": null, "correct_answer": "深"}, "level_3": {"options": [{"text": "高", "is_correct": false, "explanation": "搭配：“高”多用于向上竖立的事物，河的深浅不说“高”，“这条河很高”不通。"}, {"text": "深", "is_correct": true, "explanation": "深：从上到下或从外到里距离大。“这条河很深”指河水从上到下的距离大。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”指物体两个面之间的距离大，多用于书、墙、被子，不用于河的纵深。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”指高度小，与河的深浅无关，“这条河很矮”不成立。"}], "explanations": {"高": "搭配：“高”多用于向上竖立的事物，河的深浅不说“高”，“这条河很高”不通。", "深": "深：从上到下或从外到里距离大。“这条河很深”指河水从上到下的距离大。", "厚": "语义：“厚”指物体两个面之间的距离大，多用于书、墙、被子，不用于河的纵深。", "矮": "语义：“矮”指高度小，与河的深浅无关，“这条河很矮”不成立。"}, "sentence_index": 0, "correct_answer": "深"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这匹马很深。", "explanation": "这里应该用〈高〉。深指从上到下或从外到里距离大，马的高矮要用“高”，“深”不能用来描述马。"}, {"text": "这床被子很深。", "explanation": "这里应该用〈厚〉。深指从上到下或从外到里距离大，被子的厚薄要用“厚”。"}, {"text": "我家离学校很深。", "explanation": "这里应该用〈远〉。深指从上到下或从外到里距离大，两地之间的远近要用“远”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86230, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "深", "is_correct": true, "explanation": "深（shēn，第一声）：从上到下或从外到里距离大，与“浅”相对。"}, {"text": "审", "is_correct": false, "explanation": "shěn（第三声）与 shēn 声调不同，意思是“审查”。"}, {"text": "生", "is_correct": false, "explanation": "shēng 与 shēn 韵尾不同（ng/n），意思是“生长”。"}, {"text": "渗", "is_correct": false, "explanation": "shèn（第四声）与 shēn 声调不同，意思是“渗透”。"}, {"text": "升", "is_correct": false, "explanation": "shēng 与 shēn 韵尾不同（ng/n），意思是“上升”。"}], "explanations": {"深": "深（shēn，第一声）：从上到下或从外到里距离大，与“浅”相对。", "审": "shěn（第三声）与 shēn 声调不同，意思是“审查”。", "生": "shēng 与 shēn 韵尾不同（ng/n），意思是“生长”。", "渗": "shèn（第四声）与 shēn 声调不同，意思是“渗透”。", "升": "shēng 与 shēn 韵尾不同（ng/n），意思是“上升”。"}, "sentence_index": null, "correct_answer": "深"}, "level_3": {"options": [{"text": "远", "is_correct": false, "explanation": "语义：“远”指距离长，与雪的厚薄无关，“雪很远”不成立。"}, {"text": "深", "is_correct": true, "explanation": "深：从上到下距离大。“雪很深”指积雪厚，所以走路很难。"}, {"text": "短", "is_correct": false, "explanation": "搭配：“短”说长度小，雪的厚度不说“短”，“雪很短”不通。"}, {"text": "窄", "is_correct": false, "explanation": "语义：“窄”指宽度小，与雪的深浅不搭，“雪很窄”不成立。"}], "explanations": {"远": "语义：“远”指距离长，与雪的厚薄无关，“雪很远”不成立。", "深": "深：从上到下距离大。“雪很深”指积雪厚，所以走路很难。", "短": "搭配：“短”说长度小，雪的厚度不说“短”，“雪很短”不通。", "窄": "语义：“窄”指宽度小，与雪的深浅不搭，“雪很窄”不成立。"}, "sentence_index": 6, "correct_answer": "深"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子很深。", "explanation": "这里应该用〈长〉。长指两端之间距离大，绳子的长短要用“长”，“深”不能用来描述绳子。"}, {"text": "这条马路很深。", "explanation": "这里应该用〈宽〉。宽指横向距离大，马路的宽窄要用“宽”，“深”不能用来描述路面。"}, {"text": "这根柱子很深。", "explanation": "这里应该用〈粗〉。粗指圆周大，柱子的粗细要用“粗”，“深”不能用来描述柱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把树根挖很深。", "corrected_sentence": "他把树根挖得很深。", "error_description": "错误：“挖很深”缺少补语标记“得”。正确：“挖得很深”。动词后接形容词作补语时，中间要用“得”连接，不能直接用“很”加形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河深太，船不能过。", "corrected_sentence": "这条河太深，船不能过。", "error_description": "错误：副词“太”要放在形容词“深”前面，应说“太深”，不说“深太”。正确：“这条河太深”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f08496-8ca7-465a-851a-971d0ff6ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
