INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86231, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“行”是说能干，很会做事。", "primary_collocate": null, "pronunciation": "xíng", "ipa": "ɕiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他做饭真行，比饭馆的还好吃。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你修电脑很行，帮我看看吧。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师教数学特别行。", "target_word": "行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小李在公司很行，大家都服他。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真行，一个人搬了这么多书！", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她游泳特别行，拿过好几块奖牌。", "target_word": "行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到修车，没有人比他更行。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别看他年纪小，做事行着呢。", "target_word": "行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画画儿不行，但唱歌很行。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的汉语不太行，请你慢点儿说。", "target_word": "行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不行", "label": "否定"}, {"form": "行着呢", "label": "体标"}], "register": "口语", "sense_fingerprint": "行：能干、很会做事（口语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c83067b8-a588-41b5-ab44-79eb0cbc0896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86231, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行", "is_correct": true, "explanation": "行（xíng，第二声）：表示能干、很会做事，是本题的词。"}, {"text": "性", "is_correct": false, "explanation": "性（xìng，第四声）与行声调不同，意思是性质、性格。"}, {"text": "醒", "is_correct": false, "explanation": "醒（xǐng，第三声）与行声调不同，意思是醒来。"}, {"text": "星", "is_correct": false, "explanation": "星（xīng，第一声）与行声调不同，意思是星星。"}], "explanations": {"行": "行（xíng，第二声）：表示能干、很会做事，是本题的词。", "性": "性（xìng，第四声）与行声调不同，意思是性质、性格。", "醒": "醒（xǐng，第三声）与行声调不同，意思是醒来。", "星": "星（xīng，第一声）与行声调不同，意思是星星。"}, "sentence_index": null, "correct_answer": "行"}, "level_3": {"options": [{"text": "行", "is_correct": true, "explanation": "行：表示能干、做得好，符合“比饭馆的还好吃”的评价。"}, {"text": "差", "is_correct": false, "explanation": "语义：“差”与“比饭馆的还好吃”矛盾。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”说身材，不能用来评价做饭的本领。"}, {"text": "笨", "is_correct": false, "explanation": "语义：“笨”说智力或动作不灵，与“比饭馆的还好吃”矛盾。"}], "explanations": {"行": "行：表示能干、做得好，符合“比饭馆的还好吃”的评价。", "差": "语义：“差”与“比饭馆的还好吃”矛盾。", "胖": "体貌：“胖”说身材，不能用来评价做饭的本领。", "笨": "语义：“笨”说智力或动作不灵，与“比饭馆的还好吃”矛盾。"}, "sentence_index": 0, "correct_answer": "行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的头疼得很行。", "explanation": "这里应该用〈厉害〉。“行”形容人的本领或事情可不可以，不能用来说病痛的程度。"}, {"text": "他写的字是行书，笔画很流畅。", "explanation": "这里的“行”属于“行书”（xíngshū，一种字体），与“能干、很会做事”无关。"}, {"text": "这首诗每段有四行。", "explanation": "这里的“行”指诗句的行（háng），是量词，与“能干”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86231, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行", "is_correct": true, "explanation": "行（xíng，第二声）：表示能干、很会做事，是本题的词。"}, {"text": "姓", "is_correct": false, "explanation": "姓（xìng，第四声）与行声调不同，意思是姓氏。"}, {"text": "兴", "is_correct": false, "explanation": "兴（xīng，第一声）与行声调不同，意思是兴奋、兴起。"}, {"text": "杏", "is_correct": false, "explanation": "杏（xìng，第四声）与行声调不同，意思是杏子。"}, {"text": "晴", "is_correct": false, "explanation": "晴（qíng，第二声）声母 q 与 x 不同，声调相同，意思是晴天。"}, {"text": "腥", "is_correct": false, "explanation": "腥（xīng，第一声）与行声调不同，意思是腥味。"}], "explanations": {"行": "行（xíng，第二声）：表示能干、很会做事，是本题的词。", "姓": "姓（xìng，第四声）与行声调不同，意思是姓氏。", "兴": "兴（xīng，第一声）与行声调不同，意思是兴奋、兴起。", "杏": "杏（xìng，第四声）与行声调不同，意思是杏子。", "晴": "晴（qíng，第二声）声母 q 与 x 不同，声调相同，意思是晴天。", "腥": "腥（xīng，第一声）与行声调不同，意思是腥味。"}, "sentence_index": null, "correct_answer": "行"}, "level_3": {"options": [{"text": "行", "is_correct": true, "explanation": "行：表示能干、本领强，符合“没有人比他更”的比较。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”说做事的态度，与“修车”的本领不对应。"}, {"text": "白", "is_correct": false, "explanation": "体貌：“白”说肤色，与修车的本事无关。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”说身高，不能用来比较修车的本领。"}], "explanations": {"行": "行：表示能干、本领强，符合“没有人比他更”的比较。", "懒": "语义：“懒”说做事的态度，与“修车”的本领不对应。", "白": "体貌：“白”说肤色，与修车的本事无关。", "矮": "体貌：“矮”说身高，不能用来比较修车的本领。"}, "sentence_index": 6, "correct_answer": "行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的行为让大家很失望。", "explanation": "这里的“行”是名词“行为”（xíng），指做事的举动，与“能干”无关。"}, {"text": "这个礼堂有十行座位。", "explanation": "这里的“行”指行列（háng），是量词，与“能干”无关。"}, {"text": "他们一行人去北京出差。", "explanation": "这里的“行”指同行的一群人（háng），与“可以、能干”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写字写很行，大家都夸他。", "corrected_sentence": "他写字写得很行，大家都夸他。", "error_description": "错误：动词重复后接补语，中间须用“得”连接，“写很行”少了“得”。正确应为“写得很行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的数学行很，经常拿第一名。", "corrected_sentence": "他的数学很行，经常拿第一名。", "error_description": "错误：“很”应放在“行”前修饰它，写成“行很”语序不对。正确应为“很行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
