INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86232, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，指可以、同意。", "primary_collocate": null, "pronunciation": "xíng", "ipa": "ɕiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "你明天来也行，后天来也行。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我坐这儿行吗？行，坐吧。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服不贵，你看行不行？", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天太晚了，明天再去也行。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你用我的手机打电话，行。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法行，我们就这么做。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样写行不行？老师说行。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要你高兴，怎么都行。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝茶还是喝水？都行，我不挑。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不带伞也行，今天不会下雨。", "target_word": "行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不行", "label": "否定"}, {"form": "行不行", "label": "正反问"}], "register": "口语", "sense_fingerprint": "行：表示同意、可以（口语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c83067b8-a588-41b5-ab44-79eb0cbc0896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86232, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行", "is_correct": true, "explanation": "行（xíng，第二声）：表示可以、同意，是本题的词。"}, {"text": "性", "is_correct": false, "explanation": "性（xìng，第四声）与行（xíng，第二声）声调不同，意思是性质、性格。"}, {"text": "醒", "is_correct": false, "explanation": "醒（xǐng，第三声）与行声调不同，意思是醒来。"}, {"text": "星", "is_correct": false, "explanation": "星（xīng，第一声）与行声调不同，意思是星星。"}], "explanations": {"行": "行（xíng，第二声）：表示可以、同意，是本题的词。", "性": "性（xìng，第四声）与行（xíng，第二声）声调不同，意思是性质、性格。", "醒": "醒（xǐng，第三声）与行声调不同，意思是醒来。", "星": "星（xīng，第一声）与行声调不同，意思是星星。"}, "sentence_index": null, "correct_answer": "行"}, "level_3": {"options": [{"text": "行", "is_correct": true, "explanation": "行：表示可以，符合“明天来也可以，后天来也可以”的意思。"}, {"text": "忙", "is_correct": false, "explanation": "语义：“忙”说人的状态，不能表示“来也可以”。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，与“明天来”的许可意思不合。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”说距离，不能用来修饰“来”表示许可。"}], "explanations": {"行": "行：表示可以，符合“明天来也可以，后天来也可以”的意思。", "忙": "语义：“忙”说人的状态，不能表示“来也可以”。", "慢": "语义：“慢”说速度，与“明天来”的许可意思不合。", "远": "搭配：“远”说距离，不能用来修饰“来”表示许可。"}, "sentence_index": 0, "correct_answer": "行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这页纸上有三行字写错了。", "explanation": "这里的“行”是名词，指文字的一行（háng），与“可以、同意”无关。"}, {"text": "我在这一行干了十年。", "explanation": "这里的“行”指行业（háng），是名词，不表示可以、同意。"}, {"text": "他们一行人走进了餐厅。", "explanation": "这里的“行”指同行的一群人（háng），是另一个用法，与“可以、能干”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86232, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行", "is_correct": true, "explanation": "行（xíng，第二声）：表示可以、同意，是本题的词。"}, {"text": "姓", "is_correct": false, "explanation": "姓（xìng，第四声）与行声调不同，意思是姓氏。"}, {"text": "兴", "is_correct": false, "explanation": "兴（xīng，第一声）与行声调不同，意思是兴奋、兴起。"}, {"text": "杏", "is_correct": false, "explanation": "杏（xìng，第四声）与行声调不同，意思是杏子。"}, {"text": "晴", "is_correct": false, "explanation": "晴（qíng，第二声）声母 q 与 x 不同，声调相同，意思是晴天。"}, {"text": "腥", "is_correct": false, "explanation": "腥（xīng，第一声）与行声调不同，意思是腥味。"}], "explanations": {"行": "行（xíng，第二声）：表示可以、同意，是本题的词。", "姓": "姓（xìng，第四声）与行声调不同，意思是姓氏。", "兴": "兴（xīng，第一声）与行声调不同，意思是兴奋、兴起。", "杏": "杏（xìng，第四声）与行声调不同，意思是杏子。", "晴": "晴（qíng，第二声）声母 q 与 x 不同，声调相同，意思是晴天。", "腥": "腥（xīng，第一声）与行声调不同，意思是腥味。"}, "sentence_index": null, "correct_answer": "行"}, "level_3": {"options": [{"text": "行", "is_correct": true, "explanation": "行：表示同意，老师的回答应是“行”。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”说距离，不能用来评价“这样写”是否可以。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度，与对“这样写”的评判不合。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量，不能用来表示同意。"}], "explanations": {"行": "行：表示同意，老师的回答应是“行”。", "远": "语义：“远”说距离，不能用来评价“这样写”是否可以。", "冷": "语义：“冷”说温度，与对“这样写”的评判不合。", "重": "语义：“重”说分量，不能用来表示同意。"}, "sentence_index": 6, "correct_answer": "行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的行为让大家很失望。", "explanation": "这里的“行”是名词“行为”（xíng），指做事的举动，与“可以、同意”无关。"}, {"text": "这首诗每段有四行。", "explanation": "这里的“行”指诗句的行（háng），是量词，不表示可以、同意。"}, {"text": "车子在路上行驶，很平稳。", "explanation": "这里的“行”属于“行驶”（xíngshǐ，指车辆移动），与“可以、能干”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你行去吧。", "corrected_sentence": "行，你去吧。", "error_description": "错误：“行”是形容词，表示可以，不能放在动词前当助动词用。正确应说“行，你去吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末去行也，你定时间吧。", "corrected_sentence": "周末去也行，你定时间吧。", "error_description": "错误：“也”应紧靠“行”放在前面，表示“去也可以”。写成“去行也”语序不对，正确应为“去也行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
