INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86234, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "action", "definition": "副词，表示一个接一个、接连不断。", "primary_collocate": null, "pronunciation": "lián", "ipa": "ljɛn˧˥", "syllable_count": 1, "sentences": [{"text": "这个星期连下了三天雨。", "target_word": "连", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他连说了三遍，我才听懂。", "target_word": "连", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她连喝了两杯水。", "target_word": "连", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们队连赢了五场比赛。", "target_word": "连", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟连着几天都没睡好。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连跑了三公里，累坏了。", "target_word": "连", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师连问了我两个问题。", "target_word": "连", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王连着三年都得第一名。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月他连迟到了四次。", "target_word": "连", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈连着做了三天饭。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連", "label": "繁体"}, {"form": "连着", "label": "体标"}, {"form": "连续", "label": "复合"}], "register": "中性", "sense_fingerprint": "连：一个接一个，接连不断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c83067b8-a588-41b5-ab44-79eb0cbc0896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86234, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "连", "is_correct": true, "explanation": "连（lián，第二声）：一个接一个、接连不断，是本题的词。"}, {"text": "年", "is_correct": false, "explanation": "年（nián）声母 n 与 l 不同，声调相同，意思是年份。"}, {"text": "脸", "is_correct": false, "explanation": "脸（liǎn，第三声）与连声调不同，意思是脸面。"}, {"text": "练", "is_correct": false, "explanation": "练（liàn，第四声）与连声调不同，意思是练习。"}], "explanations": {"连": "连（lián，第二声）：一个接一个、接连不断，是本题的词。", "年": "年（nián）声母 n 与 l 不同，声调相同，意思是年份。", "脸": "脸（liǎn，第三声）与连声调不同，意思是脸面。", "练": "练（liàn，第四声）与连声调不同，意思是练习。"}, "sentence_index": null, "correct_answer": "连"}, "level_3": {"options": [{"text": "连", "is_correct": true, "explanation": "连：表示接连不断，符合“连续下了三天雨”的意思。"}, {"text": "从来", "is_correct": false, "explanation": "语法：“从来”须与否定词连用，不能直接修饰“下了三天雨”。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”需要人作施事，不能修饰“下雨”。"}, {"text": "悄悄", "is_correct": false, "explanation": "语义：“悄悄”说动作无声，与下雨的意思不合。"}], "explanations": {"连": "连：表示接连不断，符合“连续下了三天雨”的意思。", "从来": "语法：“从来”须与否定词连用，不能直接修饰“下了三天雨”。", "亲自": "搭配：“亲自”需要人作施事，不能修饰“下雨”。", "悄悄": "语义：“悄悄”说动作无声，与下雨的意思不合。"}, "sentence_index": 0, "correct_answer": "连"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他连一口水都没喝。", "explanation": "这里的“连”表示“甚至”（连……都），不表示接连不断。"}, {"text": "他的错误连累了全家。", "explanation": "这里的“连”是“牵累、拖累”的意思，与“接合”和“接连”都无关。"}, {"text": "连老师也不认识他。", "explanation": "这里的“连”是“甚至”的意思，与“接连不断”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86234, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "连", "is_correct": true, "explanation": "连（lián，第二声）：一个接一个、接连不断，是本题的词。"}, {"text": "男", "is_correct": false, "explanation": "男（nán）声母 n 与 l 不同，声调相同，意思是男性。"}, {"text": "林", "is_correct": false, "explanation": "林（lín）韵母比连的 ian 少了 a，声调相同，意思是树林。"}, {"text": "兰", "is_correct": false, "explanation": "兰（lán）韵母 ian 变成 an，声调相同，意思是兰花。"}, {"text": "凉", "is_correct": false, "explanation": "凉（liáng）韵尾 n 换成 ng，声调相同，意思是凉爽。"}], "explanations": {"连": "连（lián，第二声）：一个接一个、接连不断，是本题的词。", "男": "男（nán）声母 n 与 l 不同，声调相同，意思是男性。", "林": "林（lín）韵母比连的 ian 少了 a，声调相同，意思是树林。", "兰": "兰（lán）韵母 ian 变成 an，声调相同，意思是兰花。", "凉": "凉（liáng）韵尾 n 换成 ng，声调相同，意思是凉爽。"}, "sentence_index": null, "correct_answer": "连"}, "level_3": {"options": [{"text": "连", "is_correct": true, "explanation": "连：表示接连不断，符合“接连问了两个问题”的意思。"}, {"text": "从来", "is_correct": false, "explanation": "语法：“从来”须与否定词连用，不能直接修饰“问了两个问题”。"}, {"text": "一概", "is_correct": false, "explanation": "语义：“一概”表示全部、一律，与“问了两个问题”的语境不合。"}, {"text": "并不", "is_correct": false, "explanation": "语义：“并不”表示否定，与句中已发生的“问了”矛盾。"}], "explanations": {"连": "连：表示接连不断，符合“接连问了两个问题”的意思。", "从来": "语法：“从来”须与否定词连用，不能直接修饰“问了两个问题”。", "一概": "语义：“一概”表示全部、一律，与“问了两个问题”的语境不合。", "并不": "语义：“并不”表示否定，与句中已发生的“问了”矛盾。"}, "sentence_index": 6, "correct_answer": "连"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "连小孩都知道这个道理。", "explanation": "这里的“连”是“甚至”的意思（连……都），与“接连不断”无关。"}, {"text": "他在一连当兵，训练很辛苦。", "explanation": "这里的“连”指部队的基层编制单位（连队），与“接合”和“接连”都无关。"}, {"text": "连老师都不认识他。", "explanation": "这里的“连”是“甚至”的意思，与“接连不断”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他着连打了五个电话，都没人接。", "corrected_sentence": "他连着打了五个电话，都没人接。", "error_description": "错误：“着”须紧跟动词，不能放在副词“连”之前；“着连打”语序不对，应为“连着打”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他着连坐了五个小时的车。", "corrected_sentence": "他连着坐了五个小时的车。", "error_description": "错误：“着”须紧跟动词，不能放在副词“连”之前；“着连坐”语序不对，应为“连着坐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
