INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86236, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于成片的地方或景物，如草地、树林、云、海。", "primary_collocate": null, "pronunciation": "piàn", "ipa": "pʰjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "山下有一片大草地。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上有一片白云。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那里有一片树林。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家后面有一片湖。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在一片空地上踢球。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗外是一片蓝色的海。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路的两边都是一片绿色。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "远处有一片灯光。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们种了一片玉米。", "target_word": "片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上飘来一大片云。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片片", "label": "重叠"}, {"form": "一大片", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词，用来数草地、树林、云、海等成片的地方或景物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e8d354-ddd6-4efa-834f-8a0151ab3ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86236, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "片", "is_correct": true, "explanation": "片：量词，用于数成片的地方或景物，如一片草地。"}, {"text": "篇", "is_correct": false, "explanation": "篇 piān（第一声）与 piàn（第四声）声调不同，意思是篇（文章的量词）。"}, {"text": "扁", "is_correct": false, "explanation": "扁 piǎn（第三声）与 piàn（第四声）声调不同，意思是扁平。"}, {"text": "变", "is_correct": false, "explanation": "变 biàn 与 piàn 声母不同（b 与 p），意思是变化。"}, {"text": "面", "is_correct": false, "explanation": "面 miàn 与 piàn 声母不同（m 与 p），意思是面粉、面条等。"}], "explanations": {"片": "片：量词，用于数成片的地方或景物，如一片草地。", "篇": "篇 piān（第一声）与 piàn（第四声）声调不同，意思是篇（文章的量词）。", "扁": "扁 piǎn（第三声）与 piàn（第四声）声调不同，意思是扁平。", "变": "变 biàn 与 piàn 声母不同（b 与 p），意思是变化。", "面": "面 miàn 与 piàn 声母不同（m 与 p），意思是面粉、面条等。"}, "sentence_index": null, "correct_answer": "片"}, "level_3": {"options": [{"text": "片", "is_correct": true, "explanation": "正确：“片”用于成片的地方，“一片大草地”自然。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、建筑等，草地不用“座”来数。"}, {"text": "朵", "is_correct": false, "explanation": "语义：“朵”用于花、云等，不能用来数草地。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对物件中的一个，不能用来数草地。"}], "explanations": {"片": "正确：“片”用于成片的地方，“一片大草地”自然。", "座": "搭配：“座”用于山、建筑等，草地不用“座”来数。", "朵": "语义：“朵”用于花、云等，不能用来数草地。", "只": "搭配：“只”用于动物或成对物件中的一个，不能用来数草地。"}, "sentence_index": 0, "correct_answer": "片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门前有一片路。", "explanation": "这里应该用〈条〉。“条”用于细长的东西，路要用“条”来数，不用“片”。"}, {"text": "我买了一片钢笔。", "explanation": "这里应该用〈支〉。钢笔要用“支”来数，“片”用于成片的地方或景物。"}, {"text": "我家养了一片猫。", "explanation": "这里应该用〈只〉。猫要用“只”来数，“片”用于成片的地方或景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "片", "is_correct": true, "explanation": "正确：“一片绿色”指成片的绿色景象，句意自然。"}, {"text": "滴", "is_correct": false, "explanation": "语义：“滴”用于液体，不能用来数绿色的景象。"}, {"text": "股", "is_correct": false, "explanation": "语义：“股”用于气流、水流等，不能用来数绿色。"}, {"text": "根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，不能用来数绿色的景象。"}], "explanations": {"片": "正确：“一片绿色”指成片的绿色景象，句意自然。", "滴": "语义：“滴”用于液体，不能用来数绿色的景象。", "股": "语义：“股”用于气流、水流等，不能用来数绿色。", "根": "搭配：“根”用于细长的东西，不能用来数绿色的景象。"}, "sentence_index": 6, "correct_answer": "片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着一片电话。", "explanation": "这里应该用〈部〉。电话要用“部”来数，“片”用于成片的地方或景物。"}, {"text": "他买了一片汽车。", "explanation": "这里应该用〈辆〉。汽车要用“辆”来数，“片”不能用于汽车。"}, {"text": "他戴着一片手表。", "explanation": "这里应该用〈块〉。手表要用“块”来数，“片”用于成片的地方或景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山坡上有大一片松树林。", "corrected_sentence": "山坡上有一大片松树林。", "error_description": "语序错误：“大”应放在“一”之后、“片”之前，说“一大片”，不能说“大一片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖边有片芦苇。", "corrected_sentence": "湖边有一片芦苇。", "error_description": "错误形式：片芦苇。正确形式：一片芦苇。原因：量词“片”前要加数词，说“一片芦苇”，不能省略“一”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
