INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在把这件事调查清楚了。", "corrected_sentence": "他把这件事调查清楚了。", "error_description": "体标错误：「正在」表示动作进行，不能与表示完成的「了」同用，应去掉「正在」，即「他把这件事调查清楚了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50feb6fa-0d2c-4a52-a299-68af71f67a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
