INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "追是在后面快快跑，想要赶上前面的人。", "primary_collocate": null, "pronunciation": "zhuī", "ipa": "ʈʂweɪ˥", "syllable_count": 1, "sentences": [{"text": "小狗在后面追着我跑。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察追上了那个小偷。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里追来追去。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得很快，我追不上他。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在地上追着一个球。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的人跑了，警察马上追过去。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我追了一路，还是没追到公交车。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟哭着追姐姐。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男孩一直追着小偷跑了两条街。", "target_word": "追", "complexity_tier": "T3", "furigana": "nà gè nán hái yì zhí zhuī zhe xiǎo tōu pǎo le liǎng tiáo jiē", "sentence_source": "generated"}, {"text": "别跑，我一定会追上你！", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追了", "label": "体标"}, {"form": "追着", "label": "体标"}, {"form": "追过", "label": "体标"}, {"form": "追上", "label": "复合"}], "register": "中性", "sense_fingerprint": "在后面跑着赶上前面的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc80c1b1-8ff1-4e63-afc6-b13565b16d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "追", "is_correct": true, "explanation": "正确答案：追 zhuī，意思是在后面快跑赶上。"}, {"text": "吹", "is_correct": false, "explanation": "吹 chuī 与 zhuī 声母不同（ch 与 zh），意思是吹气。"}, {"text": "坠", "is_correct": false, "explanation": "坠 zhuì 与 zhuī 声调不同（第四声），意思是落下。"}, {"text": "猪", "is_correct": false, "explanation": "猪 zhū 与 zhuī 韵母不同（u 与 ui），意思是猪。"}, {"text": "催", "is_correct": false, "explanation": "催 cuī 与 zhuī 声母不同（c 与 zh），意思是催促。"}], "explanations": {"追": "正确答案：追 zhuī，意思是在后面快跑赶上。", "吹": "吹 chuī 与 zhuī 声母不同（ch 与 zh），意思是吹气。", "坠": "坠 zhuì 与 zhuī 声调不同（第四声），意思是落下。", "猪": "猪 zhū 与 zhuī 韵母不同（u 与 ui），意思是猪。", "催": "催 cuī 与 zhuī 声母不同（c 与 zh），意思是催促。"}, "sentence_index": null, "correct_answer": "追"}, "level_3": {"options": [{"text": "追", "is_correct": true, "explanation": "“追”表示在后面快跑赶上，符合“在后面追着我跑”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：狗在后面跑时不会“吃着我跑”，与句意说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱着我跑”描述不出在后面跟人跑的动作，与句意不符。"}, {"text": "逃", "is_correct": false, "explanation": "语义：“逃”是逃离，与“在后面跟着我跑”的方向相反。"}], "explanations": {"追": "“追”表示在后面快跑赶上，符合“在后面追着我跑”的语境。", "吃": "语义：狗在后面跑时不会“吃着我跑”，与句意说不通。", "唱": "语义：“唱着我跑”描述不出在后面跟人跑的动作，与句意不符。", "逃": "语义：“逃”是逃离，与“在后面跟着我跑”的方向相反。"}, "sentence_index": 0, "correct_answer": "追"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐早班车，追上了九点的会议。", "explanation": "这里应该用〈赶〉。赶上表示来得及参加会议，会议不能被“追”；“追上”只用于追赶有形的人或车。"}, {"text": "他追忆了下个月的旅行计划。", "explanation": "这里的“追”是“追忆”义，指回想已经发生的往事；“下个月的旅行计划”还没有发生，不能被追忆。"}, {"text": "我在超市里追了一瓶酱油。", "explanation": "这里应该用〈买〉。买表示付钱获得东西；“追”是赶人或车，不能用来表示买东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "追", "is_correct": true, "explanation": "正确答案：追 zhuī，意思是在后面快跑赶上。"}, {"text": "捉", "is_correct": false, "explanation": "捉 zhuō 与 zhuī 韵母不同（o 与 i），意思是抓住。"}, {"text": "桌", "is_correct": false, "explanation": "桌 zhuō 与 zhuī 韵母不同（o 与 i），意思是桌子。"}, {"text": "之", "is_correct": false, "explanation": "之 zhī 与 zhuī 韵母不同（之没有 u 介音），常见于“之后”“之前”。"}], "explanations": {"追": "正确答案：追 zhuī，意思是在后面快跑赶上。", "捉": "捉 zhuō 与 zhuī 韵母不同（o 与 i），意思是抓住。", "桌": "桌 zhuō 与 zhuī 韵母不同（o 与 i），意思是桌子。", "之": "之 zhī 与 zhuī 韵母不同（之没有 u 介音），常见于“之后”“之前”。"}, "sentence_index": null, "correct_answer": "追"}, "level_3": {"options": [{"text": "追", "is_correct": true, "explanation": "“追了一路”指一路在后面赶，与后半句“还是没追到公交车”前后呼应。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃了一路”说不通，“吃”通常要接食物，不能与“一路”搭配。"}, {"text": "写", "is_correct": false, "explanation": "语义：写与赶车的动作无关，与“还是没追到公交车”说不通。"}, {"text": "画", "is_correct": false, "explanation": "语义：画一路与赶公交车的过程无关，句意不通。"}], "explanations": {"追": "“追了一路”指一路在后面赶，与后半句“还是没追到公交车”前后呼应。", "吃": "搭配：“吃了一路”说不通，“吃”通常要接食物，不能与“一路”搭配。", "写": "语义：写与赶车的动作无关，与“还是没追到公交车”说不通。", "画": "语义：画一路与赶公交车的过程无关，句意不通。"}, "sentence_index": 6, "correct_answer": "追"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我终于追到了钥匙。", "explanation": "这里应该用〈找〉。找到表示寻得失物；追是跑着赶人，不能用于找东西。"}, {"text": "我给她追了一封信。", "explanation": "这里应该用〈写〉。写信是动笔书写；“追”是赶人或车，不能用于写信。"}, {"text": "他在舞台上追了一首歌。", "explanation": "这里应该用〈唱〉。唱是发声演唱；“追”是赶人或车，不能用于唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑车追了上那辆汽车。", "corrected_sentence": "他骑车追上了那辆汽车。", "error_description": "错误形式：追了上；正确形式：追上了。“上”是“追”的结果补语，必须紧跟在“追”后面，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她追了着那只猫跑了很久。", "corrected_sentence": "她追着那只猫跑了很久。", "error_description": "错误形式：追了着；正确形式：追着。“着”表示动作持续进行，“了”不能和“着”同时用在同一个动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“并且”表示除了前一件事以外，还有另一件事。", "primary_collocate": null, "pronunciation": "bìng qiě", "ipa": "piŋ˥˩ tɕʰjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他会说英语，并且说得很好。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手机便宜，并且好用。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她会唱歌，并且会跳舞。", "target_word": "并且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师来了，并且带来了新书。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店东西好，并且很干净。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我吃了早饭，并且喝了牛奶。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写完作业，并且检查了一遍。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的菜好吃，并且不贵。", "target_word": "并且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们参观了学校，并且见到了校长。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做好饭，并且把桌子擦干净了。", "target_word": "并且", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词：连接两个动作或两种情况，表示除前一件事外还有后一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ad95ebb-2d68-48d2-a298-d9f392305c7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前后意思相反；这里“说得很好”是对“会说英语”的补充，并不相反。"}, {"text": "并且", "is_correct": true, "explanation": "正确：“并且”表示在前一件事之外还有另一件事，这里补充“说得很好”。"}, {"text": "以及", "is_correct": false, "explanation": "搭配：“以及”连接名词性成分，不能连接“会说英语”和“说得很好”这样的小句。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示二选一，这里说的是同一个人的两项能力，不是选择。"}], "explanations": {"但是": "语义：“但是”表示转折，前后意思相反；这里“说得很好”是对“会说英语”的补充，并不相反。", "并且": "正确：“并且”表示在前一件事之外还有另一件事，这里补充“说得很好”。", "以及": "搭配：“以及”连接名词性成分，不能连接“会说英语”和“说得很好”这样的小句。", "或者": "语义：“或者”表示二选一，这里说的是同一个人的两项能力，不是选择。"}, "sentence_index": 0, "correct_answer": "并且"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很努力，并且没有成功。", "explanation": "这里应该用〈但是〉。“并且”只表示补充，不表示转折；“很努力”与“没有成功”前后意思相反，要用“但是”。"}, {"text": "我很渴，并且却没有喝水。", "explanation": "这里应该用〈但是〉。“却”表示转折，与只表示补充的“并且”矛盾；“很渴”与“没有喝水”前后形成对比，要用“但是”。"}, {"text": "今天我们去爬山，并且去游泳，你选一个吧。", "explanation": "这里应该用〈或者〉。“并且”表示两件事都要做，这里后面说“你选一个”，是二选一，要用“或者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "配价：“而是”前面要有“不是……”的否定成分，这里没有，不能单独使用。"}, {"text": "并且", "is_correct": true, "explanation": "正确：“并且”连接动作，表示写完作业之外又检查了一遍。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”说明原因，“检查了一遍”不是“写完作业”的原因。"}, {"text": "以至", "is_correct": false, "explanation": "搭配：“以至”后面要接结果或程度，“检查了一遍”不能用“以至”引出。"}], "explanations": {"而是": "配价：“而是”前面要有“不是……”的否定成分，这里没有，不能单独使用。", "并且": "正确：“并且”连接动作，表示写完作业之外又检查了一遍。", "因为": "语义：“因为”说明原因，“检查了一遍”不是“写完作业”的原因。", "以至": "搭配：“以至”后面要接结果或程度，“检查了一遍”不能用“以至”引出。"}, "sentence_index": 6, "correct_answer": "并且"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这不是他的主意，并且是我的主意。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示更正或对比，“并且”只表示并列补充，不能用来更正前面的说法。"}, {"text": "即使下雨，并且我们也要去。", "explanation": "这里表示让步，应该用“即使……也……”的让步关系；“并且”只表示并列补充，不表示让步。"}, {"text": "虽然他很累，并且还在工作。", "explanation": "这里应该用〈但是〉。“虽然……”要与“但是”配合表示转折，“并且”只表示补充，不能与“虽然”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢音乐，并且电影。", "corrected_sentence": "我喜欢音乐，并且喜欢电影。", "error_description": "错误：“并且”后面直接接了名词“电影”，缺少谓语“喜欢”。“并且”连接的应是两个完整的谓语部分，应说“我喜欢音乐，并且喜欢电影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她不是很聪明，并且很努力。", "corrected_sentence": "她不是很聪明，而是很努力。", "error_description": "错误：“不是……而是……”表示更正或对比，“并且”只表示补充，不能替代“而是”。应说“她不是很聪明，而是很努力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
