INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示递进或并列关系。", "primary_collocate": null, "pronunciation": "bìng qiě", "ipa": "piŋ˥˩ tɕʰjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本书很有意思，并且很便宜。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很聪明，并且非常努力。", "target_word": "并且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢这个城市，并且想住在这里。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她打开窗户，并且关了灯。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "李明学过法语，并且学得不错。", "target_word": "并且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要认真听，并且做笔记。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气好，并且不太热，我们去爬山。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查了他的腿，并且给了他药。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法简单，并且有用。", "target_word": "并且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他看着我，并且点了点头。", "target_word": "并且", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词：连接并列或递进的成分，后面的内容补充或加深前面的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ad95ebb-2d68-48d2-a298-d9f392305c7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，“很便宜”不是因为“有意思”才有的结果，说不通。"}, {"text": "并且", "is_correct": true, "explanation": "正确：“并且”表示补充，这里在“有意思”之外又补充“很便宜”。"}, {"text": "以及", "is_correct": false, "explanation": "搭配：“以及”连接名词性成分，不能连接“很有意思”和“很便宜”这两个形容词短语。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示二选一，这里说的是书的两个优点，不是选择。"}], "explanations": {"因此": "语义：“因此”表示因果，“很便宜”不是因为“有意思”才有的结果，说不通。", "并且": "正确：“并且”表示补充，这里在“有意思”之外又补充“很便宜”。", "以及": "搭配：“以及”连接名词性成分，不能连接“很有意思”和“很便宜”这两个形容词短语。", "或者": "语义：“或者”表示二选一，这里说的是书的两个优点，不是选择。"}, "sentence_index": 0, "correct_answer": "并且"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很聪明，并且成绩很差。", "explanation": "这里应该用〈但是〉。“成绩很差”与“很聪明”形成转折，“并且”只表示补充，要用“但是”。"}, {"text": "周末可以去看电影，并且去逛街，你选一个吧。", "explanation": "这里应该用〈或者〉。后面说“你选一个”，是二选一，“并且”表示两件都要，要用“或者”。"}, {"text": "他很累，并且却还在工作。", "explanation": "这里应该用〈但是〉。“却”表示转折，与只表示补充的“并且”矛盾；“很累”与“还在工作”前后形成对比，要用“但是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "配价：“而是”前面要有“不是……”的否定成分，这里没有否定成分，不能用。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示承接的结果，“不太热”不是因为“天气好”才产生的结果。"}, {"text": "并且", "is_correct": true, "explanation": "正确：“并且”表示补充，这里在“天气好”之外又补充“不太热”。"}, {"text": "从而", "is_correct": false, "explanation": "语义：“从而”表示由此产生的结果，这里前后不构成因果，说不通。"}], "explanations": {"而是": "配价：“而是”前面要有“不是……”的否定成分，这里没有否定成分，不能用。", "于是": "语义：“于是”表示承接的结果，“不太热”不是因为“天气好”才产生的结果。", "并且": "正确：“并且”表示补充，这里在“天气好”之外又补充“不太热”。", "从而": "语义：“从而”表示由此产生的结果，这里前后不构成因果，说不通。"}, "sentence_index": 6, "correct_answer": "并且"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不是来玩的，并且是来工作的。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示更正或对比，“并且”只表示并列补充，不能用来更正前面的说法。"}, {"text": "即使天气很冷，并且我们也要去爬山。", "explanation": "这里表示让步，应该用“即使……也……”的让步关系；“并且”只表示并列补充，不表示让步。"}, {"text": "如果下雨，并且我们就不去爬山。", "explanation": "这里应该用〈就〉。“如果……”后面要用“就”引出结果，“并且”不能放在假设关系中，应去掉〈并且〉，说“如果下雨，我们就不去爬山”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很有钱，并且却很大方。", "corrected_sentence": "他很有钱，并且也很大方。", "error_description": "错误：“并且”表示补充，后面不能接表示转折的“却”，应说“并且也很大方”，“也”要放在“并且”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢喝茶，并且咖啡。", "corrected_sentence": "我喜欢喝茶，并且喜欢喝咖啡。", "error_description": "错误：“并且”后面直接接了名词“咖啡”，缺少谓语“喜欢喝”。“并且”连接的应是完整的谓语部分，应说“并且喜欢喝咖啡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打开", "is_correct": true, "explanation": "反义：“打开”与“关闭”相对，指使电脑重新开启，与本句动作相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”与“关闭”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”与“关闭”在任何义项上都不构成反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "无关：“写作”与“关闭”没有反义关系。"}], "correct_answer": "打开", "explanations": {"打开": "反义：“打开”与“关闭”相对，指使电脑重新开启，与本句动作相反。", "唱歌": "无关：“唱歌”与“关闭”没有反义关系。", "吃饭": "无关：“吃饭”与“关闭”在任何义项上都不构成反义关系。", "写作": "无关：“写作”与“关闭”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开启", "is_correct": true, "explanation": "反义：“开启”与“关闭”相对，指使网页重新打开，与本句动作相反。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”与“关闭”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”与“关闭”在任何义项上都不构成反义关系。"}, {"text": "学习", "is_correct": false, "explanation": "无关：“学习”与“关闭”没有反义关系。"}], "correct_answer": "开启", "explanations": {"开启": "反义：“开启”与“关闭”相对，指使网页重新打开，与本句动作相反。", "散步": "无关：“散步”与“关闭”没有反义关系。", "思考": "无关：“思考”与“关闭”在任何义项上都不构成反义关系。", "学习": "无关：“学习”与“关闭”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "关闭是把开着的东西合上。", "primary_collocate": null, "pronunciation": "guān bì", "ipa": "kwan˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "睡觉前请关闭电视。", "target_word": "关闭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他关闭了房间的窗户。", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把门关闭，外面很冷。", "target_word": "关闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她关闭电脑，走出办公室。", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机上要关闭手机。", "target_word": "关闭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出门前，我关闭了所有的灯。", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用完水，请关闭水龙头。", "target_word": "关闭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他关闭了房门，开始看书。", "target_word": "关闭", "complexity_tier": "T3", "furigana": "tā guān bì le fáng mén, kāi shǐ kàn shū", "sentence_source": "generated"}, {"text": "老师关闭了教室的门。", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以关闭这个网页吗？", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "关闭了", "label": "体标"}, {"form": "关闭过", "label": "体标"}, {"form": "關閉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把门、窗、电器等开着的东西合上或关掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e8d354-ddd6-4efa-834f-8a0151ab3ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关闭", "is_correct": true, "explanation": "“关闭”指使电视停止工作，与“睡觉前”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能说唱电视。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不说穿电视。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物或水，不能用于电视。"}], "explanations": {"关闭": "“关闭”指使电视停止工作，与“睡觉前”的语境相符。", "唱": "语义：“唱”的对象是歌曲，不能说唱电视。", "穿": "搭配：“穿”用于衣服、鞋袜，不说穿电视。", "煮": "语义：“煮”的对象是食物或水，不能用于电视。"}, "sentence_index": 0, "correct_answer": "关闭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他关闭了雨伞，走进屋里。", "explanation": "这里应该用〈收起〉。撑开的雨伞要说收起，关闭用于门窗、电器等可以开合或开关的事物。"}, {"text": "她关闭了眼睛，慢慢地睡着了。", "explanation": "这里应该用〈闭上〉。眼睛要说闭上，关闭用于门窗、电器等可以开合或开关的事物。"}, {"text": "他关闭了课本，开始做作业。", "explanation": "这里应该用〈合上〉。书本要说合上，关闭用于门窗、电器等可以开合或开关的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关闭", "is_correct": true, "explanation": "“关闭”指拧紧水龙头、停止出水，与“用完水”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，水龙头不能被“吃”。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、手表等，不说戴水龙头。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，与水龙头无关，句意不通。"}], "explanations": {"关闭": "“关闭”指拧紧水龙头、停止出水，与“用完水”的语境相符。", "吃": "语义：“吃”的对象是食物，水龙头不能被“吃”。", "戴": "搭配：“戴”用于帽子、手表等，不说戴水龙头。", "飞": "语义：“飞”指在空中移动，与水龙头无关，句意不通。"}, "sentence_index": 6, "correct_answer": "关闭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他关闭了桌上的蜡烛，房间里一片漆黑。", "explanation": "这里应该用〈熄灭〉。蜡烛要说熄灭或吹灭，关闭用于门窗、电器、水龙头等可以开合的物件。"}, {"text": "他关闭了手表，准备出门。", "explanation": "这里应该用〈戴〉。手表要说戴上或摘下，关闭用于门窗、电器、水龙头等可以开合的物件。"}, {"text": "他关闭了鞋子，穿着出了门。", "explanation": "这里应该用〈穿〉。鞋子要说穿上，关闭用于门窗、电器、水龙头等可以开合的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她关闭上门，走出了房间。", "corrected_sentence": "她关闭了门，走出了房间。", "error_description": "错误形式：关闭上。正确形式：关闭。原因：“关闭”本身已表示合上，不再接结果补语“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把水龙头关闭上了。", "corrected_sentence": "他把水龙头关闭了。", "error_description": "错误形式：关闭上了。正确形式：关闭了。原因：“关闭”本身已表示合上，不能再接结果补语“上”，多加的“上”是多余成分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
