INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86262, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "叹词，表示答应或同意对方。", "primary_collocate": null, "pronunciation": "èn", "ipa": "ən˥˩", "syllable_count": 1, "sentences": [{"text": "“明天一起去吗？”“嗯，好啊。”", "target_word": "嗯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈问我吃了没有，我说：“嗯，吃了。”", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“你会来吧？”“嗯，我一定来。”", "target_word": "嗯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说：“请坐。”我“嗯”了一声就坐下了。", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“这样可以吗？”“嗯，可以。”", "target_word": "嗯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他听了我的话，只“嗯”了一声。", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“你同意吗？”“嗯，我同意。”", "target_word": "嗯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "“作业写完了吗？”“嗯，写完了。”", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸问我累不累，我说：“嗯，有点儿累。”", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“我们走吧。”“嗯，走吧。”", "target_word": "嗯", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "叹词，口语中用来答应或同意对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40bec50f-c43d-494c-bc06-77387795ad2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86262, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嗯", "is_correct": true, "explanation": "嗯 èn 是叹词，口语中表示答应或同意，即本义项。"}, {"text": "恩", "is_correct": false, "explanation": "恩 ēn 为第一声，与 èn（第四声）声调不同，意思是恩惠、恩情。"}, {"text": "按", "is_correct": false, "explanation": "按 àn 与 èn 韵母不同（an 与 en），意思是用手压或依照。"}, {"text": "案", "is_correct": false, "explanation": "案 àn 与 èn 韵母不同（an 与 en），意思是方案或案件。"}, {"text": "暗", "is_correct": false, "explanation": "暗 àn 与 èn 韵母不同（an 与 en），意思是光线不足。"}], "explanations": {"嗯": "嗯 èn 是叹词，口语中表示答应或同意，即本义项。", "恩": "恩 ēn 为第一声，与 èn（第四声）声调不同，意思是恩惠、恩情。", "按": "按 àn 与 èn 韵母不同（an 与 en），意思是用手压或依照。", "案": "案 àn 与 èn 韵母不同（an 与 en），意思是方案或案件。", "暗": "暗 àn 与 èn 韵母不同（an 与 en），意思是光线不足。"}, "sentence_index": null, "correct_answer": "嗯"}, "level_3": {"options": [{"text": "嗯", "is_correct": true, "explanation": "“嗯”表示答应，与前面的提问和后面的“好啊”前后一致。"}, {"text": "唉", "is_correct": false, "explanation": "语义：唉表示叹气或无奈，与“好啊”的爽快答应语气相反。"}, {"text": "哼", "is_correct": false, "explanation": "语义：哼表示不满或轻蔑，与“好啊”的同意不符。"}, {"text": "唯", "is_correct": false, "explanation": "语域：唯是书面语的应答词，与口语对话中的“好啊”语域不合。"}], "explanations": {"嗯": "“嗯”表示答应，与前面的提问和后面的“好啊”前后一致。", "唉": "语义：唉表示叹气或无奈，与“好啊”的爽快答应语气相反。", "哼": "语义：哼表示不满或轻蔑，与“好啊”的同意不符。", "唯": "语域：唯是书面语的应答词，与口语对话中的“好啊”语域不合。"}, "sentence_index": 0, "correct_answer": "嗯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他摔倒后一边揉着膝盖，一边“嗯”地叫了一声。", "explanation": "这里的“嗯”是疼痛时的哼叫声，表示痛楚，不是答应或同意。"}, {"text": "我把碗打碎了，妈妈回过头，皱着眉“嗯”了一声，显然在责怪我。", "explanation": "这里的“嗯”是不满时的鼻音，表示责怪，不是答应或同意。"}, {"text": "这幅画的色彩太美了，他看了半天，只“嗯”地赞了一声。", "explanation": "这里的“嗯”是看到好东西时发出的赞叹声，不是答应或同意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嗯", "is_correct": true, "explanation": "“嗯”表示答应，与“你同意吗”的提问和“我同意”的回答相符。"}, {"text": "咦", "is_correct": false, "explanation": "语义：咦表示惊讶，与“我同意”的平静应答不符。"}, {"text": "呸", "is_correct": false, "explanation": "语域：呸表示唾弃或鄙视，语气粗俗，与平和的同意语境不合。"}, {"text": "哈", "is_correct": false, "explanation": "语义：哈表示笑或得意，与“我同意”的郑重表态不符。"}], "explanations": {"嗯": "“嗯”表示答应，与“你同意吗”的提问和“我同意”的回答相符。", "咦": "语义：咦表示惊讶，与“我同意”的平静应答不符。", "呸": "语域：呸表示唾弃或鄙视，语气粗俗，与平和的同意语境不合。", "哈": "语义：哈表示笑或得意，与“我同意”的郑重表态不符。"}, "sentence_index": 6, "correct_answer": "嗯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听完结果，只无奈地“嗯”了一声，叹了口气。", "explanation": "这里的“嗯”是无奈的叹息声，不是答应或同意。"}, {"text": "他埋头看书，嘴里小声“嗯”着，不知道在想什么。", "explanation": "这里的“嗯”是无意识的低声哼唱，不是对别人的答应。"}, {"text": "听到这个消息，我惊讶地“嗯”了一下，一时没反应过来。", "explanation": "这里的“嗯”是吃惊时的短促声音，不是答应或同意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他应了一个“嗯”，就走了。", "corrected_sentence": "他应了一声“嗯”，就走了。", "error_description": "“嗯”是一声应答，量词应用“声”，不能用“个”。错误形式：应了一个“嗯”；正确形式：应了一声“嗯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他“嗯”了一个，没有再说话。", "corrected_sentence": "他“嗯”了一下，没有再说话。", "error_description": "“嗯”的动量词应为“下”或“声”，不能用“个”。错误形式：“嗯”了一个；正确形式：“嗯”了一下。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86263, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
