INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86263, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城镇是很多人住在一起的城市和小镇。", "primary_collocate": null, "pronunciation": "chéng zhèn", "ipa": "ʈʂʰɤŋ˧˥ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "这个城镇不大，但是很安静。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越来越多的年轻人搬到城镇生活。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在海边的城镇里。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城镇有一所学校和两家医院。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我坐火车去了邻近的城镇。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城镇里的人多，农村的人少。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的城镇都很干净。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷从农村搬到了城镇。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城镇的晚上有很多灯。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个山边的城镇只有三千人。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "城镇化", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多人聚居的城市和小镇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b584fe-81b3-45c5-b43f-c258eb988e16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城镇", "is_correct": true, "explanation": "“这个___不大，但是很安静”指一个聚居的地方，“城镇”符合句意。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能“很安静”，句子不通。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“很安静”一般形容地方或人，不能用来形容鞋子。"}, {"text": "菜", "is_correct": false, "explanation": "语义：菜是食物，不能“很安静”，句子不通。"}], "explanations": {"城镇": "“这个___不大，但是很安静”指一个聚居的地方，“城镇”符合句意。", "面包": "语义：面包是食物，不能“很安静”，句子不通。", "鞋子": "搭配：“很安静”一般形容地方或人，不能用来形容鞋子。", "菜": "语义：菜是食物，不能“很安静”，句子不通。"}, "sentence_index": 0, "correct_answer": "城镇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们住在一只城镇里。", "explanation": "这里应该用〈座〉或〈个〉。“只”一般用于动物或成对的东西，城镇要用“座”或“个”。"}, {"text": "这辆城镇很大，很多人住在这里。", "explanation": "这里应该用〈座〉或〈个〉。“辆”用于车辆，城镇不能用“辆”。"}, {"text": "这个城镇只有五户人家。", "explanation": "这里应该用〈村庄〉。“城镇”指很多人聚居的地方，只有五户人家要说“村庄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城镇", "is_correct": true, "explanation": "“这里的___都很干净”指一个地方，“城镇”符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能说“很干净”，句子不通。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“很干净”形容物体或环境，不能用来形容性格。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不能说“很干净”，句子不通。"}], "explanations": {"城镇": "“这里的___都很干净”指一个地方，“城镇”符合句意。", "天气": "语义：天气是自然现象，不能说“很干净”，句子不通。", "性格": "搭配：“很干净”形容物体或环境，不能用来形容性格。", "数学": "语义：数学是学科，不能说“很干净”，句子不通。"}, "sentence_index": 6, "correct_answer": "城镇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山边有两棵城镇。", "explanation": "这里应该用〈座〉或〈个〉。“棵”用于植物，城镇不能用“棵”。"}, {"text": "这本城镇很安静，大家都喜欢。", "explanation": "这里应该用〈座〉或〈个〉。“本”用于书册，城镇不能用“本”。"}, {"text": "那个城镇昨天写了三篇作文。", "explanation": "这里应该用〈学生〉。城镇是地方，不会写作文，要说“学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所城镇有三所小学。", "corrected_sentence": "这个城镇有三所小学。", "error_description": "“城镇”的量词应用“个”或“座”，“所”多用于学校、房屋，不能用来修饰城镇。正确说法：这个城镇有三所小学。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山边有一座的城镇。", "corrected_sentence": "山边有一座城镇。", "error_description": "数量词“一座”与“城镇”之间不能加“的”，应说“一座城镇”。正确说法：山边有一座城镇。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
