INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86265, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "多个是不只一个，有好几个。", "primary_collocate": null, "pronunciation": "duō gè", "ipa": "tuɔ˥ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "桌子上有多个杯子。", "target_word": "多个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司在多个城市都有店。", "target_word": "多个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去过多个国家。", "target_word": "多个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题有多个答案。", "target_word": "多个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里有多个人在说话。", "target_word": "多个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我手机里有多个游戏。", "target_word": "多个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给了我们多个办法。", "target_word": "多个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店有多个入口。", "target_word": "多个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们学校有多个运动场。", "target_word": "多个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他找了多个朋友帮忙。", "target_word": "多个", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "多個", "label": "繁体"}], "register": "中性", "sense_fingerprint": "放在名词前，表示数量不止一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40bec50f-c43d-494c-bc06-77387795ad2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多个", "is_correct": true, "explanation": "“多个”表示不止一个，与“有……杯子”的数量意思相合。"}, {"text": "少量", "is_correct": false, "explanation": "搭配：“少量”多修饰不可数的东西，不能说“少量杯子”。"}, {"text": "整个", "is_correct": false, "explanation": "语义：“整个”指全部、整体，与“桌子上有……杯子”的数量意思不合。"}, {"text": "一个", "is_correct": false, "explanation": "语义：“一个”只表示单个，与“桌子上有……杯子”的多数量意思相反。"}], "explanations": {"多个": "“多个”表示不止一个，与“有……杯子”的数量意思相合。", "少量": "搭配：“少量”多修饰不可数的东西，不能说“少量杯子”。", "整个": "语义：“整个”指全部、整体，与“桌子上有……杯子”的数量意思不合。", "一个": "语义：“一个”只表示单个，与“桌子上有……杯子”的多数量意思相反。"}, "sentence_index": 0, "correct_answer": "多个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里有多个水，大家都可以喝。", "explanation": "这里用错了。水是不可数的物质，不能用“多个”修饰，应说“很多水”或“大量的水”。"}, {"text": "我们班有多个学生，正好三十人。", "explanation": "这里把“多个”用成了确定数目的意思。“多个”只表示不确定的较多数量，不能与“正好三十人”这样的确切数字同用，应说“三十人”。"}, {"text": "我家里有多个电脑，但我只有一台。", "explanation": "这里把“多个”用成了“一个”的意思。“多个”只表示不止一个，不能用来指只有一台的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多个", "is_correct": true, "explanation": "“多个”表示不止一个，与“老师给了我们……办法”的意思相合。"}, {"text": "零星", "is_correct": false, "explanation": "语义：“零星”表示少而分散，与“给了我们很多办法”的意思相反。"}, {"text": "寥寥", "is_correct": false, "explanation": "搭配：“寥寥”多用于“寥寥几个”等说法，不能直接修饰“办法”。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”表示只有一种，与“给了我们很多办法”的意思相反。"}], "explanations": {"多个": "“多个”表示不止一个，与“老师给了我们……办法”的意思相合。", "零星": "语义：“零星”表示少而分散，与“给了我们很多办法”的意思相反。", "寥寥": "搭配：“寥寥”多用于“寥寥几个”等说法，不能直接修饰“办法”。", "单一": "语义：“单一”表示只有一种，与“给了我们很多办法”的意思相反。"}, "sentence_index": 6, "correct_answer": "多个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "从这里到学校有多个公里。", "explanation": "这里用错了。“公里”是度量单位，应说“几公里”或“多少公里”，不能用“多个”修饰。"}, {"text": "我们班的班长有多个人。", "explanation": "这里用错了。班长只能是一个人，“多个”不能修饰这个唯一的职位。"}, {"text": "这道题只有一个答案，却有多个答案。", "explanation": "这里“多个”表示不止一个，与前文“只有一个答案”的唯一数量矛盾，是把它当成了“单个”来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动有多个只人报名参加。", "corrected_sentence": "这次活动有多个人报名参加。", "error_description": "“多个”后应直接接名词，不能再插入量词“只”。错误形式：多个只人；正确形式：多个人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有多个只爱好。", "corrected_sentence": "她有多个爱好。", "error_description": "“多个”后应直接接名词，不能再插入量词“只”。错误形式：多个只爱好；正确形式：多个爱好。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
