INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同父母（或同父、同母）而年纪比自己大的女子。", "primary_collocate": null, "pronunciation": "jiě jie", "ipa": "tɕjɛ˨˩ tɕjɛ", "syllable_count": 2, "sentences": [{"text": "我姐姐比我大三岁。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐今年上大学了，住在北京。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个姐姐和一个弟弟。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐给我买了一本新书。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的姐姐是医生，每天都很忙。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，姐姐常常带我去公园玩。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐结婚了，姐夫对她很好。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和姐姐的房间在二楼。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟哭了，姐姐一直哄他。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐比我高，也比我会唱歌。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "姐姐们", "label": "复数"}, {"form": "亲姐姐", "label": "复合"}], "register": "口语", "sense_fingerprint": "同父母的比自己年长的女性亲属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b584fe-81b3-45c5-b43f-c258eb988e16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "姐姐", "is_correct": true, "explanation": "“我___比我大三岁”中，主语是比我年长三岁的同父母女性亲属，“姐姐”符合句意。"}, {"text": "妹妹", "is_correct": false, "explanation": "语义：“妹妹”通常比我小，与“比我大三岁”矛盾。"}, {"text": "弟弟", "is_correct": false, "explanation": "语义：“弟弟”通常比我小，与“比我大三岁”矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“比我大三岁”的主语必须是有年龄的人，窗户不能这样用。"}], "explanations": {"姐姐": "“我___比我大三岁”中，主语是比我年长三岁的同父母女性亲属，“姐姐”符合句意。", "妹妹": "语义：“妹妹”通常比我小，与“比我大三岁”矛盾。", "弟弟": "语义：“弟弟”通常比我小，与“比我大三岁”矛盾。", "窗户": "配价：“比我大三岁”的主语必须是有年龄的人，窗户不能这样用。"}, "sentence_index": 0, "correct_answer": "姐姐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有一辆姐姐。", "explanation": "这里应该用〈个〉或〈位〉。“辆”用于车辆，指人不能用“辆”。"}, {"text": "我姐姐比我小三岁，还在上幼儿园。", "explanation": "这里应该用〈妹妹〉。姐姐比自己年长，比我小要说“妹妹”。"}, {"text": "我姐姐是男的，每天骑车去上班。", "explanation": "这里应该用〈哥哥〉。“姐姐”指女性，男性要说“哥哥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "姐姐", "is_correct": true, "explanation": "“___结婚了”需要一个能结婚的人，“姐姐”符合句意，“姐夫”也与之对应。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能结婚，句子不通。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能结婚，与句意不符。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“结婚”的主语必须是人，汽车不能作“结婚”的主语。"}], "explanations": {"姐姐": "“___结婚了”需要一个能结婚的人，“姐姐”符合句意，“姐夫”也与之对应。", "桌子": "语义：桌子不能结婚，句子不通。", "小猫": "语义：小猫是动物，不能结婚，与句意不符。", "汽车": "配价：“结婚”的主语必须是人，汽车不能作“结婚”的主语。"}, "sentence_index": 6, "correct_answer": "姐姐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有两只姐姐。", "explanation": "这里应该用〈个〉或〈位〉。“只”用于动物，指人要用“个”或“位”。"}, {"text": "我姐姐是我的奶奶，她已经七十岁了。", "explanation": "这里应该用〈奶奶〉。“姐姐”指同辈的女性，奶奶是长辈，不能这样称呼。"}, {"text": "我姐姐是我爸爸的哥哥，比我爸爸大两岁。", "explanation": "这里应该用〈伯伯〉。爸爸的哥哥是伯伯，不是同父母的姐姐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一个姐姐们。", "corrected_sentence": "我有一个姐姐。", "error_description": "“一个”表示单数，与表示复数的“们”矛盾，应去掉“们”。正确说法：我有一个姐姐。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我想去见一姐姐。", "corrected_sentence": "周末我想去见一个姐姐。", "error_description": "“一”后面要用量词“个”，不能直接接“姐姐”。正确说法：周末我想去见一个姐姐。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
