INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86272, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示让步，即使。", "primary_collocate": null, "pronunciation": "jiù suàn", "ipa": "tɕjoʊ̯˥˩ swan˥˩", "syllable_count": 2, "sentences": [{"text": "你就算跑得再快，也赶不上火车了。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他就算很忙，每天也会给妈妈打电话。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就算天气再冷，她也坚持晨跑。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事就算是真的，我也不会告诉别人。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就算下大雪，学校也照常上课。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师就算批评你，也是为你好。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就算价格很高，很多人也愿意买。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子就算不聪明，也要让他学会做人。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就算我有时间，也不想去那个地方。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他就算住在国外，也常常想念家乡。", "target_word": "就算", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示让步的连词，相当于“即使”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e8d354-ddd6-4efa-834f-8a0151ab3ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就算", "is_correct": true, "explanation": "“就算”表示让步，与“跑得再快，也赶不上”的句式相符。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“跑得再快”不能作为赶不上火车的理由，句意不通。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：“只有”要与“才”呼应，这里没有“才”，搭配不当。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”要与“就”呼应，且与“也赶不上”所表达的让步语气相冲突。"}], "explanations": {"就算": "“就算”表示让步，与“跑得再快，也赶不上”的句式相符。", "因为": "语义：“因为”表示原因，“跑得再快”不能作为赶不上火车的理由，句意不通。", "只有": "搭配：“只有”要与“才”呼应，这里没有“才”，搭配不当。", "只要": "搭配：“只要”要与“就”呼应，且与“也赶不上”所表达的让步语气相冲突。"}, "sentence_index": 0, "correct_answer": "就算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "就算这本书有趣，而且很有用。", "explanation": "这里应该用〈不仅〉。“不仅……而且……”表示递进，“就算”表示让步，不能与“而且”搭配。"}, {"text": "就算他没复习，所以考得不好。", "explanation": "这里应该用〈因为〉。“就算”表示让步，而这句说的是原因和结果，应使用“因为……所以……”。"}, {"text": "就算努力，才能成功。", "explanation": "这里应该用〈只有〉，与“才”呼应表示必要条件；“就算”表示让步，不能与“才”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就算", "is_correct": true, "explanation": "“就算”表示让步，与“很多人也愿意买”的让步语气呼应，语境相符。"}, {"text": "因而", "is_correct": false, "explanation": "语域：“因而”偏书面语，与这句口语化的表达不协调；且表示结果，与“也愿意买”矛盾。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，“价格很高”不会使人“愿意买”，逻辑矛盾。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“价格很高”导致“很多人愿意买”不合常理，与“也”的让步语气冲突。"}], "explanations": {"就算": "“就算”表示让步，与“很多人也愿意买”的让步语气呼应，语境相符。", "因而": "语域：“因而”偏书面语，与这句口语化的表达不协调；且表示结果，与“也愿意买”矛盾。", "因此": "语义：“因此”表示结果，“价格很高”不会使人“愿意买”，逻辑矛盾。", "所以": "语义：“所以”表示结果，“价格很高”导致“很多人愿意买”不合常理，与“也”的让步语气冲突。"}, "sentence_index": 6, "correct_answer": "就算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一边做饭，就算接电话。", "explanation": "这里应该用〈同时〉。“同时”表示两件事在同一时间进行，“就算”表示让步，不能用来并列两个动作。"}, {"text": "我们不是要放弃，就算是要调整。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示对比纠正，“就算”表示让步，不能用在对比句中。"}, {"text": "就算我们已经说好了，就不能改。", "explanation": "这里应该用〈既然〉。“既然”用于已经确定的事实作依据，“就算”表示假设性的让步，不能用于已经发生的事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "就算天气很冷，她就会坚持晨跑。", "corrected_sentence": "就算天气很冷，她也会坚持晨跑。", "error_description": "错误形式：主句用“就”。正确形式：主句用“也”。原因：让步句式“就算……，也……”中，主句应与“就算”呼应，用“也”；“就”表示顺承或时间，不能表示让步。正确：“就算天气很冷，她也会坚持晨跑。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "就算外面下雨，我们就要出发。", "corrected_sentence": "就算外面下雨，我们也要出发。", "error_description": "错误：主句用了“就”，应改为“也”，与“就算”呼应。“就要”表示即将，不能表示让步。正确：“就算外面下雨，我们也要出发。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
