INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“为人”是说一个人对别人怎么样，品行怎么样。", "primary_collocate": null, "pronunciation": "wéi rén", "ipa": "wei˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他为人很热情，大家都喜欢他。", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师为人认真，对学生也很好。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的邻居为人友好，常常帮助别人。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的为人不太诚实，我不想和他做朋友。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为人很安静，不爱说别人的坏话。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理为人公平，所以同事都相信他。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为人老实，从来不骗人。", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你觉得张明为人怎么样？", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶为人善良，村里的人都说她好。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的为人大方，请朋友吃饭从不小气。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "為人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为人：一个人的品行和待人的态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ad95ebb-2d68-48d2-a298-d9f392305c7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体形高矮胖瘦，不是品性，不能用“很热情”来形容。"}, {"text": "为人", "is_correct": true, "explanation": "正确：“为人”指一个人的品行和待人处世的态度，与“很热情”搭配。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不能与“口音”搭配。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”指受教育的程度，与待人的态度无关，“很热情”说不通。"}], "explanations": {"身材": "体貌：“身材”指体形高矮胖瘦，不是品性，不能用“很热情”来形容。", "为人": "正确：“为人”指一个人的品行和待人处世的态度，与“很热情”搭配。", "口音": "搭配：“热情”形容人的态度，不能与“口音”搭配。", "学历": "语义：“学历”指受教育的程度，与待人的态度无关，“很热情”说不通。"}, "sentence_index": 0, "correct_answer": "为人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的为人很健康，每天坚持跑步。", "explanation": "这里应该用〈身体〉。“为人”指品性和待人处世，不指身体状况；说身体好要用“身体”。"}, {"text": "他的为人很帅，很多女生喜欢他。", "explanation": "这里应该用〈外貌〉。“为人”不指长相，说长相帅要用“外貌”。"}, {"text": "他的为人很强，什么工作都能做。", "explanation": "这里应该用〈能力〉。“为人”说的是品行，不说办事本领，“很强，什么工作都能做”要用“能力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成绩", "is_correct": false, "explanation": "搭配：“老实”形容人的品性，不能用来形容“成绩”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，与“老实”不相关，后半句“从来不骗人”说的是品性。"}, {"text": "为人", "is_correct": true, "explanation": "正确：“为人”指品性，与“老实”和“从来不骗人”前后呼应。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能用来说人“老实”，前后意思说不通。"}], "explanations": {"成绩": "搭配：“老实”形容人的品性，不能用来形容“成绩”。", "年龄": "语义：“年龄”指岁数，与“老实”不相关，后半句“从来不骗人”说的是品性。", "为人": "正确：“为人”指品性，与“老实”和“从来不骗人”前后呼应。", "天气": "语义：“天气”是自然现象，不能用来说人“老实”，前后意思说不通。"}, "sentence_index": 6, "correct_answer": "为人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的为人读到博士，在大学教书。", "explanation": "这里应该用〈学历〉。“为人”指品性，不指受教育的程度；说读到博士要用“学历”。"}, {"text": "他的为人在班里最高，大家叫他大个子。", "explanation": "这里应该用〈身高〉。“为人”指品性，不指身体的高矮；说高矮要用“身高”。"}, {"text": "他的为人很多，住在大房子里。", "explanation": "这里应该用〈财富〉。“为人”不指钱财，说钱多要用“财富”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很佩服他为人。", "corrected_sentence": "我很佩服他的为人。", "error_description": "错误：“佩服”后面要接名词性的宾语，“他为人”不能作宾语，应加“的”，说“他的为人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地为人很好，大家都信任他。", "corrected_sentence": "他的为人很好，大家都信任他。", "error_description": "错误：修饰名词“为人”时应用“的”，不能用“地”。“地”用于修饰动词或形容词，应说“他的为人很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指一个人的品性和待人处世的态度。", "primary_collocate": null, "pronunciation": "wéi rén", "ipa": "wei˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "我们常说，一个人的为人比他的成绩更重要。", "target_word": "为人", "complexity_tier": "T3", "furigana": "wéi rén", "sentence_source": "generated"}, {"text": "我很喜欢她的为人。", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一个人，不但要看工作，也要看为人。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让我重新认识了他的为人。", "target_word": "为人", "complexity_tier": "T3", "furigana": "wéi rén", "sentence_source": "generated"}, {"text": "他的为人大家都知道，不会做那种事。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的为人很受学生尊敬。", "target_word": "为人", "complexity_tier": "T3", "furigana": "wéi rén", "sentence_source": "generated"}, {"text": "选朋友要看对方的为人，不能只看钱。", "target_word": "为人", "complexity_tier": "T3", "furigana": "wéi rén", "sentence_source": "generated"}, {"text": "我不太了解这个人的为人。", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的为人让大家都很放心。", "target_word": "为人", "complexity_tier": "T3", "furigana": "wéi rén", "sentence_source": "generated"}, {"text": "面试时，考官最看重的是应聘者的为人。", "target_word": "为人", "complexity_tier": "T3", "furigana": "wéi rén", "sentence_source": "generated"}], "morphological_forms": [{"form": "為人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为人：品性与待人处世的态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 考官 (Zipf 3.24), 看重 (Zipf 3.84), 应聘 (Zipf 3.68)']::text[], '3ad95ebb-2d68-48d2-a298-d9f392305c7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发型", "is_correct": false, "explanation": "语义：“发型”指头发的样式，与品性无关，不能用来和“成绩”比较重要性。"}, {"text": "为人", "is_correct": true, "explanation": "正确：“为人”是品性，符合“一个人的……比……更重要”的说法。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“比……更重要”的主体要是品性、能力一类的名词，“口音”不能这样比较。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”说的是身体的高矮，属于外表，不能用来比较品性与成绩的重要性。"}], "explanations": {"发型": "语义：“发型”指头发的样式，与品性无关，不能用来和“成绩”比较重要性。", "为人": "正确：“为人”是品性，符合“一个人的……比……更重要”的说法。", "口音": "搭配：“比……更重要”的主体要是品性、能力一类的名词，“口音”不能这样比较。", "身高": "体貌：“身高”说的是身体的高矮，属于外表，不能用来比较品性与成绩的重要性。"}, "sentence_index": 0, "correct_answer": "为人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的为人很英俊，很多女生喜欢他。", "explanation": "这里应该用〈相貌〉。“为人”指品性，不指长相；说长相英俊要用“相貌”。"}, {"text": "他的为人很丰富，见过很多世面。", "explanation": "这里应该用〈经历〉。“为人”指品性，不指见闻；说见过很多世面要用“经历”。"}, {"text": "他的为人很强，做事很快。", "explanation": "这里应该用〈能力〉。“为人”说品性，不说办事本领；“很强，做事很快”要用“能力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“体重”与选朋友无关，不能作为选择朋友时要看的内容。"}, {"text": "为人", "is_correct": true, "explanation": "正确：“为人”指品性，与“不能只看钱”形成对照，符合选朋友的标准。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”与选朋友无关，“看天气”不能作为选朋友的标准。"}, {"text": "发色", "is_correct": false, "explanation": "体貌：“发色”指头发的颜色，属于外表，不是选朋友时要看的品性。"}], "explanations": {"体重": "语义：“体重”与选朋友无关，不能作为选择朋友时要看的内容。", "为人": "正确：“为人”指品性，与“不能只看钱”形成对照，符合选朋友的标准。", "天气": "语义：“天气”与选朋友无关，“看天气”不能作为选朋友的标准。", "发色": "体貌：“发色”指头发的颜色，属于外表，不是选朋友时要看的品性。"}, "sentence_index": 6, "correct_answer": "为人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的为人很高，买了一套大房子。", "explanation": "这里应该用〈收入〉。“为人”指品性，不指钱的多少；说收入高要用“收入”。"}, {"text": "他的为人很好听，大家都爱听他唱歌。", "explanation": "这里应该用〈声音〉。“为人”不说好听；“很好听”形容的是声音，要用“声音”。"}, {"text": "他的为人很快，跑步总是第一名。", "explanation": "这里应该用〈速度〉。“为人”说的是品性，不说快慢；“很快”形容速度，要用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板很看重员工为人。", "corrected_sentence": "老板很看重员工的为人。", "error_description": "错误：“员工为人”前缺少“的”，不能作“看重”的宾语。应说“员工的为人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地为人很可靠，我们都愿意和他合作。", "corrected_sentence": "他的为人很可靠，我们都愿意和他合作。", "error_description": "错误：修饰名词“为人”时应用“的”，不能用“地”。“地”用于修饰动词或形容词，应说“他的为人很可靠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
