INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "往往是说常常是这样。", "primary_collocate": null, "pronunciation": "wǎng wǎng", "ipa": "wɑŋ˨˩ wɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "他往往最后一个到教室。", "target_word": "往往", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好朋友之间，往往不用说太多话。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日的公园往往人很多。", "target_word": "往往", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事太快，往往容易出错。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥晚上往往在家看书。", "target_word": "往往", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后的天空往往特别蓝。", "target_word": "往往", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "带孩子去书店，他往往不想走。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天这里的早上往往有点冷。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次做的菜，往往不太好吃。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习语言时，我们往往怕说错。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "常常是这样，说明一般情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487a10cd-ac34-420d-b7b4-50a652b0befc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "往往", "is_correct": true, "explanation": "往往：表示经常如此，与“他最后一个到教室”这种习惯性情况相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，而“到”表示到达这一结果，两者不能搭配。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示立刻发生，与“最后一个到”这种先后顺序说法不搭配。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示紧接着发生，与“最后一个到”所表达的先后顺序相矛盾。"}], "explanations": {"往往": "往往：表示经常如此，与“他最后一个到教室”这种习惯性情况相符。", "正在": "体貌：“正在”表示动作进行中，而“到”表示到达这一结果，两者不能搭配。", "马上": "搭配：“马上”表示立刻发生，与“最后一个到”这种先后顺序说法不搭配。", "立刻": "语义：“立刻”表示紧接着发生，与“最后一个到”所表达的先后顺序相矛盾。"}, "sentence_index": 0, "correct_answer": "往往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那天下午往往下起了大雨。", "explanation": "这里应该用〈突然〉。往往表示经常出现的情况，不能用来说某一天下午发生的一次性事件。"}, {"text": "我往往在这里住过三年。", "explanation": "这里应该用〈曾经〉。往往表示经常，不能用来描述过去一段时间里发生过一次的经历。"}, {"text": "下个月他往往去上海出差。", "explanation": "这里应该用〈必定〉。往往只描述经常出现的情况，不能用来断定某个未来的一次性安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "往往", "is_correct": true, "explanation": "往往：表示经常如此，与“带孩子去书店，他不想走”这种习惯相符。"}, {"text": "即将", "is_correct": false, "explanation": "体貌：“即将”表示即将发生的动作，而“不想走”是心理状态，不能用“即将”修饰。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“往往”所说的经常如此相反。"}, {"text": "猛地", "is_correct": false, "explanation": "搭配：“猛地”多修饰突然发生的动作，与“不想走”这类心理状态不搭配。"}], "explanations": {"往往": "往往：表示经常如此，与“带孩子去书店，他不想走”这种习惯相符。", "即将": "体貌：“即将”表示即将发生的动作，而“不想走”是心理状态，不能用“即将”修饰。", "偶尔": "语义：“偶尔”表示不常发生，与“往往”所说的经常如此相反。", "猛地": "搭配：“猛地”多修饰突然发生的动作，与“不想走”这类心理状态不搭配。"}, "sentence_index": 6, "correct_answer": "往往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二加二往往等于四。", "explanation": "这里应该用〈总是〉。往往表示经常但不一定如此，不能用来说明必然的数学结论。"}, {"text": "请往往带上护照！", "explanation": "这里应该用〈务必〉。往往是描述习惯的副词，不能用于提醒或命令别人做某件事。"}, {"text": "这座城市往往是我的家。", "explanation": "这里应该用〈一直〉。往往表示经常出现的情况，不能用来说明地方与人之间长期不变的关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种人的往往很小心。", "corrected_sentence": "这种人往往很小心。", "error_description": "错误形式：“人的往往”；正确形式：“人往往”。“往往”是副词，不能在前面加“的”变成名词性成分，也不能加“的”作定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每年这时候，这里很往往下雨。", "corrected_sentence": "每年这时候，这里往往下雨。", "error_description": "错误形式：“很往往”；正确形式：“往往下雨”。“很”不能修饰副词“往往”，应直接用“往往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
