INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86280, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示某种情况经常出现。", "primary_collocate": null, "pronunciation": "wǎng wǎng", "ipa": "wɑŋ˨˩ wɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "周末我往往睡到十点才起床。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，路上往往会堵车。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气时，往往一句话也不说。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们往往喜欢吃甜的东西。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，这里的游客往往特别多。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人早上往往起得很早。", "target_word": "往往", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试以前，他往往紧张得睡不着。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在海边的人往往爱吃海鲜。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越着急，事情往往越做不好。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人往往不太注意身体。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示某种情况经常出现的规律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487a10cd-ac34-420d-b7b4-50a652b0befc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "往往", "is_correct": true, "explanation": "往往：表示经常如此，与“周末睡到十点才起床”这种习惯相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，不能与“睡到十点才起床”这种结果性说法搭配。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示立即发生，与“睡到十点才起床”的延后说法不搭配。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示紧接着发生的一次性事件，与“周末”反复出现的习惯不符。"}], "explanations": {"往往": "往往：表示经常如此，与“周末睡到十点才起床”这种习惯相符。", "正在": "体貌：“正在”表示动作正在进行，不能与“睡到十点才起床”这种结果性说法搭配。", "马上": "搭配：“马上”表示立即发生，与“睡到十点才起床”的延后说法不搭配。", "立刻": "语义：“立刻”表示紧接着发生的一次性事件，与“周末”反复出现的习惯不符。"}, "sentence_index": 0, "correct_answer": "往往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天晚上往往停电了。", "explanation": "这里应该用〈突然〉。往往表示经常出现的情况，不能用来说昨天晚上这样的一次性事件。"}, {"text": "我往往去过一次北京。", "explanation": "这里应该用〈曾经〉。往往表示经常，与“一次”矛盾；说过去做过的事要用〈曾经〉。"}, {"text": "明天他往往来。", "explanation": "这里应该用〈一定〉。往往只描述经常出现的情况，不能用来断定某个未来的一次性安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "往往", "is_correct": true, "explanation": "往往：表示经常出现，与“考试以前紧张得睡不着”的常见情况相符。"}, {"text": "当场", "is_correct": false, "explanation": "语义：“当场”指就在事情发生的当时，与“考试以前”这个时间不相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“往往”所说的常见情况相反。"}, {"text": "猛地", "is_correct": false, "explanation": "搭配：“猛地”多修饰突然发生的动作，不说“猛地紧张得睡不着”这种逐渐形成的状态。"}], "explanations": {"往往": "往往：表示经常出现，与“考试以前紧张得睡不着”的常见情况相符。", "当场": "语义：“当场”指就在事情发生的当时，与“考试以前”这个时间不相符。", "偶尔": "语义：“偶尔”表示不常发生，与“往往”所说的常见情况相反。", "猛地": "搭配：“猛地”多修饰突然发生的动作，不说“猛地紧张得睡不着”这种逐渐形成的状态。"}, "sentence_index": 6, "correct_answer": "往往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球往往绕着太阳转。", "explanation": "这里应该用〈总是〉。往往表示经常但不一定如此，不能用来陈述绝对的事实。"}, {"text": "请你往往早点来！", "explanation": "这里应该用〈务必〉。往往是描述习惯的副词，不能用于提醒或要求别人做某件事。"}, {"text": "我的弟弟往往是个大学生。", "explanation": "这里应该用〈一直〉。往往表示经常出现的情况，不能用来说明人的身份或长期不变的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐会往往十点睡觉。", "corrected_sentence": "我姐姐往往十点睡觉。", "error_description": "错误形式：“会往往十点睡觉”；正确形式：“往往十点睡觉”。“会”不能放在副词“往往”之前，删去“会”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个季节这里很往往下雨。", "corrected_sentence": "这个季节这里往往下雨。", "error_description": "错误形式：“很往往”；正确形式：“往往下雨”。“很”只能修饰形容词或部分心理动词，不能修饰副词“往往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
