INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86287, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作品是人用心做出来的画、歌、书等东西。", "primary_collocate": null, "pronunciation": "zuò pǐn", "ipa": "tswo˥˩ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是我自己画的作品。", "target_word": "作品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌是他最好的作品。", "target_word": "作品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们的作品都贴在墙上。", "target_word": "作品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花了三年才完成这部作品。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是那位作家的第一部作品。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看他的全部作品。", "target_word": "作品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能给我介绍一下你的作品吗？", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画展上的每件作品都有名字。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作品很受年轻人欢迎。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸我的作品很有想法。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "部", "label": "量词"}, {"form": "文学作品", "label": "复合"}, {"form": "艺术作品", "label": "复合"}], "register": "中性", "sense_fingerprint": "作品：人用心做出来的画、歌、书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ad95ebb-2d68-48d2-a298-d9f392305c7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作品", "is_correct": true, "explanation": "“自己画的作品”指自己画出来的艺术成果，搭配自然。"}, {"text": "照片", "is_correct": false, "explanation": "语义：“照片”是拍出来的，不是画出来的，句中的“画的”说不通。"}, {"text": "面条", "is_correct": false, "explanation": "搭配：“画”不能搭配“面条”，句中要指可以画出来的成果。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“画的”只能用于画出来的东西，不能说“画的歌曲”。"}], "explanations": {"作品": "“自己画的作品”指自己画出来的艺术成果，搭配自然。", "照片": "语义：“照片”是拍出来的，不是画出来的，句中的“画的”说不通。", "面条": "搭配：“画”不能搭配“面条”，句中要指可以画出来的成果。", "歌曲": "搭配：“画的”只能用于画出来的东西，不能说“画的歌曲”。"}, "sentence_index": 0, "correct_answer": "作品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每天生产很多作品，都是用来点火的。", "explanation": "这里应该用〈火柴〉。“作品”指文艺成果，用来点火的东西要用“火柴”。"}, {"text": "他花了三年才把这座大桥的作品修完。", "explanation": "这里应该用〈工程〉。“作品”指创作的文艺成果，建造大桥这类工程要用“工程”。"}, {"text": "这种作品一天吃三次。", "explanation": "这里应该用〈药品〉。“作品”不能用来指要服用的东西，服用的要用“药品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作品", "is_correct": true, "explanation": "“介绍一下你的作品”指介绍你创作的成果，搭配自然。"}, {"text": "电压", "is_correct": false, "explanation": "语义：“电压”是电的数值，不是可以介绍的对象，句中语义不合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的数值，不是创作的成果，句中语义不合。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”指走路的动作，不能作为可以介绍的创作对象。"}], "explanations": {"作品": "“介绍一下你的作品”指介绍你创作的成果，搭配自然。", "电压": "语义：“电压”是电的数值，不是可以介绍的对象，句中语义不合。", "体重": "语义：“体重”是身体的数值，不是创作的成果，句中语义不合。", "脚步": "语义：“脚步”指走路的动作，不能作为可以介绍的创作对象。"}, "sentence_index": 6, "correct_answer": "作品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的作品很忙，常常加班。", "explanation": "这里应该用〈工作〉。“作品”指文艺成果，说人的职业、忙碌要用“工作”。"}, {"text": "那位作品天天写作，很努力。", "explanation": "这里应该用〈作家〉。“作品”指成果，不能指写作的人，写作、努力的主体要用“作家”。"}, {"text": "这种药的作品很大。", "explanation": "这里应该用〈作用〉。“作品”指创作成果，药物产生的效果要用“作用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的第一只作品已经出版了。", "corrected_sentence": "我的第一部作品已经出版了。", "error_description": "“只”多用于动物或成对的东西，书籍这类作品应用量词“部”，应说“第一部作品”，不能说“第一只作品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我作品很有想法，老师很满意。", "corrected_sentence": "我的作品很有想法，老师很满意。", "error_description": "“作品”前作定语表示所属时要加“的”，应说“我的作品”，不能说“我作品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
