INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时刻是一个很短的时间点。", "primary_collocate": null, "pronunciation": "shí kè", "ipa": "ʂɻ̩˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这是我一生中最难忘的时刻。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后的时刻，他把球踢进了球门。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息的那个时刻，她高兴得哭了。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关键时刻，他站出来帮了大家。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子出生的时刻，爸爸一直在医院里。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个幸福的时刻，我们等了很久。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车开动的时刻，妈妈在窗外挥着手。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相机拍下了那个美好的时刻。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在危险的时刻，朋友没有离开他。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟声响起的时刻，大家一起唱起了歌。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "時刻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某件事发生的那一个短暂的时间点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e8d354-ddd6-4efa-834f-8a0151ab3ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86289, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时刻", "is_correct": true, "explanation": "“时刻”指某个具体的时间点，可以被“一生中最难忘的”修饰，句意通顺。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“难忘”修饰经历或事件，不能修饰“方向”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的数值，与“一生中最难忘的”所指的经历不相符。"}, {"text": "数量", "is_correct": false, "explanation": "语义：“数量”是抽象的多少，与“一生中最难忘的”所指的经历不相符。"}], "explanations": {"时刻": "“时刻”指某个具体的时间点，可以被“一生中最难忘的”修饰，句意通顺。", "方向": "搭配：“难忘”修饰经历或事件，不能修饰“方向”。", "体重": "语义：“体重”是身体的数值，与“一生中最难忘的”所指的经历不相符。", "数量": "语义：“数量”是抽象的多少，与“一生中最难忘的”所指的经历不相符。"}, "sentence_index": 0, "correct_answer": "时刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在农村住了一个时刻。", "explanation": "这里应该用〈时期〉。“时刻”只是时间点，不能表示在农村居住这样一段时期。"}, {"text": "我们生活在信息时刻。", "explanation": "这里应该用〈时代〉。“时代”指较长的历史阶段，“时刻”只是一个时间点，不能指一个时代。"}, {"text": "我永远记得那一条时刻。", "explanation": "这里应该用〈个〉。“时刻”用“个”计量，“条”用于细长的东西，不能用来计量“时刻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86289, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时刻", "is_correct": true, "explanation": "“时刻”指某个时间点，与“火车开动的”搭配，表示火车开动的那一刻。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：“颜色”是外观特征，不能与“开动”这一动作搭配。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，不能表示一个动作发生的时间点，句意不通。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“座位”不能作为“开动”的对象，与动词搭配不当。"}], "explanations": {"时刻": "“时刻”指某个时间点，与“火车开动的”搭配，表示火车开动的那一刻。", "颜色": "体貌：“颜色”是外观特征，不能与“开动”这一动作搭配。", "重量": "语义：“重量”指物体的轻重，不能表示一个动作发生的时间点，句意不通。", "座位": "搭配：“座位”不能作为“开动”的对象，与动词搭配不当。"}, "sentence_index": 6, "correct_answer": "时刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几年时刻过得很快。", "explanation": "这里应该用〈时间〉。“时间”可以“过得很快”，表示时光的流逝；“时刻”只是某个时间点，不能表示时光流逝。"}, {"text": "这节课的时刻是两个小时。", "explanation": "这里应该用〈时长〉。“时长”表示持续的长度，“时刻”只是时间点，不能用来表示时间的长短。"}, {"text": "他等了一时刻才上车。", "explanation": "这里应该用〈一刻〉（一刻钟）。“时刻”不能直接与数词“一”组合表示一段时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那是一只难忘的时刻。", "corrected_sentence": "那是一个难忘的时刻。", "error_description": "错误：量词用了“只”。“只”多用于动物或成对的东西，“时刻”应用“个”计量。正确：“一个难忘的时刻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一起度过了美好地时刻。", "corrected_sentence": "我们一起度过了美好的时刻。", "error_description": "错误：修饰名词“时刻”时用了“地”。“地”用于修饰动词，名词前的修饰语应用“的”。正确：“美好的时刻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
