INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个时间点；也指一段时间。", "primary_collocate": null, "pronunciation": "shí kè", "ipa": "ʂɻ̩˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "飞机起飞的时刻是下午三点。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你到达的具体时刻。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在最困难的时刻，家人一直陪着我。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些艰难的时刻，我永远不会忘记。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试期间是学生最紧张的时刻。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车的出发时刻写在车票上。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤独的时刻，他喜欢听音乐。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在不是休息的时刻，大家继续工作。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有想家的时刻。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个时刻，整个城市都安静下来了。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "時刻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "具体的时间点，或指某一段特定的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e8d354-ddd6-4efa-834f-8a0151ab3ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时刻", "is_correct": true, "explanation": "“时刻”指一个具体的时间点，与“下午三点”对应，句意通顺。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”指空间位置，不能是“下午三点”这样的时间。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能与“下午三点”对应。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：“颜色”是外观特征，不能与“下午三点”对应。"}], "explanations": {"时刻": "“时刻”指一个具体的时间点，与“下午三点”对应，句意通顺。", "地点": "语义：“地点”指空间位置，不能是“下午三点”这样的时间。", "价格": "语义：“价格”指钱数，不能与“下午三点”对应。", "颜色": "体貌：“颜色”是外观特征，不能与“下午三点”对应。"}, "sentence_index": 0, "correct_answer": "时刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我永远记得那一块时刻。", "explanation": "这里应该用〈个〉。“块”用于成块的东西，不能用来计量“时刻”。"}, {"text": "我在售票处买了一张时刻。", "explanation": "这里应该用〈时刻表〉。“时刻”不能指写着列车或车次时间的表格，应说“时刻表”。"}, {"text": "在春秋时刻，各国常常打仗。", "explanation": "这里应该用〈时代〉。“时代”指较长的历史阶段，“春秋”是历史时代的名称，不能说“春秋时刻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时刻", "is_correct": true, "explanation": "“时刻”指一个时间点，可以与“孤独的”修饰的时段相配，句意通顺。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的数值，不能用“孤独的”来修饰。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“孤独”不能修饰“速度”，搭配不当。"}, {"text": "号码", "is_correct": false, "explanation": "语义：“号码”与“孤独”无关，句意不通。"}], "explanations": {"时刻": "“时刻”指一个时间点，可以与“孤独的”修饰的时段相配，句意通顺。", "体温": "语义：“体温”是身体的数值，不能用“孤独的”来修饰。", "速度": "搭配：“孤独”不能修饰“速度”，搭配不当。", "号码": "语义：“号码”与“孤独”无关，句意不通。"}, "sentence_index": 6, "correct_answer": "时刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "假期的时刻过得很快。", "explanation": "这里应该用〈时间〉。“时间”表示时光的流逝，可以“过得很快”；“时刻”不能表示时光的流逝。"}, {"text": "他等了一时刻钟才上车。", "explanation": "这里应该用〈一刻钟〉。“时刻”不能与“钟”直接组合表示时长，应说“一刻钟”。"}, {"text": "我把书时刻在桌上。", "explanation": "这里应该用〈放〉。“时刻”是名词或副词，不能作动词表示放置，应说“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火车的到站时刻了是晚上八点。", "corrected_sentence": "火车的到站时刻是晚上八点。", "error_description": "错误：“时刻”后多加了“了”。“时刻”是名词，后面不能直接加“了”。正确：“火车的到站时刻是晚上八点。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是他人生中了重要时刻。", "corrected_sentence": "这是他人生中的重要时刻。", "error_description": "错误：修饰语“重要”与“时刻”之间的“的”误写为“了”。“了”是体标，不能放在修饰语和名词之间。正确：“这是他人生中的重要时刻。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3af8b60a-08ea-418c-a48d-e16085472e28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
