INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“台”是比地面高一点、可以站在上面的地方。", "primary_collocate": null, "pronunciation": "tái", "ipa": "tʰaɪ̯˧˥", "syllable_count": 1, "sentences": [{"text": "他站在台上，大家都看着他。", "target_word": "台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台下堆着几只旧木箱。", "target_word": "台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友走上台，伸手去够树上的果子。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个台很高，小孩自己上不去。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从台上跳了下来。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台上的雪还没化，踩上去很滑。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让他走到台前，说几句话。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在台边坐下，看着远处的山。", "target_word": "台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爬上台，高兴地跳起来。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台上有风，站久了有点冷。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "臺", "label": "繁体"}, {"form": "台阶", "label": "复合"}], "register": "中性", "sense_fingerprint": "比地面高的平地，人可以站或坐在上面，常与台上、台边连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 伸手 (Zipf 3.8), 树上 (Zipf 3.82), 果子 (Zipf 3.45)']::text[], 'c83067b8-a588-41b5-ab44-79eb0cbc0896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "台", "is_correct": true, "explanation": "台（tái）指比地面高、可以站上去的平台，是正确答案。"}, {"text": "太", "is_correct": false, "explanation": "tài（第四声）与 tái（第二声）声调不同，意思是“太”。"}, {"text": "胎", "is_correct": false, "explanation": "tāi（第一声）与 tái（第二声）声调不同，意思是“胎”。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 tái 韵母不同（an 与 ai），意思是“谈”。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tái 韵母不同（ang 与 ai），意思是“糖”。"}], "explanations": {"台": "台（tái）指比地面高、可以站上去的平台，是正确答案。", "太": "tài（第四声）与 tái（第二声）声调不同，意思是“太”。", "胎": "tāi（第一声）与 tái（第二声）声调不同，意思是“胎”。", "谈": "tán 与 tái 韵母不同（an 与 ai），意思是“谈”。", "糖": "táng 与 tái 韵母不同（ang 与 ai），意思是“糖”。"}, "sentence_index": null, "correct_answer": "台"}, "level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "“台”指高出地面、可以站立的平面，符合“站在……上”的语境。"}, {"text": "烟", "is_correct": false, "explanation": "语义：烟无法承托人站立，句意不通。"}, {"text": "雾", "is_correct": false, "explanation": "语义：雾无法承托人站立，“站在雾上”句意不通。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子只是光线投下的暗区，承托不了人站立，句意不通。"}], "explanations": {"台": "“台”指高出地面、可以站立的平面，符合“站在……上”的语境。", "烟": "语义：烟无法承托人站立，句意不通。", "雾": "语义：雾无法承托人站立，“站在雾上”句意不通。", "影子": "语义：影子只是光线投下的暗区，承托不了人站立，句意不通。"}, "sentence_index": 0, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我和朋友去俱乐部打台。", "explanation": "这里应该用〈台球〉。台指比地面高、可以站上去的平面，不能单独指打的台球。"}, {"text": "我去台办手续，窗口的人很热情。", "explanation": "这里应该用〈柜台〉。台不能单独指办理业务的柜台，办手续要说柜台。"}, {"text": "昨晚台掠过海面，渔船都回了港。", "explanation": "这里应该用〈台风〉。台指比地面高、可以站上去的平面，不能单独指台风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "台", "is_correct": true, "explanation": "台（tái）指比地面高、可以站上去的平台，是正确答案。"}, {"text": "态", "is_correct": false, "explanation": "tài（第四声）与 tái（第二声）声调不同，意思是“态”。"}, {"text": "坛", "is_correct": false, "explanation": "tán 与 tái 韵母不同（an 与 ai），意思是“坛”。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tái 韵母不同（ang 与 ai），意思是“堂”。"}], "explanations": {"台": "台（tái）指比地面高、可以站上去的平台，是正确答案。", "态": "tài（第四声）与 tái（第二声）声调不同，意思是“态”。", "坛": "tán 与 tái 韵母不同（an 与 ai），意思是“坛”。", "堂": "táng 与 tái 韵母不同（ang 与 ai），意思是“堂”。"}, "sentence_index": null, "correct_answer": "台"}, "level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "“台”指可以站立的高处，“走到台前”指走到台的前方，符合语境。"}, {"text": "柱", "is_correct": false, "explanation": "语义：柱子听不了人讲话，“说几句话”需要面对听众，句意不通。"}, {"text": "雾", "is_correct": false, "explanation": "搭配：“走到……前”要求有实体可以走近的地方，不能说走到雾前。"}, {"text": "泡沫", "is_correct": false, "explanation": "语义：泡沫不是可以走过去、并让人面对听众讲话的地方，句意不通。"}], "explanations": {"台": "“台”指可以站立的高处，“走到台前”指走到台的前方，符合语境。", "柱": "语义：柱子听不了人讲话，“说几句话”需要面对听众，句意不通。", "雾": "搭配：“走到……前”要求有实体可以走近的地方，不能说走到雾前。", "泡沫": "语义：泡沫不是可以走过去、并让人面对听众讲话的地方，句意不通。"}, "sentence_index": 6, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台过境后，街上到处是落叶。", "explanation": "这里应该用〈台风〉。台指比地面高、可以站上去的平面，不能单独指台风。"}, {"text": "他把台背得很熟。", "explanation": "这里应该用〈台词〉。台指可以站上去的平面，演员要背的台词不能说台。"}, {"text": "孩子们一步一个台地往上走。", "explanation": "这里应该用〈台阶〉。台指比地面高的平台，一级一级的踏步要说台阶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "广场中间有一只台，很高。", "corrected_sentence": "广场中间有一个台，很高。", "error_description": "错误形式：“一只台”；正确形式：“一个台”。“只”是动物的量词，台应该用“个”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他走到台里，大家都停下来看他。", "corrected_sentence": "他走到台上，大家都停下来看他。", "error_description": "错误形式：“台里”；正确形式：“台上”。平台是可以站上去的平面，表示位置要用“上”，“里”表示容器的内部。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
