INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86292, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高出地面的平面，如舞台、讲台；也指桌子一类的东西。", "primary_collocate": null, "pronunciation": "tái", "ipa": "tʰaɪ̯˧˥", "syllable_count": 1, "sentences": [{"text": "演员在台上唱了一个小时的歌。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台下的观众都在鼓掌。", "target_word": "台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师站在台上，给大家讲课。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次站在台上，手一直在发抖。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台上放着一瓶花，很好看。", "target_word": "台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把书放在台上，走出了教室。", "target_word": "台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位歌手在台上向大家鞠躬。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台上的灯一亮，音乐就响了。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把粉笔放回台上了。", "target_word": "台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主持人走到台中间，笑着说话。", "target_word": "台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "臺", "label": "繁体"}, {"form": "舞台", "label": "复合"}, {"form": "讲台", "label": "复合"}], "register": "中性", "sense_fingerprint": "舞台、讲台一类供表演或讲课的平面，也指可以放东西的台面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c83067b8-a588-41b5-ab44-79eb0cbc0896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86292, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "台", "is_correct": true, "explanation": "台（tái）指舞台、讲台一类供表演或讲课的平面，是正确答案。"}, {"text": "太", "is_correct": false, "explanation": "tài（第四声）与 tái（第二声）声调不同，意思是“太”。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 tái 韵母不同（an 与 ai），意思是“谈”。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tái 韵母不同（ang 与 ai），意思是“糖”。"}], "explanations": {"台": "台（tái）指舞台、讲台一类供表演或讲课的平面，是正确答案。", "太": "tài（第四声）与 tái（第二声）声调不同，意思是“太”。", "谈": "tán 与 tái 韵母不同（an 与 ai），意思是“谈”。", "糖": "táng 与 tái 韵母不同（ang 与 ai），意思是“糖”。"}, "sentence_index": null, "correct_answer": "台"}, "level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "“台”指舞台这样供表演的平面，演员在台上唱歌，符合语境。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸面承受不了人站着唱歌，句意不通。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃面站不住一个人长时间唱歌，场景不成立。"}, {"text": "泥", "is_correct": false, "explanation": "搭配：“在……上唱歌”要求可以站稳表演的平面，不说在泥上表演。"}], "explanations": {"台": "“台”指舞台这样供表演的平面，演员在台上唱歌，符合语境。", "纸": "语义：纸面承受不了人站着唱歌，句意不通。", "玻璃": "语义：玻璃面站不住一个人长时间唱歌，场景不成立。", "泥": "搭配：“在……上唱歌”要求可以站稳表演的平面，不说在泥上表演。"}, "sentence_index": 0, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天台过境，学校停了一天课。", "explanation": "这里应该用〈台风〉。台指舞台、讲台一类供表演或讲课的平面，不能单独指台风。"}, {"text": "书桌上的台很亮，他看书看了很久。", "explanation": "这里应该用〈台灯〉。台指高出地面的平面，不能单独指发光的台灯。"}, {"text": "他从小就喜欢打台，每周都练。", "explanation": "这里应该用〈台球〉。台指高出地面的平面，打的球类要说台球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86292, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "台", "is_correct": true, "explanation": "台（tái）指舞台、讲台一类供表演或讲课的平面，是正确答案。"}, {"text": "态", "is_correct": false, "explanation": "tài（第四声）与 tái（第二声）声调不同，意思是“态”。"}, {"text": "坛", "is_correct": false, "explanation": "tán 与 tái 韵母不同（an 与 ai），意思是“坛”。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tái 韵母不同（ang 与 ai），意思是“堂”。"}], "explanations": {"台": "台（tái）指舞台、讲台一类供表演或讲课的平面，是正确答案。", "态": "tài（第四声）与 tái（第二声）声调不同，意思是“态”。", "坛": "tán 与 tái 韵母不同（an 与 ai），意思是“坛”。", "堂": "táng 与 tái 韵母不同（ang 与 ai），意思是“堂”。"}, "sentence_index": null, "correct_answer": "台"}, "level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "“台”指舞台，歌手在台上向大家鞠躬，符合语境。"}, {"text": "床", "is_correct": false, "explanation": "语义：床不是面向大家鞠躬的地方，句意不通。"}, {"text": "雾", "is_correct": false, "explanation": "搭配：雾上不能站人，“在……上”不搭配雾。"}, {"text": "泡沫", "is_correct": false, "explanation": "语义：泡沫承受不了人站立并做鞠躬的动作，场景不成立。"}], "explanations": {"台": "“台”指舞台，歌手在台上向大家鞠躬，符合语境。", "床": "语义：床不是面向大家鞠躬的地方，句意不通。", "雾": "搭配：雾上不能站人，“在……上”不搭配雾。", "泡沫": "语义：泡沫承受不了人站立并做鞠躬的动作，场景不成立。"}, "sentence_index": 6, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台来的时候，窗户一直在响。", "explanation": "这里应该用〈台风〉。台指高出地面的平面，不能单独指台风。"}, {"text": "导演让他把台改得更口语化。", "explanation": "这里应该用〈台词〉。台指高出地面的平面，演员说的台词不能说台。"}, {"text": "观众坐在台上看比赛，视野很好。", "explanation": "这里应该用〈看台〉。台指舞台、讲台一类的平面，观众席要说看台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演员站在台里，向观众挥手。", "corrected_sentence": "演员站在台上，向观众挥手。", "error_description": "错误形式：“台里”；正确形式：“台上”。舞台是可以站上去的平面，表示位置要用“上”，不用“里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "房间中间摆着一条台，上面放着花。", "corrected_sentence": "房间中间摆着一个台，上面放着花。", "error_description": "错误形式：“一条台”；正确形式：“一个台”。“条”用于细长的东西，台应该用“个”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e947a890-4459-4a90-a91e-5f7a538c30d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
