INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86298, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠近陆地的大片咸水水域。", "primary_collocate": null, "pronunciation": "hǎi", "ipa": "xaɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我家离海很近，走十分钟就到。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的东边是海。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很多人去海里玩。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的房子对着海。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海的那边是另一个国家。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把小船开到了海中间。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山的前面是海，后面是树林。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天风很大，海一直在响。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市三面是山，一面是海。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢看着海，不想说话。", "target_word": "海", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大海", "label": "复合"}, {"form": "海水", "label": "复合"}, {"form": "海边", "label": "复合"}], "register": "中性", "sense_fingerprint": "靠近陆地的大片咸水水域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc80c1b1-8ff1-4e63-afc6-b13565b16d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86298, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海", "is_correct": true, "explanation": "正确答案：海 hǎi，意思是靠近陆地的大片咸水水域。"}, {"text": "好", "is_correct": false, "explanation": "好 hǎo 与 hǎi 韵母不同（ao 与 ai），意思是好。"}, {"text": "买", "is_correct": false, "explanation": "买 mǎi 与 hǎi 声母不同（m 与 h），意思是购买。"}, {"text": "奶", "is_correct": false, "explanation": "奶 nǎi 与 hǎi 声母不同（n 与 h），意思是奶。"}, {"text": "嗨", "is_correct": false, "explanation": "嗨 hāi 与 hǎi 声调不同（第一声），是打招呼时的口语词。"}], "explanations": {"海": "正确答案：海 hǎi，意思是靠近陆地的大片咸水水域。", "好": "好 hǎo 与 hǎi 韵母不同（ao 与 ai），意思是好。", "买": "买 mǎi 与 hǎi 声母不同（m 与 h），意思是购买。", "奶": "奶 nǎi 与 hǎi 声母不同（n 与 h），意思是奶。", "嗨": "嗨 hāi 与 hǎi 声调不同（第一声），是打招呼时的口语词。"}, "sentence_index": null, "correct_answer": "海"}, "level_3": {"options": [{"text": "海", "is_correct": true, "explanation": "“离海很近，走十分钟就到”说的是离海岸很近，符合句意。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不是“离家很近”的地点，句子说不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是地点，“离作业很近”说不通。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“离……很近”后面要接地点，“饭”不是地点，不能搭配。"}], "explanations": {"海": "“离海很近，走十分钟就到”说的是离海岸很近，符合句意。", "猫": "语义：猫不是“离家很近”的地点，句子说不通。", "作业": "语义：作业不是地点，“离作业很近”说不通。", "饭": "搭配：“离……很近”后面要接地点，“饭”不是地点，不能搭配。"}, "sentence_index": 0, "correct_answer": "海"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们住的房子对着一座海。", "explanation": "这里应该用〈片〉。“海”的量词用“片”，“座”用于山、楼房等，不用于海。"}, {"text": "我们在餐厅吃了一顿海，很便宜。", "explanation": "这里应该用〈海鲜〉。“海”不能单独指海产品，吃海产品要说“海鲜”。"}, {"text": "我的姐姐去海留学了。", "explanation": "这里应该用〈海外〉。“海”单独不能指国外，出国留学要说“海外”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86298, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海", "is_correct": true, "explanation": "正确答案：海 hǎi，意思是靠近陆地的大片咸水水域。"}, {"text": "孩", "is_correct": false, "explanation": "孩 hái 与 hǎi 声调不同（第二声），意思是孩子。"}, {"text": "喊", "is_correct": false, "explanation": "喊 hǎn 与 hǎi 韵母不同（an 与 ai），意思是大声叫。"}, {"text": "害", "is_correct": false, "explanation": "害 hài 与 hǎi 声调不同（第四声），意思是伤害。"}], "explanations": {"海": "正确答案：海 hǎi，意思是靠近陆地的大片咸水水域。", "孩": "孩 hái 与 hǎi 声调不同（第二声），意思是孩子。", "喊": "喊 hǎn 与 hǎi 韵母不同（an 与 ai），意思是大声叫。", "害": "害 hài 与 hǎi 声调不同（第四声），意思是伤害。"}, "sentence_index": null, "correct_answer": "海"}, "level_3": {"options": [{"text": "海", "is_correct": true, "explanation": "“山的前面是海，后面是树林”描述的是海岸地形，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是地形，“山的前面是桌子”与句意不符。"}, {"text": "鸡", "is_correct": false, "explanation": "语义：鸡不是地形，“山的前面是鸡”说不通。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“前面是……，后面是……”要接地点，“故事”不能作为地点，不能搭配。"}], "explanations": {"海": "“山的前面是海，后面是树林”描述的是海岸地形，符合句意。", "桌子": "语义：桌子不是地形，“山的前面是桌子”与句意不符。", "鸡": "语义：鸡不是地形，“山的前面是鸡”说不通。", "故事": "搭配：“前面是……，后面是……”要接地点，“故事”不能作为地点，不能搭配。"}, "sentence_index": 6, "correct_answer": "海"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喜欢看着这条海，不想说话。", "explanation": "这里应该用〈片〉。“海”的量词用“片”，“条”用于河流、线状物，不用于海。"}, {"text": "这栋楼的海很高。", "explanation": "这里应该用〈海拔〉。“海”不能单独表示高度，说地势高低要用“海拔”。"}, {"text": "我们坐船穿过了太平海。", "explanation": "这里应该用〈洋〉。太平洋的“洋”指面积更大的水域，“太平海”不是正式说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的窗口对着一个海。", "corrected_sentence": "我们的窗口对着一片海。", "error_description": "错误形式：一个海；正确形式：一片海。“海”的量词应用“片”，“个”不能修饰“海”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条海横在我们面前。", "corrected_sentence": "一片海横在我们面前。", "error_description": "错误形式：一条海；正确形式：一片海。“条”不用于海，“海”的量词应为“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86299, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最后", "is_correct": true, "explanation": "正确答案。第一与最后在次序上相对，是一对反义词。"}, {"text": "中间", "is_correct": false, "explanation": "中间指位置居中，与第一的次序义没有反义关系。"}, {"text": "角落", "is_correct": false, "explanation": "角落指偏僻的地方，与次序义没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是具体事物，与第一的次序义没有反义关系。"}], "correct_answer": "最后", "explanations": {"最后": "正确答案。第一与最后在次序上相对，是一对反义词。", "中间": "中间指位置居中，与第一的次序义没有反义关系。", "角落": "角落指偏僻的地方，与次序义没有反义关系。", "窗户": "窗户是具体事物，与第一的次序义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
