INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“第一”是排在最前面的那一个。", "primary_collocate": null, "pronunciation": "dì yī", "ipa": "ti⁵¹ i⁵⁵", "syllable_count": 2, "sentences": [{"text": "最先到的人是老师，他是第一个来的人。", "target_word": "第一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的房间在第一层。", "target_word": "第一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是我第一次来北京。", "target_word": "第一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请大家打开书，看第一页。", "target_word": "第一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在比赛中得了第一。", "target_word": "第一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我是第一，她是第二。", "target_word": "第一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "第一天上课，老师先让我们介绍自己。", "target_word": "第一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "排队时，他站在第一个。", "target_word": "第一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "第一个问题很容易，第二个有点难。", "target_word": "第一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把奖状给了第一名的小王。", "target_word": "第一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "第一名", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示次序排在最前面的那一个，如第一个、第一次、第一页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2360d38e-578e-4142-a840-d1924b1155a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86299, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "第一", "is_correct": true, "explanation": "正确答案。第一指次序排在最前面的那一个，读作 dì yī。"}, {"text": "单一", "is_correct": false, "explanation": "dān（第一声）与 dì（第四声）韵母与声调都不同，意思是只有一种，与次序无关。"}, {"text": "敌意", "is_correct": false, "explanation": "dí（第二声）与 dì（第四声）声调不同，yì（第四声）与 yī（第一声）声调也不同，意思是敌对的心理。"}, {"text": "立意", "is_correct": false, "explanation": "lì（第四声）与 dì 声母不同（l 与 d），yì 与 yī 声调不同，意思是立志或构思的意图。"}], "explanations": {"第一": "正确答案。第一指次序排在最前面的那一个，读作 dì yī。", "单一": "dān（第一声）与 dì（第四声）韵母与声调都不同，意思是只有一种，与次序无关。", "敌意": "dí（第二声）与 dì（第四声）声调不同，yì（第四声）与 yī（第一声）声调也不同，意思是敌对的心理。", "立意": "lì（第四声）与 dì 声母不同（l 与 d），yì 与 yī 声调不同，意思是立志或构思的意图。"}, "sentence_index": null, "correct_answer": "第一"}, "level_3": {"options": [{"text": "第一", "is_correct": true, "explanation": "正确答案。“第一个来的人”指次序最前的那个人，符合句意。"}, {"text": "第二", "is_correct": false, "explanation": "语义：第二指次序排在第二位，与句中要求的最先到达的人相反。"}, {"text": "第三", "is_correct": false, "explanation": "语义：第三指次序排在第三位，不能指最先来的那个人。"}, {"text": "下一", "is_correct": false, "explanation": "语义：下一指紧接着的那一个，表示顺序的后续，而不是最先到的人。"}], "explanations": {"第一": "正确答案。“第一个来的人”指次序最前的那个人，符合句意。", "第二": "语义：第二指次序排在第二位，与句中要求的最先到达的人相反。", "第三": "语义：第三指次序排在第三位，不能指最先来的那个人。", "下一": "语义：下一指紧接着的那一个，表示顺序的后续，而不是最先到的人。"}, "sentence_index": 0, "correct_answer": "第一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次数学考了第一百分，老师很惊讶。", "explanation": "这里应该用基数〈一百〉表示分数。〈第一〉是序数，表示排在最前的次序，不表示分数的数量，不能用来说分数。"}, {"text": "他的身高是第一米八，比我高很多。", "explanation": "这里应该用基数〈一米八〉表示身高。〈第一〉表示次序，不表示长度，不能用来说身高。"}, {"text": "他今年第一岁，还不会走路。", "explanation": "这里应该用基数〈一岁〉表示年龄。〈第一〉表示次序，不表示年龄的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "第一", "is_correct": true, "explanation": "正确答案。“第一天上课”指开学的第一天，符合句意。"}, {"text": "每", "is_correct": false, "explanation": "语义：每指每一天，不是特定的起始日，与“先让我们介绍自己”的开学首日不符。"}, {"text": "那", "is_correct": false, "explanation": "语义：那指前文已提到的某一天，与句中开始上课的首日不符。"}, {"text": "某", "is_correct": false, "explanation": "语义：某指不确定的某一天，与句中的开学首日不符。"}], "explanations": {"第一": "正确答案。“第一天上课”指开学的第一天，符合句意。", "每": "语义：每指每一天，不是特定的起始日，与“先让我们介绍自己”的开学首日不符。", "那": "语义：那指前文已提到的某一天，与句中开始上课的首日不符。", "某": "语义：某指不确定的某一天，与句中的开学首日不符。"}, "sentence_index": 6, "correct_answer": "第一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服卖第一百元，很便宜。", "explanation": "这里应该用基数〈一百〉表示价格。〈第一〉是序数，表示次序，不表示价钱的数量，不能用来说价格。"}, {"text": "他的体重是第一百斤，很重。", "explanation": "这里应该用基数〈一百斤〉表示体重。〈第一〉表示次序，不表示重量的数量。"}, {"text": "今天的气温是第一度，很冷。", "explanation": "这里应该用基数〈一度〉表示温度。〈第一〉表示次序，不表示温度的数量，不能用来说温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的第一学生是小王。", "corrected_sentence": "我们班的第一个学生是小王。", "error_description": "“第一”后面的名词前要加量词“个”，漏掉“个”不对。正确说法是“我们班的第一个学生是小王”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我第一个去长城。", "corrected_sentence": "这是我第一次去长城。", "error_description": "计量动作的量词应为“次”。“第一个”中的“个”用于人或事物，不能计量“去长城”这个动作。正确说法是“第一次去长城”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
