INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86309, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“怎样”是用来问事情是什么样子，或者怎么做。", "primary_collocate": null, "pronunciation": "zěn yàng", "ipa": "ʈʂən˨˩ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你觉得这部电影怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这个字怎样写。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道该怎样回答老师。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的考试怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想怎样过这个周末？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜怎样做才好吃？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管天气怎样，我们都去爬山。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的新工作怎样了？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该怎样学好汉语？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道怎样才能找到那家商店。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "怎样：询问事情的样子或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e70502b-b805-4b8c-a302-573ca6cc38cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎样", "is_correct": true, "explanation": "正确：“怎样”询问事物的样子，可以作谓语，用来问对这部电影的评价。"}, {"text": "怎么", "is_correct": false, "explanation": "语义：“怎么”问方式或原因，不能单独作谓语来评价电影。"}, {"text": "什么", "is_correct": false, "explanation": "配价：“什么”指代事物，不能放在“觉得……”之后作评价性的谓语。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”问地点，与对电影的评价不相符。"}], "explanations": {"怎样": "正确：“怎样”询问事物的样子，可以作谓语，用来问对这部电影的评价。", "怎么": "语义：“怎么”问方式或原因，不能单独作谓语来评价电影。", "什么": "配价：“什么”指代事物，不能放在“觉得……”之后作评价性的谓语。", "哪里": "语义：“哪里”问地点，与对电影的评价不相符。"}, "sentence_index": 0, "correct_answer": "怎样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他怎样这么晚才到？", "explanation": "这里应该用〈为什么〉。问原因要用“为什么”，“怎样”问的是方式或状况，不能用来问迟到的原因。"}, {"text": "这个箱子怎样重？", "explanation": "这里应该用〈多〉。问重量的程度要用“多重”，“怎样”只问方式或状况，不能用来问重量。"}, {"text": "我等了他怎样久？", "explanation": "这里应该用〈多久〉。问时间长短要用“多久”，“怎样”只问方式或状况，不能用来问等待的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎样", "is_correct": true, "explanation": "正确：“怎样”指天气的状况，与“不管……都”的结构相符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能用来指天气的状况。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，与天气的状况不符。"}, {"text": "为何", "is_correct": false, "explanation": "语义：“为何”问原因，此处要表达的是天气的状况，而不是原因。"}], "explanations": {"怎样": "正确：“怎样”指天气的状况，与“不管……都”的结构相符。", "谁": "语义：“谁”指人，不能用来指天气的状况。", "哪儿": "语义：“哪儿”问地点，与天气的状况不符。", "为何": "语义：“为何”问原因，此处要表达的是天气的状况，而不是原因。"}, "sentence_index": 6, "correct_answer": "怎样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事我们就怎样算了吧。", "explanation": "这里应该用〈这样〉。“就这样算了”指照这个样子结束，要用指示词“这样”；“怎样”是疑问词，不能用来指代上文的处理。"}, {"text": "大家别再怎样闹了，好好说话。", "explanation": "这里应该用〈那样〉。指代对方刚才的行为要用指示词“那样”；“怎样”是疑问词，不能这样指代。"}, {"text": "你把书放在怎样？", "explanation": "这里应该用〈哪儿〉。问地点要用“哪儿”，“怎样”只问方式或状况，不能用来问书放的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你知道很怎样学好钢琴吗？", "corrected_sentence": "你知道怎样学好钢琴吗？", "error_description": "修饰语错误：程度副词「很」不能放在疑问代词「怎样」前，「怎样」在此作状语，前面不能加「很」。正确说法是「你知道怎样学好钢琴吗」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你的新电脑的情况了怎样？", "corrected_sentence": "你的新电脑的情况怎样了？", "error_description": "语序错误：“了”应放在“怎样”之后，“了怎样”不成立。正确说法是“情况怎样了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
