INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问方式或状况。", "primary_collocate": null, "pronunciation": "zěn yàng", "ipa": "ʈʂən˨˩ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个手机怎样用？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家的小狗最近怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去火车站怎样走？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体现在怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道怎样跟朋友说这件事。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说，这件事怎样解决才好？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样读这个词。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管你怎样说，我都相信他。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在新学校过得怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "怎样：疑问代词，问方式或状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e70502b-b805-4b8c-a302-573ca6cc38cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎样", "is_correct": true, "explanation": "正确：“怎样”问手机的使用方法，可以作谓语。"}, {"text": "为什么", "is_correct": false, "explanation": "语义：“为什么”问原因，“这个手机为什么用”不能用来问使用方法。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，“这个手机谁用”问的是使用者，不是使用方法。"}, {"text": "那样", "is_correct": false, "explanation": "语义：“那样”是指示词，需要指代上文的方式，此处没有可指代的内容。"}], "explanations": {"怎样": "正确：“怎样”问手机的使用方法，可以作谓语。", "为什么": "语义：“为什么”问原因，“这个手机为什么用”不能用来问使用方法。", "谁": "语义：“谁”问人，“这个手机谁用”问的是使用者，不是使用方法。", "那样": "语义：“那样”是指示词，需要指代上文的方式，此处没有可指代的内容。"}, "sentence_index": 0, "correct_answer": "怎样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这里住了怎样久？", "explanation": "这里应该用〈多久〉。问时间长短要用“多久”，“怎样”只问方式或状况，不能用来问居住的时长。"}, {"text": "这件衣服怎样贵？", "explanation": "这里应该用〈多〉。问价格的高低要用“多”或“多么”，“怎样”只问方式或状况，不能用来问贵的程度。"}, {"text": "他怎样一直不说话？", "explanation": "这里应该用〈为何〉。“为何”用于问原因，此处表达的是沉默的原因，“怎样”不能用于这种问法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎样", "is_correct": true, "explanation": "正确：“怎样”问饭店菜的状况，可以作谓语。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能用来问菜的状况。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，与问菜的状况不相符。"}, {"text": "为何", "is_correct": false, "explanation": "语义：“为何”问原因，不能用来问菜的状况。"}], "explanations": {"怎样": "正确：“怎样”问饭店菜的状况，可以作谓语。", "谁": "语义：“谁”指人，不能用来问菜的状况。", "哪儿": "语义：“哪儿”问地点，与问菜的状况不相符。", "为何": "语义：“为何”问原因，不能用来问菜的状况。"}, "sentence_index": 6, "correct_answer": "怎样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这点小事就怎样算了吧。", "explanation": "这里应该用〈这样〉。“就这样算了”指照这个样子结束，要用指示词“这样”；“怎样”是疑问词，不能用来指代。"}, {"text": "你别再怎样了，我已经知道错了。", "explanation": "这里应该用〈那样〉。指代对方刚才的做法要用“那样”，“怎样”是疑问词，不能这样指代。"}, {"text": "他把钥匙丢在怎样了？", "explanation": "这里应该用〈哪儿〉。问地点要用“哪儿”，“怎样”只问方式或状况，不能用来问钥匙丢在哪里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请告诉我你怎样胖了。", "corrected_sentence": "请告诉我你为什么胖了。", "error_description": "用法错误：“怎样”只问方式或状况，不能用来问原因。问原因应说“为什么”，“你怎样胖了”不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行的情况怎样的？", "corrected_sentence": "这次旅行的情况怎样了？", "error_description": "语法错误：「怎样的」是定语结构，后面须接名词，句末单独说「情况怎样的？」不成立。句末的「了」表示状况已发生变化，应为「情况怎样了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
