INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示禁止或劝阻，相当于“不要”。", "primary_collocate": null, "pronunciation": "bié", "ipa": "pje˧˥", "syllable_count": 1, "sentences": [{"text": "别说话，孩子睡着了。", "target_word": "别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了带伞，外面在下雨。", "target_word": "别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很冷，别穿这么少。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别跑，路上有很多车。", "target_word": "别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太晚了，别再看手机了。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别生气，我不是故意的。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别哭，我们一起想办法。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里请别大声说话。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别把杯子放在桌边，会掉下去的。", "target_word": "别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别着急，时间还很多。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "別", "label": "繁体"}], "register": "口语", "sense_fingerprint": "别：禁止或劝阻，相当于不要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 杯子 (Zipf 3.82), 桌 (Zipf 3.79), 掉下去 (Zipf 3.25)']::text[], '3ad95ebb-2d68-48d2-a298-d9f392305c7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "别", "is_correct": true, "explanation": "别（bié）是副词，表示禁止或劝阻，相当于“不要”。"}, {"text": "憋", "is_correct": false, "explanation": "bié（第二声）与 biē（第一声）声调不同，意思是“憋”（如憋气），不是“别”。"}, {"text": "瘪", "is_correct": false, "explanation": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。"}, {"text": "撇", "is_correct": false, "explanation": "piě 与 bié 声母不同（p 与 b），意思是“撇”（向一侧斜去），不是“别”。"}, {"text": "灭", "is_correct": false, "explanation": "miè 与 bié 声母不同（m 与 b），意思是“灭”（熄灭），不是“别”。"}], "explanations": {"别": "别（bié）是副词，表示禁止或劝阻，相当于“不要”。", "憋": "bié（第二声）与 biē（第一声）声调不同，意思是“憋”（如憋气），不是“别”。", "瘪": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。", "撇": "piě 与 bié 声母不同（p 与 b），意思是“撇”（向一侧斜去），不是“别”。", "灭": "miè 与 bié 声母不同（m 与 b），意思是“灭”（熄灭），不是“别”。"}, "sentence_index": null, "correct_answer": "别"}, "level_3": {"options": [{"text": "别", "is_correct": true, "explanation": "“别说话”表示禁止，与“孩子睡着了”的安静语境相符。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促尽快行动，与孩子睡着、需要安静的语境相反。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，不能表示禁止或劝阻。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示动作重复，不能表示禁止或劝阻。"}], "explanations": {"别": "“别说话”表示禁止，与“孩子睡着了”的安静语境相符。", "赶紧": "语义：“赶紧”表示催促尽快行动，与孩子睡着、需要安静的语境相反。", "已经": "体貌：“已经”表示动作已经完成，不能表示禁止或劝阻。", "又": "语义：“又”表示动作重复，不能表示禁止或劝阻。"}, "sentence_index": 0, "correct_answer": "别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我别这个蛋糕，太甜了。", "explanation": "这里应该用〈不要〉。表示不想要某样东西时用“不要”，“别”只用于禁止或劝阻，不能这样表达。"}, {"text": "他别很忙，所以没有来。", "explanation": "这里应该用〈很〉。“很忙”表示程度，“别”只用于劝阻，不能修饰形容词。"}, {"text": "这件事我别清楚，所以不能帮你。", "explanation": "这里应该用〈很〉。“很清楚”表示程度，“别”不能修饰形容词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "别", "is_correct": true, "explanation": "别（bié）是副词，表示禁止或劝阻，相当于“不要”。"}, {"text": "鳖", "is_correct": false, "explanation": "biē（第一声）与 bié（第二声）声调不同，意思是“鳖”（甲鱼）。"}, {"text": "瞥", "is_correct": false, "explanation": "piē（第一声）与 bié 声母不同（p 与 b），声调也不同，意思是“瞥”（看一眼）。"}, {"text": "跌", "is_correct": false, "explanation": "diē（第一声）与 bié 声母不同（d 与 b），声调也不同，意思是“跌”（摔倒）。"}, {"text": "碟", "is_correct": false, "explanation": "dié（第二声）与 bié 声母不同（d 与 b），意思是“碟子”，不是“别”。"}], "explanations": {"别": "别（bié）是副词，表示禁止或劝阻，相当于“不要”。", "鳖": "biē（第一声）与 bié（第二声）声调不同，意思是“鳖”（甲鱼）。", "瞥": "piē（第一声）与 bié 声母不同（p 与 b），声调也不同，意思是“瞥”（看一眼）。", "跌": "diē（第一声）与 bié 声母不同（d 与 b），声调也不同，意思是“跌”（摔倒）。", "碟": "dié（第二声）与 bié 声母不同（d 与 b），意思是“碟子”，不是“别”。"}, "sentence_index": null, "correct_answer": "别"}, "level_3": {"options": [{"text": "别", "is_correct": true, "explanation": "“别哭”表示劝阻，与“我们一起想办法”的安慰语境相符。"}, {"text": "还", "is_correct": false, "explanation": "语义：“还”表示持续或追加，与“别哭”的劝阻语气不合。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，不能表示劝阻。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意、反而，与“我们一起想办法”的安慰语境不合。"}], "explanations": {"别": "“别哭”表示劝阻，与“我们一起想办法”的安慰语境相符。", "还": "语义：“还”表示持续或追加，与“别哭”的劝阻语气不合。", "正在": "体貌：“正在”表示动作进行中，不能表示劝阻。", "偏偏": "语义：“偏偏”表示故意、反而，与“我们一起想办法”的安慰语境不合。"}, "sentence_index": 6, "correct_answer": "别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他别来过中国，所以不太了解那里。", "explanation": "这里应该用〈没〉。“没来过”表示过去没有某种经历，“别”只用于劝阻，不能这样用。"}, {"text": "我别会游泳，所以不去海边。", "explanation": "这里应该用〈不会〉。“不会”表示不具备某种能力，“别”只能用于禁止或劝阻。"}, {"text": "这家店的衣服别便宜，很多人都买。", "explanation": "这里应该用〈很〉。“很便宜”表示程度，“别”不能修饰形容词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别你说话，奶奶在休息。", "corrected_sentence": "你别说话，奶奶在休息。", "error_description": "“别”应放在主语“你”之后，应说“你别说话”，不能说“别你说话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不别担心，他很快就回来。", "corrected_sentence": "别担心，他很快就回来。", "error_description": "“别”本身已含否定意思，前面不能再加“不”，应说“别担心”，不能说“不别担心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8622782-50aa-416e-972c-067ebb6c3f22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示充分条件，常与“就”配合使用。", "primary_collocate": null, "pronunciation": "zhǐ yào", "ipa": "ʈʂɨ²¹⁴ jɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "只要你来，我就高兴。", "target_word": "只要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "只要天气好，我们就去玩。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要努力学习，你就会进步。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要看过一遍，她就能记住。", "target_word": "只要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要不下雨，比赛就照常进行。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要每天听一小时，你的汉语就会好起来。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要明天不下雨，我们就去公园。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要坐地铁，二十分钟就能到公司。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要你说一声，我马上就来。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要他想学，老师就愿意教他。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词，引出充分条件，后面常用“就”接结果，如只要……就……", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2360d38e-578e-4142-a840-d1924b1155a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "只要", "is_correct": true, "explanation": "正确答案。“只要你来，我就高兴”表示充分条件，符合句意。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与“而且”或“也”配合，与后句的“就”不能搭配。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”后要与“都”配合，此处用“就”不通。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，与“我就高兴”的条件结果不符。"}], "explanations": {"只要": "正确答案。“只要你来，我就高兴”表示充分条件，符合句意。", "不但": "搭配：“不但”要与“而且”或“也”配合，与后句的“就”不能搭配。", "无论": "搭配：“无论”后要与“都”配合，此处用“就”不通。", "虽然": "语义：“虽然”表示让步，与“我就高兴”的条件结果不符。"}, "sentence_index": 0, "correct_answer": "只要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "只要努力学习，你却没进步。", "explanation": "〈只要〉表示充分条件，“努力学习”即应带来进步；这里用〈却〉表示没有进步，与充分条件的含义相矛盾。若要表示转折，应改用〈虽然〉。"}, {"text": "只要你肯努力，这次却没考好。", "explanation": "这里应该用〈虽然〉，表示让步，与“却”配合。〈只要〉引出充分条件，与“却”表示的转折不相容。"}, {"text": "只要他很努力，所以成绩好。", "explanation": "这里应该用〈因为〉，表示原因。〈只要〉引出充分条件，后面应接“就”，不能接“所以”表示因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只要", "is_correct": true, "explanation": "正确答案。“只要明天不下雨，我们就去公园”表示充分条件，符合句意。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”是副词，不能用来引出条件分句。"}, {"text": "不管", "is_correct": false, "explanation": "搭配：“不管”要与“都”配合，与后句的“就”不能搭配。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，与“我们就去公园”的条件结果不符。"}], "explanations": {"只要": "正确答案。“只要明天不下雨，我们就去公园”表示充分条件，符合句意。", "只好": "搭配：“只好”是副词，不能用来引出条件分句。", "不管": "搭配：“不管”要与“都”配合，与后句的“就”不能搭配。", "尽管": "语义：“尽管”表示让步，与“我们就去公园”的条件结果不符。"}, "sentence_index": 6, "correct_answer": "只要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只要天气怎样，我们都去公园。", "explanation": "这里应该用〈不管〉，表示无论哪种情况，后接“都”。〈只要〉引出充分条件，不能表示无条件的意思。"}, {"text": "只要下雨，我们还是去了。", "explanation": "这里应该用〈虽然〉，表示让步。〈只要〉引出充分条件，不能用来表示转折的“还是”。"}, {"text": "他很累，只要还在工作，所以他很快乐。", "explanation": "这里〈只要〉引出充分条件，后接〈所以〉表示因果，两者搭配不当，因果应说〈因为〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你肯努力只要，就能学好汉语。", "corrected_sentence": "只要你肯努力，就能学好汉语。", "error_description": "“只要”引导条件分句，必须位于条件分句之首；这里放在“肯努力”之后，位置错误。正确说法是“只要你肯努力，就能学好汉语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多练习只要，你的口语就会好起来。", "corrected_sentence": "只要多练习，你的口语就会好起来。", "error_description": "“只要”是连词，引出条件分句时必须位于条件分句之首，不能放在动词短语“多练习”之后。这里把“只要”误放在“多练习”后面，位置错误。正确说法是“只要多练习，你的口语就会好起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
