INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网页是上网时，屏幕上看到的一页。", "primary_collocate": null, "pronunciation": "wǎng yè", "ipa": "waŋ˨˩˦ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "屏幕上的网页突然变白了。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页太长，我往下看了很久。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上网时，我常常同时开着几个网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他关掉了所有的网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页的颜色很舒服。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页上出现了一个红色的字。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把网页往上拉一点儿。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看着网页，不知道怎么点。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷新一下网页，就能看到新的内容。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑里有太多没关的网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "网页设计", "label": "复合"}], "register": "通用", "sense_fingerprint": "网页：上网时屏幕上看到的一页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd8ccd27-d9af-45a9-8d08-de0015174fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网页", "is_correct": true, "explanation": "网页指上网时屏幕上看到的一页，屏幕上出现的正是它，符合语境。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是能显示在屏幕上、会变白的东西，与语境不符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人内在的感受，不是屏幕上可见的东西，与“突然变白了”不相符。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是人与人之间的情感，不是能显示在屏幕上的东西，与语境不符。"}], "explanations": {"网页": "网页指上网时屏幕上看到的一页，屏幕上出现的正是它，符合语境。", "感冒": "语义：感冒是一种疾病，不是能显示在屏幕上、会变白的东西，与语境不符。", "心情": "语义：心情是人内在的感受，不是屏幕上可见的东西，与“突然变白了”不相符。", "友谊": "语义：友谊是人与人之间的情感，不是能显示在屏幕上的东西，与语境不符。"}, "sentence_index": 0, "correct_answer": "网页"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个网页是用木头刻出来的。", "explanation": "这里的“网页”被当成了实物。网页是屏幕上显示的页面，没有实体，不能用木头刻，这个意思不对。"}, {"text": "我家的网页很快，看视频不卡。", "explanation": "这里应该用〈网络〉。网页指单个页面，说连接的速度快要用“网络”。"}, {"text": "渔夫把网页撒进了河里。", "explanation": "这里应该用〈渔网〉。这里的“网”是渔网，网页是屏幕上的页面，不能撒进河里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网页", "is_correct": true, "explanation": "网页可以在窗口中上下滚动，“往上拉”指拖动页面，符合语境。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以拖动调整位置的东西，“把感冒往上拉”不通。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，不是可以拖动调整的页面，“把白菜往上拉”与语境不符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，不是可以拖动调整位置的东西，与语境不符。"}], "explanations": {"网页": "网页可以在窗口中上下滚动，“往上拉”指拖动页面，符合语境。", "感冒": "语义：感冒是一种疾病，不是可以拖动调整位置的东西，“把感冒往上拉”不通。", "白菜": "语义：白菜是蔬菜，不是可以拖动调整的页面，“把白菜往上拉”与语境不符。", "早饭": "语义：早饭是一顿饭，不是可以拖动调整位置的东西，与语境不符。"}, "sentence_index": 6, "correct_answer": "网页"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天收到很多网页。", "explanation": "这里应该用〈邮件〉。收到的是邮件，网页是在浏览器里打开浏览的，不说“收到网页”。"}, {"text": "我的网页碎了，换了一块新的。", "explanation": "这里应该用〈屏幕〉。屏幕是会碎的硬件，网页只是屏幕上显示的内容，不会碎。"}, {"text": "这本书有三百个网页。", "explanation": "这里应该用〈页〉。书的页是纸上的页，网页只指屏幕上的页面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我打开了一只网页。", "corrected_sentence": "我打开了一个网页。", "error_description": "量词错误：“网页”应配“个”（或“张”），“只”用于动物。正确说法是“一个网页”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把网页们关掉了。", "corrected_sentence": "妈妈把网页关掉了。", "error_description": "错误：“网页”指屏幕上的页面，不是人或动物，不能加“们”表示复数；去掉“们”即为“妈妈把网页关掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
