INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "互联网上的页面，可显示文字、图片等。", "primary_collocate": null, "pronunciation": "wǎng yè", "ipa": "waŋ˨˩˦ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我打开了一个新网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页上有很多漂亮的图片。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在学做网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个网页发给我。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页的字太小，我看不清楚。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页打不开，可能是网速太慢。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机看了一个新闻网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页是用中文写的。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们找一个介绍中国的网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把有用的网页都存起来了。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "网页设计", "label": "复合"}], "register": "通用", "sense_fingerprint": "网页：互联网上可显示文字、图片的页面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd8ccd27-d9af-45a9-8d08-de0015174fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网页", "is_correct": true, "explanation": "正确：网页是互联网上可以打开的页面，与“打开”搭配。"}, {"text": "网速", "is_correct": false, "explanation": "语义：网速指网络传输的速度，不是可以打开的东西。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以打开的东西，与语境不符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，不是可以打开的东西，与语境不符。"}], "explanations": {"网页": "正确：网页是互联网上可以打开的页面，与“打开”搭配。", "网速": "语义：网速指网络传输的速度，不是可以打开的东西。", "感冒": "语义：感冒是一种疾病，不是可以打开的东西，与语境不符。", "早饭": "语义：早饭是一顿饭，不是可以打开的东西，与语境不符。"}, "sentence_index": 0, "correct_answer": "网页"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我打开了一本网页。", "explanation": "这里应该用〈个〉。“本”是书籍的量词，网页应用“个”或“张”计量。"}, {"text": "我买了一台新网页。", "explanation": "这里应该用〈电脑〉。“台”用于机器，网页不是机器，不能用“台”计量。"}, {"text": "我们家的网页很快。", "explanation": "这里应该用〈网络〉。“很快”形容网络的速度，网页是页面，不能用来形容速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网页", "is_correct": true, "explanation": "正确：网页是在手机上可以看到的页面，符合“看了一个新闻”的语境。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是一台设备，不能说用手机看了一个电视。"}, {"text": "水龙头", "is_correct": false, "explanation": "语义：水龙头是用来出水的设备，与“看新闻”的语境完全不符。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：看不与“音乐”搭配，听音乐才这样说。"}], "explanations": {"网页": "正确：网页是在手机上可以看到的页面，符合“看了一个新闻”的语境。", "电视": "语义：电视是一台设备，不能说用手机看了一个电视。", "水龙头": "语义：水龙头是用来出水的设备，与“看新闻”的语境完全不符。", "音乐": "搭配：看不与“音乐”搭配，听音乐才这样说。"}, "sentence_index": 6, "correct_answer": "网页"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的网页没电了，要充电。", "explanation": "这里应该用〈手机〉。没电要充电的是手机等设备，网页是页面，不能说没电。"}, {"text": "我把网页的电源关掉了。", "explanation": "这里应该用〈电脑〉。电源是电脑等设备才有的，网页是页面，不能说关掉它的电源。"}, {"text": "我在厨房里煮了一锅网页。", "explanation": "这里应该用〈饭〉。“煮”的对象是食物，网页是屏幕上的页面，不能下锅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚打开了一只新网页，里面有很多图片。", "corrected_sentence": "我刚打开了一个新网页，里面有很多图片。", "error_description": "错误：网页的量词应为“个”或“张”，“一只”是动物的量词，用在网页上错了。正确说法是“一个新网页”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用手机看了一个天气网页们。", "corrected_sentence": "她用手机看了一个天气网页。", "error_description": "错误：“网页”指屏幕上的页面，不是人或动物，不能加“们”表示复数；去掉“们”即为“她用手机看了一个天气网页。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "局部", "is_correct": true, "explanation": "正确：“整个”指全部，“局部”指一部分，两者是反义关系。"}, {"text": "特别", "is_correct": false, "explanation": "“特别”表示不一般，与“整个”指全部的范围无反义关系。"}, {"text": "微小", "is_correct": false, "explanation": "“微小”形容很小，不是“整个”在范围上的反义词。"}, {"text": "普通", "is_correct": false, "explanation": "“普通”表示平常，与“整个”的范围含义无关。"}], "correct_answer": "局部", "explanations": {"局部": "正确：“整个”指全部，“局部”指一部分，两者是反义关系。", "特别": "“特别”表示不一般，与“整个”指全部的范围无反义关系。", "微小": "“微小”形容很小，不是“整个”在范围上的反义词。", "普通": "“普通”表示平常，与“整个”的范围含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "局部", "is_correct": true, "explanation": "正确：“整个”指全部，“局部”指一部分，两者是反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“整个”的范围含义无反义关系。"}, {"text": "精细", "is_correct": false, "explanation": "“精细”形容细致，与“整个”的范围含义无反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“整个”的范围含义无关。"}], "correct_answer": "局部", "explanations": {"局部": "正确：“整个”指全部，“局部”指一部分，两者是反义关系。", "清楚": "“清楚”形容明白、不模糊，与“整个”的范围含义无反义关系。", "精细": "“精细”形容细致，与“整个”的范围含义无反义关系。", "迅速": "“迅速”形容速度快，与“整个”的范围含义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“整个”是说全部，一点不少。", "primary_collocate": null, "pronunciation": "zhěng gè", "ipa": "ʈʂɤŋ˨˩˦ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "整个下午我都在图书馆看书。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个城市都下着大雨。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他病了，整个星期没去上班。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个晚上孩子都在哭。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个好消息，整个教室都安静了。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个夏天我们都住在海边。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个班的同学都参加了比赛。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事，整个公司的人都知道。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个房间里都是花的香味。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个冬天，这里一直没有下雪。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整个：用于时间、范围，指全部，一点不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0b2c08-2695-4f5d-b3b3-5f7e6e5c77a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整个", "is_correct": true, "explanation": "正确：“整个下午”表示全部时间，与后面“我都在”的全程含义相符。"}, {"text": "部分", "is_correct": false, "explanation": "搭配：“部分”表示不全，与后面的“都”要求全部的语义矛盾。"}, {"text": "零星", "is_correct": false, "explanation": "语义：“零星”指断断续续、很少，与“我都在图书馆看书”的整段时间冲突。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”说时间很短，与这里整段下午的时长相反。"}], "explanations": {"整个": "正确：“整个下午”表示全部时间，与后面“我都在”的全程含义相符。", "部分": "搭配：“部分”表示不全，与后面的“都”要求全部的语义矛盾。", "零星": "语义：“零星”指断断续续、很少，与“我都在图书馆看书”的整段时间冲突。", "短暂": "语义：“短暂”说时间很短，与这里整段下午的时长相反。"}, "sentence_index": 0, "correct_answer": "整个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把假期的整个都用来看书，很少出门。", "explanation": "这里应该用〈全部〉。“整个”是形容词，只能修饰名词，不能单独作名词；应说“假期的全部”或“整个假期”。"}, {"text": "他忘了这件事的整个，直到第二天才想起来。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这件事的全部”。"}, {"text": "这些钱的整个交给了他。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这些钱的全部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整个", "is_correct": true, "explanation": "正确：“整个班”指全班，与“都参加了比赛”相符。"}, {"text": "偏僻", "is_correct": false, "explanation": "语义：“偏僻”形容地方冷僻，不能修饰一个班级的全体同学。"}, {"text": "残缺", "is_correct": false, "explanation": "搭配：“残缺”多用于物品或身体，不用来修饰班级及其成员全部到齐的情况。"}, {"text": "空荡", "is_correct": false, "explanation": "语义：“空荡”形容空间空旷，与“同学都参加了比赛”的人员状态冲突。"}], "explanations": {"整个": "正确：“整个班”指全班，与“都参加了比赛”相符。", "偏僻": "语义：“偏僻”形容地方冷僻，不能修饰一个班级的全体同学。", "残缺": "搭配：“残缺”多用于物品或身体，不用来修饰班级及其成员全部到齐的情况。", "空荡": "语义：“空荡”形容空间空旷，与“同学都参加了比赛”的人员状态冲突。"}, "sentence_index": 6, "correct_answer": "整个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们的整个在操场上玩，玩到天黑。", "explanation": "这里应该用〈全体〉。“整个”是形容词，不能单独作主语；指全体孩子应说“全体孩子”。"}, {"text": "这些菜我们的整个吃完了，一点也没剩。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这些菜我们全部吃完了”。"}, {"text": "这些书的整个卖完了。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这些书全部卖完了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们整个整个冬天都在家读书。", "corrected_sentence": "我们整个冬天都在家读书。", "error_description": "错误：“整个”重复了一次。“整个”只修饰“冬天”一次，应说“整个冬天”，不能说“整个整个冬天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他整个整个下午都在打扫房间。", "corrected_sentence": "他整个下午都在打扫房间。", "error_description": "错误：“整个”重复了一次。“整个”只修饰“下午”一次，应说“整个下午”，不能说“整个整个下午”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
