INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86330, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，指全部的、完整的。", "primary_collocate": null, "pronunciation": "zhěng gè", "ipa": "ʈʂɤŋ˨˩˦ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我一口吃了整个苹果。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把整个蛋糕都吃完了。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个西瓜太大了，我们切开吃吧。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买下整个商店。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把整个故事讲一遍。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在山上，可以看到整个城市。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个蛋糕只要五十块钱。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们租下了整个二楼。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把整个房间都打扫干净了。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上画了整个世界。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整个：用于具体事物，指完整的、没有分开的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0b2c08-2695-4f5d-b3b3-5f7e6e5c77a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整个", "is_correct": true, "explanation": "正确：“整个苹果”指完整的一个苹果，与“一口吃了”相符。"}, {"text": "巨大", "is_correct": false, "explanation": "语义：“巨大”指体积很大，与“一口吃了”的小口动作冲突。"}, {"text": "透明", "is_correct": false, "explanation": "体貌：“透明”描述外观特征，苹果不能用来形容这种状态，且与吃的动作无关。"}, {"text": "方正", "is_correct": false, "explanation": "体貌：“方正”描述形状，苹果通常不是方形，与句子语境不符。"}], "explanations": {"整个": "正确：“整个苹果”指完整的一个苹果，与“一口吃了”相符。", "巨大": "语义：“巨大”指体积很大，与“一口吃了”的小口动作冲突。", "透明": "体貌：“透明”描述外观特征，苹果不能用来形容这种状态，且与吃的动作无关。", "方正": "体貌：“方正”描述形状，苹果通常不是方形，与句子语境不符。"}, "sentence_index": 0, "correct_answer": "整个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他只吃了苹果的整个，剩下的留给了妹妹。", "explanation": "这里应该用〈一半〉。“整个”是形容词，不能单独作名词；只吃一部分应说“只吃了苹果的一半”。"}, {"text": "他只看了商店的整个，就匆匆走了。", "explanation": "这里应该用〈整体〉。“整个”是形容词，不能单独作名词中心语；指一个整体要用“整体”。"}, {"text": "这笔钱的整个交给了他。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这笔钱的全部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整个", "is_correct": true, "explanation": "正确：“整个蛋糕”指完整的一块蛋糕，与“只要五十块钱”的价格语境相符。"}, {"text": "永恒", "is_correct": false, "explanation": "语义：“永恒”指时间上没有终点，与“只要五十块钱”的具体价格冲突。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”指距离很远，不能修饰一块可以买到的蛋糕。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多用于水、眼神等，不用来修饰蛋糕。"}], "explanations": {"整个": "正确：“整个蛋糕”指完整的一块蛋糕，与“只要五十块钱”的价格语境相符。", "永恒": "语义：“永恒”指时间上没有终点，与“只要五十块钱”的具体价格冲突。", "遥远": "语义：“遥远”指距离很远，不能修饰一块可以买到的蛋糕。", "清澈": "搭配：“清澈”多用于水、眼神等，不用来修饰蛋糕。"}, "sentence_index": 6, "correct_answer": "整个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把整个图画完了，只剩下一小块空白。", "explanation": "这里应该用〈基本〉。“整个”指全部、完整，和“只剩下一小块空白”矛盾，说大致完成要用“基本”。"}, {"text": "我们只在冬天的整个读了几天书，后面就不读了。", "explanation": "这里应该用〈前段〉。“整个”是形容词，不能单独作名词；只读前段应说“冬天的前段”。"}, {"text": "这些画的整个卖完了。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这些画全部卖完了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了整个整个西瓜回家。", "corrected_sentence": "我买了整个西瓜回家。", "error_description": "错误：“整个”重复了一次。“整个”只修饰“西瓜”一次，应说“整个西瓜”，不能说“整个整个西瓜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在纸上画了整个整个城市。", "corrected_sentence": "他在纸上画了整个城市。", "error_description": "错误：“整个”重复了一次。“整个”只修饰“城市”一次，应说“整个城市”，不能说“整个整个城市”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
