INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86331, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "频道是电视里不同的节目台。", "primary_collocate": null, "pronunciation": "pín dào", "ipa": "pʰin˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢看电影频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一直在换频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想看这个频道的电视剧。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个频道在播足球比赛？", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱看少儿频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别老换频道，我在看呢。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个频道有好看的动画片。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遥控器在哪儿？我想换个频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把电视调到了音乐频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个频道的节目很有意思。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "頻道", "label": "繁体"}, {"form": "电影频道", "label": "复合"}], "register": "中性", "sense_fingerprint": "电视里可以选择的不同节目台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24b4c419-7330-44fc-8baa-3d93001cf48d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“看电影”接的是可以看的内容，“作业”不能被看成电影。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，不能作为“看电影”的对象。"}, {"text": "频道", "is_correct": true, "explanation": "正确答案：“看电影频道”指观看以电影为主的电视节目台。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“看”接电影、节目这类内容，“书包”是用品，不能搭配。"}], "explanations": {"作业": "语义：“看电影”接的是可以看的内容，“作业”不能被看成电影。", "面包": "语义：“面包”是食物，不能作为“看电影”的对象。", "频道": "正确答案：“看电影频道”指观看以电影为主的电视节目台。", "书包": "搭配：“看”接电影、节目这类内容，“书包”是用品，不能搭配。"}, "sentence_index": 0, "correct_answer": "频道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在台上表演了一个频道。", "explanation": "这里应该用〈节目〉。频道是可以选择的节目台，不能被表演；表演的是节目。"}, {"text": "他从这个频道走进了图书馆。", "explanation": "这里应该用〈通道〉。频道是电视里可选的节目台，不能指供人通行的通道。"}, {"text": "我家电视上有一条频道很好看。", "explanation": "这里应该用〈个〉。频道的量词是“个”，“条”不用于频道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是可以播放动画片的媒体。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“这个X有好看的动画片”中的X须是播放节目的媒体，“雨伞”不能有动画片。"}, {"text": "频率", "is_correct": false, "explanation": "语义：“频率”指振动的次数，不能播放动画片。"}, {"text": "频道", "is_correct": true, "explanation": "正确答案：“这个频道”指播放动画片的电视节目台。"}], "explanations": {"作业": "语义：“作业”不是可以播放动画片的媒体。", "雨伞": "搭配：“这个X有好看的动画片”中的X须是播放节目的媒体，“雨伞”不能有动画片。", "频率": "语义：“频率”指振动的次数，不能播放动画片。", "频道": "正确答案：“这个频道”指播放动画片的电视节目台。"}, "sentence_index": 6, "correct_answer": "频道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个频道的压力很大。", "explanation": "这里应该用〈水管〉。频道是电视里的节目台，不能指输水的水管。"}, {"text": "这根频道的节目很有意思。", "explanation": "这里应该用〈个〉。频道的量词是“个”，“根”用于细长的东西，不用于频道。"}, {"text": "这个频道很宽，可以并排开两辆车。", "explanation": "这里应该用〈车道〉。频道是电视里的节目台，不能指道路上供车辆通行的车道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈喜欢看那条体育频道。", "corrected_sentence": "妈妈喜欢看那个体育频道。", "error_description": "量词错误：“频道”应搭配量词“个”，“条”不能用于频道，应为“那个体育频道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把电视换只动画频道。", "corrected_sentence": "请把电视换个动画频道。", "error_description": "量词错误：“频道”应搭配量词“个”，“只”用于动物或成对器物中的单个，不能用于频道。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
