INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电视或广播中，传送某套节目的信号通路。", "primary_collocate": null, "pronunciation": "pín dào", "ipa": "pʰin˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "请把电视换到新闻频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个频道的信号不太好。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收音机里有很多音乐频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个频道二十四小时播放新闻。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视的频道太多了。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上看体育频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的电视只能收到十个频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广播频道晚上播放音乐。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信号太弱，这个频道看不清楚。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把收音机调到交通频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "頻道", "label": "繁体"}, {"form": "新闻频道", "label": "复合"}], "register": "中性", "sense_fingerprint": "电视或广播传送某套节目的信号通路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24b4c419-7330-44fc-8baa-3d93001cf48d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：电视不能换到“作业”上，作业不是可以切换的播出内容。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“新闻”修饰的是频道、节目，不能修饰手机。"}, {"text": "频道", "is_correct": true, "explanation": "正确答案：“新闻频道”指播放新闻的电视频道，电视可以换到这里。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，电视不能换到它上面。"}], "explanations": {"作业": "语义：电视不能换到“作业”上，作业不是可以切换的播出内容。", "手机": "搭配：“新闻”修饰的是频道、节目，不能修饰手机。", "频道": "正确答案：“新闻频道”指播放新闻的电视频道，电视可以换到这里。", "面包": "语义：“面包”是食物，电视不能换到它上面。"}, "sentence_index": 0, "correct_answer": "频道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个频道表演了一首歌。", "explanation": "这里应该用〈节目〉。频道是信号通路，不能表演；能表演的是节目。"}, {"text": "我们从这个频道走出了地铁站。", "explanation": "这里应该用〈通道〉。频道指电视或广播的节目信号通路，不能指供人通行的通道。"}, {"text": "我家电视上有一条频道在播新闻。", "explanation": "这里应该用〈个〉。频道的量词是“个”，“条”多用于河流、道路、消息等，不用于频道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信件", "is_correct": false, "explanation": "语义：电视不能收到“信件”，信件不是可以接收的节目或信号。"}, {"text": "频道", "is_correct": true, "explanation": "正确答案：电视能收到的是频道，“十个频道”是数量。"}, {"text": "包裹", "is_correct": false, "explanation": "语义：“包裹”是寄送的物品，电视不能收到它。"}, {"text": "孩子", "is_correct": false, "explanation": "搭配：“收到”接的是信号、节目、频道这类内容，不能搭配“孩子”。"}], "explanations": {"信件": "语义：电视不能收到“信件”，信件不是可以接收的节目或信号。", "频道": "正确答案：电视能收到的是频道，“十个频道”是数量。", "包裹": "语义：“包裹”是寄送的物品，电视不能收到它。", "孩子": "搭配：“收到”接的是信号、节目、频道这类内容，不能搭配“孩子”。"}, "sentence_index": 6, "correct_answer": "频道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们通过正规频道买到了票。", "explanation": "这里应该用〈渠道〉。频道只指电视或广播的节目信号通路，“通过……买到”的途径要用渠道。"}, {"text": "这个频道的水流很急。", "explanation": "这里应该用〈管道〉。频道指电视或广播的节目信号通路，不能指输水的管道。"}, {"text": "我家电视只有一根频道。", "explanation": "这里应该用〈个〉。频道的量词是“个”，“根”用于细长的东西，不用于频道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有三只频道。", "corrected_sentence": "我家有三个频道。", "error_description": "量词错误：“频道”应搭配量词“个”。“只”多用于动物或成对器物中的单个，不能用于频道。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把电视调到一条体育频道。", "corrected_sentence": "请把电视调到一个体育频道。", "error_description": "量词错误：“频道”应搭配量词“个”，“条”不用于频道，应为“调到一个体育频道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
