INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交是把东西给别人。", "primary_collocate": null, "pronunciation": "jiāo", "ipa": "tɕjɑʊ̯˥", "syllable_count": 1, "sentences": [{"text": "老师让我们交作业。", "target_word": "交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把信交给了我。", "target_word": "交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把票交给门口的人。", "target_word": "交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经交了这个月的房租。", "target_word": "交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事你交给我吧。", "target_word": "交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把手机交给了爸爸。", "target_word": "交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束了，请马上交卷子。", "target_word": "交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都在交试卷。", "target_word": "交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每月交一次电费。", "target_word": "交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理把工作交给了小王。", "target_word": "交", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交了", "label": "完成体"}, {"form": "交过", "label": "经历体"}, {"form": "交给", "label": "复合"}], "register": "中性", "sense_fingerprint": "交：把东西交给别人（上交、转交）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24b4c419-7330-44fc-8baa-3d93001cf48d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敲", "is_correct": false, "explanation": "qiāo 与 jiāo 声母不同（q / j），意思是敲打。"}, {"text": "交", "is_correct": true, "explanation": "正确答案：交（jiāo），意思是把东西交给别人。"}, {"text": "脚", "is_correct": false, "explanation": "jiǎo 与 jiāo 声调不同（第三声 / 第一声），意思是脚。"}, {"text": "消", "is_correct": false, "explanation": "xiāo 与 jiāo 声母不同（x / j），意思是消失、消除。"}], "explanations": {"敲": "qiāo 与 jiāo 声母不同（q / j），意思是敲打。", "交": "正确答案：交（jiāo），意思是把东西交给别人。", "脚": "jiǎo 与 jiāo 声调不同（第三声 / 第一声），意思是脚。", "消": "xiāo 与 jiāo 声母不同（x / j），意思是消失、消除。"}, "sentence_index": null, "correct_answer": "交"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“作业”不能被吃，“吃”与“作业”的意思不合。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”一般接桌子、黑板等，不能接“作业”。"}, {"text": "交", "is_correct": true, "explanation": "正确答案：“老师让我们交作业”指要求学生把作业交上去。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“作业”不能被煮，“煮”与“作业”的意思不合。"}], "explanations": {"吃": "语义：“作业”不能被吃，“吃”与“作业”的意思不合。", "擦": "搭配：“擦”一般接桌子、黑板等，不能接“作业”。", "交": "正确答案：“老师让我们交作业”指要求学生把作业交上去。", "煮": "语义：“作业”不能被煮，“煮”与“作业”的意思不合。"}, "sentence_index": 0, "correct_answer": "交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在大学交了一座教学楼。", "explanation": "这里的“交”是结识的意思，但结识的对象只能是人，不能指教学楼；本题“把东西交给别人”不是这样用。"}, {"text": "我在山上交了一片森林。", "explanation": "这里的“交”是结识的意思，但结识的对象只能是人，不能指森林；本题“把东西交给别人”不是这样用。"}, {"text": "我在操场上交了一棵大树。", "explanation": "这里的“交”是结识的意思，但结识的对象只能是人，不能指大树；本题“把东西交给别人”不是这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "叫", "is_correct": false, "explanation": "jiào 与 jiāo 声调不同（第四声 / 第一声），意思是叫喊。"}, {"text": "交", "is_correct": true, "explanation": "正确答案：交（jiāo），意思是把东西交给别人。"}, {"text": "缴", "is_correct": false, "explanation": "jiǎo 与 jiāo 声调不同（第三声 / 第一声），意思是缴纳，如缴费。"}, {"text": "招", "is_correct": false, "explanation": "zhāo 与 jiāo 声母不同（zh / j），意思是招呼、招手。"}], "explanations": {"叫": "jiào 与 jiāo 声调不同（第四声 / 第一声），意思是叫喊。", "交": "正确答案：交（jiāo），意思是把东西交给别人。", "缴": "jiǎo 与 jiāo 声调不同（第三声 / 第一声），意思是缴纳，如缴费。", "招": "zhāo 与 jiāo 声母不同（zh / j），意思是招呼、招手。"}, "sentence_index": null, "correct_answer": "交"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“卷子”不是可以清洗的东西，“洗”与“卷子”不合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“卷子”不能被煮，“煮”与“卷子”不合。"}, {"text": "交", "is_correct": true, "explanation": "正确答案：“马上交卷子”指考试结束后把试卷交上去。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”一般接水果、花，不能接“卷子”。"}], "explanations": {"洗": "语义：“卷子”不是可以清洗的东西，“洗”与“卷子”不合。", "煮": "语义：“卷子”不能被煮，“煮”与“卷子”不合。", "交": "正确答案：“马上交卷子”指考试结束后把试卷交上去。", "摘": "搭配：“摘”一般接水果、花，不能接“卷子”。"}, "sentence_index": 6, "correct_answer": "交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在学校交了一棵松树。", "explanation": "这里的“交”是结识的意思，但结识的对象只能是人，不能指松树；本题“把东西交给别人”不是这样用。"}, {"text": "我在图书馆交了一张书桌。", "explanation": "这里的“交”是结识的意思，但结识的对象只能是人，不能指书桌；本题“把东西交给别人”不是这样用。"}, {"text": "我在城里交了一座广场。", "explanation": "这里的“交”是结识的意思，但结识的对象只能是人，不能指广场；本题“把东西交给别人”不是这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把卷子交了给老师。", "corrected_sentence": "她把卷子交给了老师。", "error_description": "“了”的位置错误：“交给”是动词加补语，“了”应放在“给”之后，应为“交给了老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理把计划交了小王。", "corrected_sentence": "经理把计划交给了小王。", "error_description": "漏掉补语：把东西交给别人要用“交给”，这里漏掉了“给”，应为“交给了小王”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
