INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86357, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“达到”是做到了想要的水平、数量或地步。", "primary_collocate": null, "pronunciation": "dá dào", "ipa": "tɑ˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他的汉语已经达到了三级。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的气温达到三十五度。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们终于达到了目的。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，他达到了九十分。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校的学生人数达到两千人。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩达到了老师的要求。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想达到什么目标？", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他减肥两个月，终于达到了目标体重。", "target_word": "达到", "complexity_tier": "T3", "furigana": "tā jiǎnféi liǎng gè yuè, zhōngyú dádào le mùbiāo tǐzhòng。", "sentence_source": "generated"}, {"text": "他练了三年，达到了比赛的水平。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车的速度能达到每小时三百公里。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "达到了", "label": "体标"}, {"form": "达到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做到或来到想要的水平、数量或地步", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f52a792-026e-4f8e-a395-edf1e5ec92ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86357, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "达到", "is_correct": true, "explanation": "达到（dá dào）：做到或来到某种水平、数量，即本词。"}, {"text": "大道", "is_correct": false, "explanation": "dà（第四声）与 dá（第二声）声调不同，意思是大路、大道理。"}, {"text": "打到", "is_correct": false, "explanation": "dǎ（第三声）与 dá（第二声）声调不同，意思是打中、打得到。"}, {"text": "打倒", "is_correct": false, "explanation": "dǎ dǎo 两个音节的声调都与 dá dào 不同，意思是打垮、推翻。"}, {"text": "大刀", "is_correct": false, "explanation": "dà 与 dá 声调不同，dāo（第一声）与 dào（第四声）声调也不同，意思是大刀。"}], "explanations": {"达到": "达到（dá dào）：做到或来到某种水平、数量，即本词。", "大道": "dà（第四声）与 dá（第二声）声调不同，意思是大路、大道理。", "打到": "dǎ（第三声）与 dá（第二声）声调不同，意思是打中、打得到。", "打倒": "dǎ dǎo 两个音节的声调都与 dá dào 不同，意思是打垮、推翻。", "大刀": "dà 与 dá 声调不同，dāo（第一声）与 dào（第四声）声调也不同，意思是大刀。"}, "sentence_index": null, "correct_answer": "达到"}, "level_3": {"options": [{"text": "达到", "is_correct": true, "explanation": "正确：「达到了三级」表示汉语水平做到了某一级。"}, {"text": "买", "is_correct": false, "explanation": "语义：「买」指购物，不能用来说汉语水平。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能带「三级」这样的水平作宾语。"}, {"text": "赶到", "is_correct": false, "explanation": "语义：「赶到」指及时到达某地，不表示做到某个水平。"}], "explanations": {"达到": "正确：「达到了三级」表示汉语水平做到了某一级。", "买": "语义：「买」指购物，不能用来说汉语水平。", "吃": "搭配：「吃」不能带「三级」这样的水平作宾语。", "赶到": "语义：「赶到」指及时到达某地，不表示做到某个水平。"}, "sentence_index": 0, "correct_answer": "达到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛，他达到了冠军。", "explanation": "这里应该用〈得到〉。达到表示做到某种水平或数量，获得冠军要说「得到」。"}, {"text": "我们终于达到了车站。", "explanation": "这里「达到」用成了到达地点的意思，而它表示的是做到某种水平、数量或标准，不指到达某个地点。"}, {"text": "他终于达到了作业。", "explanation": "这里应该用〈完成〉。达到用于水平、数量或标准，作业要说「完成」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "达到", "is_correct": true, "explanation": "正确：「想达到什么目标」表示想做到什么目标。"}, {"text": "看", "is_correct": false, "explanation": "语义：「看」指观看，「你想看什么目标」问的是要观看的对象，与想实现的目标意思不同。"}, {"text": "躲", "is_correct": false, "explanation": "语义：「躲」表示避开，不能表示要实现某个目标。"}, {"text": "逃", "is_correct": false, "explanation": "语义：「逃」表示逃离，与想要实现的目标意思相反。"}], "explanations": {"达到": "正确：「想达到什么目标」表示想做到什么目标。", "看": "语义：「看」指观看，「你想看什么目标」问的是要观看的对象，与想实现的目标意思不同。", "躲": "语义：「躲」表示避开，不能表示要实现某个目标。", "逃": "语义：「逃」表示逃离，与想要实现的目标意思相反。"}, "sentence_index": 6, "correct_answer": "达到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很努力，终于达到了同学。", "explanation": "这里应该用〈超过〉。达到指做到某个标准，不表示胜过别人，比同学要用「超过」。"}, {"text": "他终于达到了父母。", "explanation": "这里应该用〈说服〉。达到不能带人作宾语表示说服，说服父母要用「说服」。"}, {"text": "他达到了考试。", "explanation": "这里应该用〈通过〉。达到表示做到某个标准，不表示通过考试，通过考试要说「通过」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的销售额达到着一亿元。", "corrected_sentence": "这家公司的销售额达到了一亿元。", "error_description": "体标错误：「达到」是瞬间完成的动词，不能带「着」表示持续，应把「着」改为「了」，说「达到了一亿元」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的数学成绩没达到了八十分。", "corrected_sentence": "他的数学成绩达到了八十分。", "error_description": "否定错误：「没」表示否定，与「了」不能同用，写成「没达到了」不对，应说「达到了八十分」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
