INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86358, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，指做到某个目标、程度或标准。", "primary_collocate": null, "pronunciation": "dá dào", "ipa": "tɑ˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个产品达到了国家标准。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画达到很高的水平。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的计划达到了目标。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要努力，你一定能达到目标。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个成绩没有达到老师的要求。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的服务达到了标准。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们提前达到了生产目标。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望大家都能达到这个标准。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水温达到一百度就会开。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语终于达到了考试要求。", "target_word": "达到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "达到了", "label": "体标"}, {"form": "达到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做到某个目标、程度或标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f52a792-026e-4f8e-a395-edf1e5ec92ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86358, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "达到", "is_correct": true, "explanation": "达到（dá dào）：做到或来到某个标准，即本词。"}, {"text": "大道", "is_correct": false, "explanation": "dà（第四声）与 dá（第二声）声调不同，意思是大路、大道理。"}, {"text": "打到", "is_correct": false, "explanation": "dǎ（第三声）与 dá（第二声）声调不同，意思是打中、打得到。"}, {"text": "打倒", "is_correct": false, "explanation": "dǎ dǎo 两个音节的声调都与 dá dào 不同，意思是打垮、推翻。"}, {"text": "大刀", "is_correct": false, "explanation": "dà 与 dá 声调不同，dāo（第一声）与 dào（第四声）声调也不同，意思是大刀。"}], "explanations": {"达到": "达到（dá dào）：做到或来到某个标准，即本词。", "大道": "dà（第四声）与 dá（第二声）声调不同，意思是大路、大道理。", "打到": "dǎ（第三声）与 dá（第二声）声调不同，意思是打中、打得到。", "打倒": "dǎ dǎo 两个音节的声调都与 dá dào 不同，意思是打垮、推翻。", "大刀": "dà 与 dá 声调不同，dāo（第一声）与 dào（第四声）声调也不同，意思是大刀。"}, "sentence_index": null, "correct_answer": "达到"}, "level_3": {"options": [{"text": "达到", "is_correct": true, "explanation": "正确：「达到了国家标准」表示产品做到了国家规定的标准。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能带「标准」作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指歌唱，与产品是否符合标准无关。"}, {"text": "跳", "is_correct": false, "explanation": "语义：「跳」指跳动或跳跃，无法表示产品做到某个标准。"}], "explanations": {"达到": "正确：「达到了国家标准」表示产品做到了国家规定的标准。", "吃": "搭配：「吃」不能带「标准」作宾语。", "唱": "语义：「唱」指歌唱，与产品是否符合标准无关。", "跳": "语义：「跳」指跳动或跳跃，无法表示产品做到某个标准。"}, "sentence_index": 0, "correct_answer": "达到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "只要努力，你一定能达到大学。", "explanation": "这里应该用〈考上〉。达到用于水平、标准，考入学校要说「考上」。"}, {"text": "我们终于达到了北京。", "explanation": "这里「达到」用成了到达地点的意思，而它表示的是做到某种水平或标准，不指到达某个地点。"}, {"text": "他提前达到了工作。", "explanation": "这里应该用〈完成〉。达到用于水平、数量或标准，工作要说「完成」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "达到", "is_correct": true, "explanation": "正确：「工人们提前达到了生产目标」表示提前做到了生产目标。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」指丢掉，与完成生产目标的意思相反。"}, {"text": "吵", "is_correct": false, "explanation": "搭配：「吵」不能带「生产目标」作宾语。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：「戴」不能与「生产目标」搭配。"}], "explanations": {"达到": "正确：「工人们提前达到了生产目标」表示提前做到了生产目标。", "扔": "语义：「扔」指丢掉，与完成生产目标的意思相反。", "吵": "搭配：「吵」不能带「生产目标」作宾语。", "戴": "搭配：「戴」不能与「生产目标」搭配。"}, "sentence_index": 6, "correct_answer": "达到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩达到了同学。", "explanation": "这里应该用〈超过〉。达到指做到某个标准，不表示胜过别人，比同学要用「超过」。"}, {"text": "他终于达到了老师。", "explanation": "这里应该用〈说服〉。达到不能带人作宾语表示说服，说服老师要用「说服」。"}, {"text": "他的汉语达到了比赛。", "explanation": "这里应该用〈参加〉。达到表示做到某个标准，不表示参加比赛，参加要说「参加」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于达到着目标。", "corrected_sentence": "他终于达到了目标。", "error_description": "体标错误：「达到」表示已经做到的结果，应用完成标记「了」，写成「达到了」；「着」表示持续状态，与「达到」的结果含义不符，「达到着目标」不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的汉语终于达到着考试要求。", "corrected_sentence": "这种药的效果能达到百分之九十。", "error_description": "体标错误：「达到」表示已经做到的结果，应用完成标记「了」；「着」表示持续状态，与已完成的结果不符，「达到着考试要求」不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
