INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地壳快速震动的自然现象。", "primary_collocate": null, "pronunciation": "dì zhèn", "ipa": "ti˥˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "地震是地壳快速震动造成的自然现象。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次地震的震级是六点五级。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震发生时，地壳里的岩石会突然断裂。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日本在两个板块之间，经常发生地震。", "target_word": "地震", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震之前，有些动物的行为会变得奇怪。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震是一种自然现象，人们还不能准确预报它。", "target_word": "地震", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里每年都有几百次地震，但是大多数人感觉不到。", "target_word": "地震", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震和火山一样，都和地壳的运动有关。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他研究地震二十年，知道地壳是怎么动的。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史上最大的一次地震发生在智利。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场地震", "label": "量词"}, {"form": "一次地震", "label": "量词"}, {"form": "地震带", "label": "复合"}], "register": "中性", "sense_fingerprint": "地震：地壳快速震动的自然现象（科学说明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40bec50f-c43d-494c-bc06-77387795ad2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地震", "is_correct": true, "explanation": "正确：「地震」指地壳快速震动的自然现象，与句子定义相符。"}, {"text": "火山", "is_correct": false, "explanation": "语义：「火山」是岩浆喷发的地质现象，不是地壳快速震动造成的。"}, {"text": "月食", "is_correct": false, "explanation": "语义：「月食」是地球挡住阳光形成的天文现象，与地壳快速震动无关。"}, {"text": "灾变", "is_correct": false, "explanation": "语域：「灾变」偏书面，泛指各种灾难，不专指地壳震动。"}], "explanations": {"地震": "正确：「地震」指地壳快速震动的自然现象，与句子定义相符。", "火山": "语义：「火山」是岩浆喷发的地质现象，不是地壳快速震动造成的。", "月食": "语义：「月食」是地球挡住阳光形成的天文现象，与地壳快速震动无关。", "灾变": "语域：「灾变」偏书面，泛指各种灾难，不专指地壳震动。"}, "sentence_index": 0, "correct_answer": "地震"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震是地球最外面的一层，厚度只有几十公里。", "explanation": "这里应该用〈地壳〉。地震指地壳快速震动的现象，不能指地球最外面的一层；这一层要用〈地壳〉。"}, {"text": "地震喷发时，岩浆会从地下流出来。", "explanation": "这里应该用〈火山〉。地震是地壳的震动，不会喷发；岩浆喷出地面是火山的活动，应该用〈火山〉。"}, {"text": "这台机器的地震很大，我们只好停下来检查。", "explanation": "这里应该用〈震动〉。地震指地壳的自然震动，机器的振动要用〈震动〉，不能用地震。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地震", "is_correct": true, "explanation": "正确：「地震」指地壳快速震动，与“几百次”且“大多数人感觉不到”的语境相符。"}, {"text": "大雪", "is_correct": false, "explanation": "搭配：「大雪」一般用“场”计量，不说“几百次大雪”。"}, {"text": "洪水", "is_correct": false, "explanation": "语义：洪水很容易被察觉，与“大多数人感觉不到”矛盾。"}, {"text": "暴雨", "is_correct": false, "explanation": "语义：暴雨声势明显，很容易被察觉，与“大多数人感觉不到”矛盾。"}], "explanations": {"地震": "正确：「地震」指地壳快速震动，与“几百次”且“大多数人感觉不到”的语境相符。", "大雪": "搭配：「大雪」一般用“场”计量，不说“几百次大雪”。", "洪水": "语义：洪水很容易被察觉，与“大多数人感觉不到”矛盾。", "暴雨": "语义：暴雨声势明显，很容易被察觉，与“大多数人感觉不到”矛盾。"}, "sentence_index": 6, "correct_answer": "地震"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震登陆了沿海城市，很多房子被吹倒了。", "explanation": "这里应该用〈台风〉。地震是大地的震动，不会登陆；登陆沿海城市的是台风，应该用〈台风〉。"}, {"text": "地震卷走了一座小屋。", "explanation": "这里应该用〈龙卷风〉。地震是大地的震动，不能把房屋卷走；卷走房屋的是龙卷风，应该用〈龙卷风〉。"}, {"text": "这条河的地震突然暴涨，淹没了两岸。", "explanation": "这里应该用〈水位〉。地震指大地的震动，不能用来描述河水的涨落；河水的高低要用〈水位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里历史上发生了过地震。", "corrected_sentence": "这里历史上发生过地震。", "error_description": "错误：“了”和“过”不能同时用。表示曾经经历时只用“过”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年我们经历了三个地震。", "corrected_sentence": "去年我们经历了三场地震。", "error_description": "错误：量词用错。地震可用“场”或“次”计量，不能用“个”，应改为“三场地震”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
