INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86363, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主席是社团、协会等组织里主要负责的人。", "primary_collocate": null, "pronunciation": "zhǔ xí", "ipa": "ʈʂu˨˩˦ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "他是我们学生会的主席。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王明当上了足球协会主席。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的俱乐部主席今天不在。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的主席是谁？", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做了三年社团主席。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席对大家说：“谢谢你们。”", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的董事会主席坐在中间。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁想当读书会的主席？", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球协会的主席请大家安静一下。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们选他当音乐协会主席。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副主席", "label": "复合"}, {"form": "主席团", "label": "复合"}], "register": "中性", "sense_fingerprint": "主席：社团、协会等组织里主要负责的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0b2c08-2695-4f5d-b3b3-5f7e6e5c77a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86363, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主席", "is_correct": true, "explanation": "正确答案：主席（zhǔxí），指社团、协会等组织里主要负责的人。"}, {"text": "竹席", "is_correct": false, "explanation": "竹席（zhúxí）第二声与主席（zhǔxí）第三声声调不同，意思是竹子编的席子。"}, {"text": "出席", "is_correct": false, "explanation": "出席（chūxí）的声母是 ch，主席的声母是 zh，且声调不同，意思是参加会议或活动。"}, {"text": "注析", "is_correct": false, "explanation": "注析（zhùxī）与主席的两个音节声调都不同，意思是注释和分析。"}], "explanations": {"主席": "正确答案：主席（zhǔxí），指社团、协会等组织里主要负责的人。", "竹席": "竹席（zhúxí）第二声与主席（zhǔxí）第三声声调不同，意思是竹子编的席子。", "出席": "出席（chūxí）的声母是 ch，主席的声母是 zh，且声调不同，意思是参加会议或活动。", "注析": "注析（zhùxī）与主席的两个音节声调都不同，意思是注释和分析。"}, "sentence_index": null, "correct_answer": "主席"}, "level_3": {"options": [{"text": "主席", "is_correct": true, "explanation": "正确：学生会的负责人称主席，符合句子的语义。"}, {"text": "老师", "is_correct": false, "explanation": "语义：学生会的成员是学生，不会是老师，与“学生会的”矛盾。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是学生会的负责人，句意不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与学生会的职务无关，句子不通。"}], "explanations": {"主席": "正确：学生会的负责人称主席，符合句子的语义。", "老师": "语义：学生会的成员是学生，不会是老师，与“学生会的”矛盾。", "课本": "语义：课本是书，不是学生会的负责人，句意不通。", "厨师": "语义：厨师与学生会的职务无关，句子不通。"}, "sentence_index": 0, "correct_answer": "主席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个部门的主席是王经理。", "explanation": "这里应该用〈主任〉。主席用于学生会、协会等组织，部门的负责人用主任。"}, {"text": "这家工厂的主席下班了。", "explanation": "这里应该用〈厂长〉。主席用于组织的主要负责人，工厂的负责人称厂长。"}, {"text": "大家选了一只新主席。", "explanation": "这里应该用〈位〉。主席指人，计量人应用〈位〉；〈只〉用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主席", "is_correct": true, "explanation": "正确：主席是能坐在中间的人，符合句意。"}, {"text": "会议", "is_correct": false, "explanation": "语义：会议是一项活动，不能“坐”在中间。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不会“坐”，句子不通。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“坐”的主语应是人，座位是供人坐的地方，不能做“坐”的主语。"}], "explanations": {"主席": "正确：主席是能坐在中间的人，符合句意。", "会议": "语义：会议是一项活动，不能“坐”在中间。", "桌子": "语义：桌子是物品，不会“坐”，句子不通。", "座位": "搭配：“坐”的主语应是人，座位是供人坐的地方，不能做“坐”的主语。"}, "sentence_index": 6, "correct_answer": "主席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学院的主席今天来了。", "explanation": "这里应该用〈院长〉。主席用于社团、协会等组织，学院的负责人称院长。"}, {"text": "这个局的主席是王先生。", "explanation": "这里应该用〈局长〉。主席用于社团、协会等组织，局的负责人称局长。"}, {"text": "我们选了一本主席。", "explanation": "这里应该用〈位〉。主席指人，计量人应用〈位〉；〈本〉用于书籍等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "读书会今年选出了一只主席。", "corrected_sentence": "读书会今年选出了一位主席。", "error_description": "错误：量词“只”。“主席”指人，量词应用“位”；“只”多用于动物，不能用于人。正确说法是“一位主席”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "读书会选出了一位新主席们。", "corrected_sentence": "读书会选出了一位新主席。", "error_description": "错误：数量短语“一位新主席”后多加了复数标记“们”。数量短语修饰的名词不能再加“们”，“主席”指一人时直接说“一位新主席”。正确说法是“一位新主席”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
