INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86364, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "会议的主持人，或某些组织、国家的主要领导人。", "primary_collocate": null, "pronunciation": "zhǔ xí", "ipa": "ʈʂu˨˩˦ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "今天的会议由张主席主持。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席去外国参观了。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席宣布会议开始。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席昨天发表了讲话。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，主席请大家发言。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席说：“现在开始投票。”", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次大会的主席是一位女士。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里，国家主席正在欢迎客人。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议主席让大家先坐下。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席把话筒递给了老师。", "target_word": "主席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副主席", "label": "复合"}, {"form": "主席团", "label": "复合"}], "register": "中性", "sense_fingerprint": "主席：会议的主持人，或国家的领导人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0b2c08-2695-4f5d-b3b3-5f7e6e5c77a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86364, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主席", "is_correct": true, "explanation": "正确答案：主席（zhǔxí），指会议的主持人或组织、国家的主要领导人。"}, {"text": "竹席", "is_correct": false, "explanation": "竹席（zhúxí）第二声与主席（zhǔxí）第三声声调不同，意思是竹子编的席子。"}, {"text": "出席", "is_correct": false, "explanation": "出席（chūxí）的声母是 ch，主席的声母是 zh，且声调不同，意思是参加会议或活动。"}, {"text": "注析", "is_correct": false, "explanation": "注析（zhùxī）与主席的两个音节声调都不同，意思是注释和分析。"}], "explanations": {"主席": "正确答案：主席（zhǔxí），指会议的主持人或组织、国家的主要领导人。", "竹席": "竹席（zhúxí）第二声与主席（zhǔxí）第三声声调不同，意思是竹子编的席子。", "出席": "出席（chūxí）的声母是 ch，主席的声母是 zh，且声调不同，意思是参加会议或活动。", "注析": "注析（zhùxī）与主席的两个音节声调都不同，意思是注释和分析。"}, "sentence_index": null, "correct_answer": "主席"}, "level_3": {"options": [{"text": "主席", "is_correct": true, "explanation": "正确：张主席是会议的主持人，符合“由……主持”的语境。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是场所，不能主持会议。"}, {"text": "礼堂", "is_correct": false, "explanation": "搭配：“张”作姓氏只修饰人名，“礼堂”是场所，不能充当“张”的称谓。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，不能主持会议。"}], "explanations": {"主席": "正确：张主席是会议的主持人，符合“由……主持”的语境。", "教室": "语义：教室是场所，不能主持会议。", "礼堂": "搭配：“张”作姓氏只修饰人名，“礼堂”是场所，不能充当“张”的称谓。", "手机": "语义：手机是物品，不能主持会议。"}, "sentence_index": 0, "correct_answer": "主席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教育部的主席昨天发表了讲话。", "explanation": "这里应该用〈部长〉。主席用于会议或组织的主要负责人，教育部的负责人称部长。"}, {"text": "我们开会时选了一把主席。", "explanation": "这里应该用〈位〉。主席指人，计量人应用〈位〉；〈把〉用于有柄的物件或椅子。"}, {"text": "这个节目的主席请大家喝茶。", "explanation": "这里应该用〈主持人〉。主席用于会议或组织，节目的主持人应称主持人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主席", "is_correct": true, "explanation": "正确：主席是人，符合“是一位女士”的主语要求，且与“大会的”搭配。"}, {"text": "会场", "is_correct": false, "explanation": "语义：会场是场所，不是人，不能“是一位女士”。"}, {"text": "日程", "is_correct": false, "explanation": "搭配：“是一位女士”要求主语指人，“日程”不能与之搭配。"}, {"text": "会议", "is_correct": false, "explanation": "语义：会议是活动，不能说它是一位女士，句意不通。"}], "explanations": {"主席": "正确：主席是人，符合“是一位女士”的主语要求，且与“大会的”搭配。", "会场": "语义：会场是场所，不是人，不能“是一位女士”。", "日程": "搭配：“是一位女士”要求主语指人，“日程”不能与之搭配。", "会议": "语义：会议是活动，不能说它是一位女士，句意不通。"}, "sentence_index": 6, "correct_answer": "主席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学院的主席今天来了。", "explanation": "这里应该用〈院长〉。主席用于会议或组织的主要负责人，学院的负责人称院长。"}, {"text": "我们选了一张主席。", "explanation": "这里应该用〈位〉。主席指人，计量人应用〈位〉；〈张〉用于平面的物件。"}, {"text": "这个厂的主席下班了。", "explanation": "这里应该用〈厂长〉。主席用于会议或组织，工厂的负责人称厂长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大会的一只主席已经到了。", "corrected_sentence": "大会的一位主席已经到了。", "error_description": "错误：量词“只”。“主席”指人，量词应用“位”；“只”用于动物等，不能用于人。正确说法是“一位主席”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位新国家主席们今天来访。", "corrected_sentence": "一位新国家主席今天来访。", "error_description": "错误：数量短语“一位新国家主席”后多加了复数标记“们”。数量短语修饰的名词不能再加“们”，去掉“们”即为正确说法“一位新国家主席今天来访。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
