INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86369, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "左是和右相反的一边。", "primary_collocate": null, "pronunciation": "zuǒ", "ipa": "tsuɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他往左看了看，没有人。", "target_word": "左", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走在这条路上，我向左看，看到了一排树。", "target_word": "左", "complexity_tier": "T3", "furigana": "zǒu zài zhè tiáo lù shàng, wǒ xiàng zuǒ kàn, kàn dào le yì pái shù", "sentence_source": "generated"}, {"text": "先向左转，再向右转。", "target_word": "左", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你要的东西在左，不在右。", "target_word": "左", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“请大家向左看。”", "target_word": "左", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上楼梯时，请靠左走。", "target_word": "左", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走到那棵树，就往左拐。", "target_word": "左", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子分不清左和右。", "target_word": "左", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把球往左踢了过去。", "target_word": "左", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先往左看，再往右看，才过马路。", "target_word": "左", "complexity_tier": "T3", "furigana": "tā xiān wǎng zuǒ kàn, zài wǎng yòu kàn, cái guò mǎ lù", "sentence_source": "generated"}], "morphological_forms": [{"form": "左边", "label": "复合"}, {"form": "左手", "label": "复合"}], "register": "通用", "sense_fingerprint": "方位：和右相反的一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e76b94-2d0b-469a-847a-d9083859c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86369, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "左", "is_correct": true, "explanation": "正确：左 zuǒ，意思是和右相反的一边。"}, {"text": "坐", "is_correct": false, "explanation": "zuò（第四声）与 zuǒ（第三声）声调不同，意思是坐下。"}, {"text": "昨", "is_correct": false, "explanation": "zuó（第二声）与 zuǒ（第三声）声调不同，意思是昨天。"}, {"text": "嘴", "is_correct": false, "explanation": "zuǐ 与 zuǒ 韵母不同（i 与 o），意思是嘴巴。"}, {"text": "所", "is_correct": false, "explanation": "suǒ 与 zuǒ 声母不同（s 与 z），意思是处所、所有。"}], "explanations": {"左": "正确：左 zuǒ，意思是和右相反的一边。", "坐": "zuò（第四声）与 zuǒ（第三声）声调不同，意思是坐下。", "昨": "zuó（第二声）与 zuǒ（第三声）声调不同，意思是昨天。", "嘴": "zuǐ 与 zuǒ 韵母不同（i 与 o），意思是嘴巴。", "所": "suǒ 与 zuǒ 声母不同（s 与 z），意思是处所、所有。"}, "sentence_index": null, "correct_answer": "左"}, "level_3": {"options": [{"text": "左", "is_correct": true, "explanation": "正确：“往左看”表示看向左边，与“看了看”搭配，句意通顺。"}, {"text": "中", "is_correct": false, "explanation": "语义：“往中看”指看向中间，与“看向一侧、没有人”的语境不符。"}, {"text": "侧", "is_correct": false, "explanation": "搭配：“往侧”不成词，表示一侧要说“往旁边”。"}, {"text": "边", "is_correct": false, "explanation": "搭配：“往边”不能单独作方位，需说“往旁边”或“往边上”。"}], "explanations": {"左": "正确：“往左看”表示看向左边，与“看了看”搭配，句意通顺。", "中": "语义：“往中看”指看向中间，与“看向一侧、没有人”的语境不符。", "侧": "搭配：“往侧”不成词，表示一侧要说“往旁边”。", "边": "搭配：“往边”不能单独作方位，需说“往旁边”或“往边上”。"}, "sentence_index": 0, "correct_answer": "左"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛有五十左的人参加。", "explanation": "这里应该用〈左右〉，表示大约。〈左〉单用没有“大约”的义项，“五十左”不成立。"}, {"text": "他用左画画，画得很好。", "explanation": "这里应该用〈左手〉。〈左〉不能单独修饰动词作工具，说明用哪只手要说“用左手”。"}, {"text": "她是个左，写字和吃饭都用左手。", "explanation": "这里应该用〈左撇子〉，指习惯用左手的人。〈左〉单用不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86369, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "左", "is_correct": true, "explanation": "正确：左 zuǒ，意思是和右相反的一边。"}, {"text": "做", "is_correct": false, "explanation": "zuò（第四声）与 zuǒ（第三声）声调不同，意思是做。"}, {"text": "组", "is_correct": false, "explanation": "zǔ 与 zuǒ 韵母不同（u 与 uo），意思是小组。"}, {"text": "躲", "is_correct": false, "explanation": "duǒ 与 zuǒ 声母不同（d 与 z），意思是躲藏。"}, {"text": "火", "is_correct": false, "explanation": "huǒ 与 zuǒ 声母不同（h 与 z），意思是火。"}], "explanations": {"左": "正确：左 zuǒ，意思是和右相反的一边。", "做": "zuò（第四声）与 zuǒ（第三声）声调不同，意思是做。", "组": "zǔ 与 zuǒ 韵母不同（u 与 uo），意思是小组。", "躲": "duǒ 与 zuǒ 声母不同（d 与 z），意思是躲藏。", "火": "huǒ 与 zuǒ 声母不同（h 与 z），意思是火。"}, "sentence_index": null, "correct_answer": "左"}, "level_3": {"options": [{"text": "左", "is_correct": true, "explanation": "正确：“往左拐”表示向左转弯，“左”与“拐”搭配，句意通顺。"}, {"text": "下", "is_correct": false, "explanation": "语义：“往下拐”指向下方，与平面上的转弯方向不符。"}, {"text": "上", "is_correct": false, "explanation": "搭配：“往上拐”指向高处，转弯不说朝上。"}, {"text": "外", "is_correct": false, "explanation": "搭配：转弯不说“往外拐”，“往外”一般只用于走出某处。"}], "explanations": {"左": "正确：“往左拐”表示向左转弯，“左”与“拐”搭配，句意通顺。", "下": "语义：“往下拐”指向下方，与平面上的转弯方向不符。", "上": "搭配：“往上拐”指向高处，转弯不说朝上。", "外": "搭配：转弯不说“往外拐”，“往外”一般只用于走出某处。"}, "sentence_index": 6, "correct_answer": "左"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路口左了一下，车就开走了。", "explanation": "这里应该用〈拐〉。〈左〉不能单独作动词表示转弯，要说“左拐”或“拐”。"}, {"text": "他遇到难题，左为难，不知道怎么办。", "explanation": "这里应该用〈左右〉（左右为难）。〈左〉单用不能与“为难”搭配。"}, {"text": "我们两人的意见左，常常吵架。", "explanation": "这里应该用〈相左〉，表示意见不一致。〈左〉单用没有这个义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我左的人是老师。", "corrected_sentence": "我左边的人是老师。", "error_description": "“左”作定语修饰名词时要说“左边的人”。原句“左的人”少了“边”，是错误形式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他往左的走了几步，就停了下来。", "corrected_sentence": "他往左走了几步，就停了下来。", "error_description": "多加“的”：“往左”是状语修饰动词，后面不能再加“的”，应为“往左走了几步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
