INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人或动植物已经生存的年数。", "primary_collocate": null, "pronunciation": "nián líng", "ipa": "njɛn˧˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这棵大树的年龄已经超过三百岁。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "兽医可以从牙齿看出马的年龄。", "target_word": "年龄", "complexity_tier": "T3", "furigana": "shòu yī kě yǐ cóng yá chǐ kàn chū mǎ de nián líng", "sentence_source": "generated"}, {"text": "乌龟的年龄很大，有的能活一百多年。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们可以数树的年轮，知道它的年龄。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小狗的年龄只有两个月。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家通过骨头测出恐龙死时的年龄。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有一棵千年古树，没人知道它的确切年龄。", "target_word": "年龄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般来说，狗的年龄越大，就越不爱动。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大象的年龄可以从牙齿和身体大小判断。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些树的年龄都差不多，是同一年种的。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "年龄段", "label": "复合"}, {"form": "年龄层", "label": "复合"}, {"form": "年齡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "年龄：人、动物或植物已经生存的年数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40bec50f-c43d-494c-bc06-77387795ad2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": true, "explanation": "年龄指生物已经生存的年数，“超过三百岁”说的正是这个意思，句意正确。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不能用“岁”计算年数，“树叶超过三百岁”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有年数，不能说“超过三百岁”。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：高度不用“岁”计量，应说“米”，不能说“高度超过三百岁”。"}], "explanations": {"年龄": "年龄指生物已经生存的年数，“超过三百岁”说的正是这个意思，句意正确。", "树叶": "语义：树叶不能用“岁”计算年数，“树叶超过三百岁”句意不通。", "颜色": "语义：颜色没有年数，不能说“超过三百岁”。", "高度": "搭配：高度不用“岁”计量，应说“米”，不能说“高度超过三百岁”。"}, "sentence_index": 0, "correct_answer": "年龄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项工程的年龄是两年。", "explanation": "这里应该用〈工期〉。施工所需的时间要用工期，年龄只用于人、动物和植物。"}, {"text": "这棵树的年龄是1985年。", "explanation": "这句把年龄理解成了种下的年份。年龄表示已经生存了多少年，不是哪一年。"}, {"text": "这场演出的年龄是两个小时。", "explanation": "这里应该用〈时长〉。演出持续的时间要用时长，年龄只用于人、动物和植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": true, "explanation": "年龄指生存的年数，“确切”修饰它说得通，句意正确。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：树没有饭量，不能谈“确切的饭量”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：树没有脾气，这句话无法成立。"}, {"text": "心情", "is_correct": false, "explanation": "语义：树没有心情，“没人知道它的确切心情”句意不通。"}], "explanations": {"年龄": "年龄指生存的年数，“确切”修饰它说得通，句意正确。", "饭量": "语义：树没有饭量，不能谈“确切的饭量”。", "脾气": "语义：树没有脾气，这句话无法成立。", "心情": "语义：树没有心情，“没人知道它的确切心情”句意不通。"}, "sentence_index": 6, "correct_answer": "年龄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盒牛奶的年龄是十天。", "explanation": "这里应该用〈保质期〉。食品能存放多久要用保质期，年龄只用于人、动物和植物。"}, {"text": "这种树每年的年龄只有三天。", "explanation": "这里应该用〈花期〉。树每年开花持续的时间要用花期，年龄指生存的年数。"}, {"text": "她的年龄已经十年了。", "explanation": "这里应该用〈岁〉。年龄要用“岁”计量，“十年”说的是经历的时长，像工龄那样；应说“她已经十岁了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只狗的年龄得了三岁。", "corrected_sentence": "这只狗的年龄是三岁。", "error_description": "搭配错误：“得了”不能与“年龄”搭配，应说“这只狗的年龄是三岁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵树的年龄是三百个。", "corrected_sentence": "这棵树的年龄是三百岁。", "error_description": "量词错误：年龄的单位应说“岁”，不能用“个”。正确说法是“三百岁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
