INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指画、照片等平面的图像。", "primary_collocate": null, "pronunciation": "tú piàn", "ipa": "tʰu˧˥ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "书里有很多漂亮的图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张图片发给我。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上找了一张图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些图片是谁画的？", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机里有很多图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一些图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图片太小，看不清楚。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢看有图片的书。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有一张大图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把图片放在文章里。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "圖片", "label": "繁体"}], "register": "中性", "sense_fingerprint": "图片：画、照片等平面的图像，可发送、查找、放进文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc0b2c08-2695-4f5d-b3b3-5f7e6e5c77a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图片", "is_correct": true, "explanation": "正确：图片是平面图像，可以用“漂亮的”修饰，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“漂亮”形容可看的对象，声音不能用“漂亮”形容。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“漂亮的”不搭配“味道”，味道应说“好”或“香”。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是刺耳的声响，不能用“漂亮”修饰，书里也不会有。"}], "explanations": {"图片": "正确：图片是平面图像，可以用“漂亮的”修饰，符合句意。", "声音": "语义：“漂亮”形容可看的对象，声音不能用“漂亮”形容。", "味道": "搭配：“漂亮的”不搭配“味道”，味道应说“好”或“香”。", "噪音": "语义：噪音是刺耳的声响，不能用“漂亮”修饰，书里也不会有。"}, "sentence_index": 0, "correct_answer": "图片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在墙上挂了一根图片。", "explanation": "这里应该用〈张〉。图片是平面的，量词应用〈张〉；〈根〉用于细长的东西，不能用于图片。"}, {"text": "这篇图片的作者是李老师。", "explanation": "这里应该用〈张〉。〈篇〉用于文章，图片的量词是〈张〉。"}, {"text": "我买了一只图片。", "explanation": "这里应该用〈张〉。图片是平面的，量词应用〈张〉；〈只〉用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图片", "is_correct": true, "explanation": "正确：图片可以被看，也可以用“太小”描述，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是实物，说它太小而“看不清楚”不合逻辑。"}, {"text": "床", "is_correct": false, "explanation": "搭配：“看不清楚”通常说文字或画面，“床”不是可被看清的对象。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：说地毯太小而“看不清楚”不合常理，句意不通。"}], "explanations": {"图片": "正确：图片可以被看，也可以用“太小”描述，符合句意。", "桌子": "语义：桌子是实物，说它太小而“看不清楚”不合逻辑。", "床": "搭配：“看不清楚”通常说文字或画面，“床”不是可被看清的对象。", "地毯": "语义：说地毯太小而“看不清楚”不合常理，句意不通。"}, "sentence_index": 6, "correct_answer": "图片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我听了一张图片。", "explanation": "这里应该用〈唱片〉。〈听〉搭配唱片、录音等声音，图片是看的，不能听。"}, {"text": "这首图片很好看。", "explanation": "这里应该用〈张〉。〈首〉用于歌曲、诗词，图片的量词是〈张〉。"}, {"text": "我唱了一张图片。", "explanation": "这里应该用〈歌曲〉。〈唱〉搭配歌曲，图片是看的，不能唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把那只图片保存下来了。", "corrected_sentence": "我已经把那张图片保存下来了。", "error_description": "错误：量词“只”。“图片”是平面的，量词应用“张”；“只”用于动物等，不能用于图片。正确说法是“那张图片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他发来一张大图片们。", "corrected_sentence": "他发来一张大图片。", "error_description": "错误：数量短语“一张大图片”后多加了复数标记“们”。数量短语修饰的名词不能再加“们”，去掉“们”即为正确说法“一张大图片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12cd7271-c5af-44c5-9978-1bba5004f07c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“反”相对，“挂正”与“挂反”构成反义。"}, {"text": "高", "is_correct": false, "explanation": "“高”指高度，与方向或样子的相对义无关。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”指光线明亮，与方向或样子的相对义无关。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”指速度，与方向或样子的相对义无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“反”相对，“挂正”与“挂反”构成反义。", "高": "“高”指高度，与方向或样子的相对义无关。", "亮": "“亮”指光线明亮，与方向或样子的相对义无关。", "慢": "“慢”指速度，与方向或样子的相对义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“反”相对，“字是正的”与“字是反的”构成反义。"}, {"text": "白", "is_correct": false, "explanation": "“白”指颜色，与方向或样子的相对义无关。"}, {"text": "大", "is_correct": false, "explanation": "“大”指大小，与方向或样子的相对义无关。"}, {"text": "冷", "is_correct": false, "explanation": "“冷”指温度，与方向或样子的相对义无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“反”相对，“字是正的”与“字是反的”构成反义。", "白": "“白”指颜色，与方向或样子的相对义无关。", "大": "“大”指大小，与方向或样子的相对义无关。", "冷": "“冷”指温度，与方向或样子的相对义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“反”是说和原来的方向、样子正好相反。", "primary_collocate": null, "pronunciation": "fǎn", "ipa": "fan²¹⁴", "syllable_count": 1, "sentences": [{"text": "你的鞋穿反了。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书拿反了。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把衣服穿反了，大家都笑了。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画挂反了，快改一下。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "方向反了，我们走错路了。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把名字写反了。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明看反了地图，所以走错了路。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字写反了，左右要换过来。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把钥匙插反了，怎么也插不进去。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜子里的字全都是反的。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反面", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容方向、位置或样子与原来正好相对，常说穿反了、拿反了、写反了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2360d38e-578e-4142-a840-d1924b1155a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反", "is_correct": true, "explanation": "fǎn 与目标词同音同调，意思是方向或样子相反。"}, {"text": "翻", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转、翻动。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是米饭、饭食。"}, {"text": "赶", "is_correct": false, "explanation": "gǎn 与 fǎn 声母不同（g 与 f），声调相同，意思是赶上、驱赶。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn 与 fǎn 声母不同（y 与 f），声调相同，意思是眼睛。"}], "explanations": {"反": "fǎn 与目标词同音同调，意思是方向或样子相反。", "翻": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转、翻动。", "饭": "fàn（第四声）与 fǎn（第三声）声调不同，意思是米饭、饭食。", "赶": "gǎn 与 fǎn 声母不同（g 与 f），声调相同，意思是赶上、驱赶。", "眼": "yǎn 与 fǎn 声母不同（y 与 f），声调相同，意思是眼睛。"}, "sentence_index": null, "correct_answer": "反"}, "level_3": {"options": [{"text": "反", "is_correct": true, "explanation": "“穿反了”表示方向或位置与正确的相反，符合句意。"}, {"text": "晾", "is_correct": false, "explanation": "语法：“晾”是动词，不能作“穿”的结果补语，“穿晾了”不成立。"}, {"text": "凉", "is_correct": false, "explanation": "语义：“凉”描述温度，不能说鞋“穿凉了”来表示穿法出错。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”不能作“穿”的结果补语，“穿亮了”不成立。"}], "explanations": {"反": "“穿反了”表示方向或位置与正确的相反，符合句意。", "晾": "语法：“晾”是动词，不能作“穿”的结果补语，“穿晾了”不成立。", "凉": "语义：“凉”描述温度，不能说鞋“穿凉了”来表示穿法出错。", "亮": "搭配：“亮”不能作“穿”的结果补语，“穿亮了”不成立。"}, "sentence_index": 0, "correct_answer": "反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙反进了抽屉。", "explanation": "这里应该用〈放〉。“反”不能表示放入、收进的意思，这里的说法不通。"}, {"text": "他每天都反自己的毛病。", "explanation": "这里的“反”是反省的意思，但“反”单独没有这个意思，应用〈反省〉。"}, {"text": "他给客人反了一杯茶。", "explanation": "这里应该用〈倒〉。“反”不能表示倒茶的意思，倒茶要用〈倒〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "反", "is_correct": true, "explanation": "fǎn 与目标词同音同调，意思是方向或样子相反。"}, {"text": "范", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是范围、模范。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn 与 fǎn 声母不同（h 与 f），声调相同，意思是呼喊。"}, {"text": "访", "is_correct": false, "explanation": "fǎng 与 fǎn 韵母不同（ang 与 an），声调相同，意思是拜访。"}, {"text": "烦", "is_correct": false, "explanation": "fán（第二声）与 fǎn（第三声）声调不同，意思是烦躁、麻烦。"}], "explanations": {"反": "fǎn 与目标词同音同调，意思是方向或样子相反。", "范": "fàn（第四声）与 fǎn（第三声）声调不同，意思是范围、模范。", "喊": "hǎn 与 fǎn 声母不同（h 与 f），声调相同，意思是呼喊。", "访": "fǎng 与 fǎn 韵母不同（ang 与 an），声调相同，意思是拜访。", "烦": "fán（第二声）与 fǎn（第三声）声调不同，意思是烦躁、麻烦。"}, "sentence_index": null, "correct_answer": "反"}, "level_3": {"options": [{"text": "反", "is_correct": true, "explanation": "“看反了地图”表示看颠倒了方向，与“走错了路”的因果相符。"}, {"text": "清", "is_correct": false, "explanation": "语义：“看清了地图”表示看得清楚，与“走错了路”的因果矛盾。"}, {"text": "懂", "is_correct": false, "explanation": "语义：“看懂了地图”表示理解正确，与“走错了路”的因果矛盾。"}, {"text": "准", "is_correct": false, "explanation": "搭配：“看准”多用于看准目标或时机，与“地图”搭配不自然。"}], "explanations": {"反": "“看反了地图”表示看颠倒了方向，与“走错了路”的因果相符。", "清": "语义：“看清了地图”表示看得清楚，与“走错了路”的因果矛盾。", "懂": "语义：“看懂了地图”表示理解正确，与“走错了路”的因果矛盾。", "准": "搭配：“看准”多用于看准目标或时机，与“地图”搭配不自然。"}, "sentence_index": 6, "correct_answer": "反"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快就反回了老家。", "explanation": "这里应该用〈返回〉。“反”单独没有“返回”的意思，这里的说法不通。"}, {"text": "他把球反给了对方。", "explanation": "这里应该用〈传〉。“反”不能表示传递、传给的意思，这里的用法不成立。"}, {"text": "他把这份报告反给了老师。", "explanation": "这里应该用〈交〉。“反”不能表示交给、呈交的意思，这里的用法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把眼镜戴了反。", "corrected_sentence": "他把眼镜戴反了。", "error_description": "“反”是结果补语，应紧接动词“戴”之后，再接“了”。说成“戴了反”是语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把地图拿了反。", "corrected_sentence": "我把地图拿反了。", "error_description": "“反”是结果补语，应紧接动词“拿”之后，再接“了”。说成“拿了反”是语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺", "is_correct": true, "explanation": "“顺”与“反”相对，“顺着走”与“反着走”构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”是动作动词，与“反”的方向相对义无关。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”是动作动词，与“反”的方向相对义无关。"}, {"text": "停", "is_correct": false, "explanation": "“停”指动作中止，与“反”的方向相对义无关。"}], "correct_answer": "顺", "explanations": {"顺": "“顺”与“反”相对，“顺着走”与“反着走”构成反义。", "跑": "“跑”是动作动词，与“反”的方向相对义无关。", "跳": "“跳”是动作动词，与“反”的方向相对义无关。", "停": "“停”指动作中止，与“反”的方向相对义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺", "is_correct": true, "explanation": "“顺”与“反”相对，“顺着想”与“反着想”构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”表示明白、不含糊，与“反”的相反义无关。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”表示繁多、不简单，与“反”的相反义无关。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”表示智力高，与“反”的相反义无关。"}], "correct_answer": "顺", "explanations": {"顺": "“顺”与“反”相对，“顺着想”与“反着想”构成反义。", "清楚": "“清楚”表示明白、不含糊，与“反”的相反义无关。", "复杂": "“复杂”表示繁多、不简单，与“反”的相反义无关。", "聪明": "“聪明”表示智力高，与“反”的相反义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“反”作动词，指把东西翻转过来，或做法与别人、与要求相违背。", "primary_collocate": null, "pronunciation": "fǎn", "ipa": "fan²¹⁴", "syllable_count": 1, "sentences": [{"text": "他总爱和我反着干。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把手心反过来看看。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把杯子反过来放在桌上。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们反着走路，觉得很好玩。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总跟老师反着来。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说东，你偏说西，为什么总是反着说？", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两个字的顺序反过来写。", "target_word": "反过来", "complexity_tier": "T3", "furigana": "qǐng bǎ zhè liǎng gè zì de shùnxù fǎn guò lái xiě。", "sentence_source": "generated"}, {"text": "妈妈让他早睡，他却反着做。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把鞋反过来晾，里面干得快。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总跟大家反着想，大家都觉得他很怪。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反过来", "label": "复合"}, {"form": "反着", "label": "体标"}], "register": "中性", "sense_fingerprint": "作动词，表示把东西翻转过来，或做法与别人、与要求相违背，如反过来、反着干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2360d38e-578e-4142-a840-d1924b1155a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反", "is_correct": true, "explanation": "fǎn 与目标词同音同调，意思是翻转、相反。"}, {"text": "粉", "is_correct": false, "explanation": "fěn 与 fǎn 韵母不同（en 与 an），声调相同，意思是粉末、粉色。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是米饭、饭食。"}, {"text": "赶", "is_correct": false, "explanation": "gǎn 与 fǎn 声母不同（g 与 f），声调相同，意思是赶上、驱赶。"}, {"text": "犯", "is_correct": false, "explanation": "fàn（第四声）与 fǎn 声调不同，意思是犯错、侵犯。"}], "explanations": {"反": "fǎn 与目标词同音同调，意思是翻转、相反。", "粉": "fěn 与 fǎn 韵母不同（en 与 an），声调相同，意思是粉末、粉色。", "饭": "fàn（第四声）与 fǎn（第三声）声调不同，意思是米饭、饭食。", "赶": "gǎn 与 fǎn 声母不同（g 与 f），声调相同，意思是赶上、驱赶。", "犯": "fàn（第四声）与 fǎn 声调不同，意思是犯错、侵犯。"}, "sentence_index": null, "correct_answer": "反"}, "level_3": {"options": [{"text": "反", "is_correct": true, "explanation": "“反着干”表示做法与对方或常规相反，符合句意。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲着干”表示回避，与句中“和我”一起做事的语境矛盾。"}, {"text": "瞒", "is_correct": false, "explanation": "搭配：“瞒着”需要被隐瞒的对象，“和我一起”做事时不能这样用。"}, {"text": "逃", "is_correct": false, "explanation": "搭配：“逃”不能接“着干”表示做事方式，“逃着干”不成立。"}], "explanations": {"反": "“反着干”表示做法与对方或常规相反，符合句意。", "躲": "语义：“躲着干”表示回避，与句中“和我”一起做事的语境矛盾。", "瞒": "搭配：“瞒着”需要被隐瞒的对象，“和我一起”做事时不能这样用。", "逃": "搭配：“逃”不能接“着干”表示做事方式，“逃着干”不成立。"}, "sentence_index": 0, "correct_answer": "反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把新买的书反到了书架上。", "explanation": "这里应该用〈放〉。“反”不能表示把东西放置到某处的意思，这里的说法不通。"}, {"text": "他每天晚上都反自己的过错。", "explanation": "这里的“反”是反省的意思，但“反”单独没有这个意思，应用〈反省〉。"}, {"text": "他给我反了一杯水。", "explanation": "这里应该用〈倒〉。倒水表示把液体注出，“反”不能表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "反", "is_correct": true, "explanation": "fǎn 与目标词同音同调，意思是翻转、相反。"}, {"text": "范", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是范围、模范。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn 与 fǎn 声母不同（h 与 f），声调相同，意思是呼喊。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn 与 fǎn 声母不同（y 与 f），声调相同，意思是眼睛。"}, {"text": "访", "is_correct": false, "explanation": "fǎng 与 fǎn 韵母不同（ang 与 an），声调相同，意思是拜访。"}], "explanations": {"反": "fǎn 与目标词同音同调，意思是翻转、相反。", "范": "fàn（第四声）与 fǎn（第三声）声调不同，意思是范围、模范。", "喊": "hǎn 与 fǎn 声母不同（h 与 f），声调相同，意思是呼喊。", "眼": "yǎn 与 fǎn 声母不同（y 与 f），声调相同，意思是眼睛。", "访": "fǎng 与 fǎn 韵母不同（ang 与 an），声调相同，意思是拜访。"}, "sentence_index": null, "correct_answer": "反"}, "level_3": {"options": [{"text": "反过来", "is_correct": true, "explanation": "“顺序反过来写”表示按相反的次序书写，符合句意。"}, {"text": "写下来", "is_correct": false, "explanation": "搭配：“写下来”表示记录，不能用来说明“顺序”的调整，句子不通。"}, {"text": "擦掉", "is_correct": false, "explanation": "语义：“擦掉”表示去除，与“顺序”的调整不兼容，句子语义不通。"}, {"text": "念出来", "is_correct": false, "explanation": "语义：“念出来”表示朗读，不能表示调整顺序。"}], "explanations": {"反过来": "“顺序反过来写”表示按相反的次序书写，符合句意。", "写下来": "搭配：“写下来”表示记录，不能用来说明“顺序”的调整，句子不通。", "擦掉": "语义：“擦掉”表示去除，与“顺序”的调整不兼容，句子语义不通。", "念出来": "语义：“念出来”表示朗读，不能表示调整顺序。"}, "sentence_index": 6, "correct_answer": "反过来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这本书反进了书架。", "explanation": "这里应该用〈放〉。“反”不能表示把东西放入某处的意思，这里的说法不通。"}, {"text": "他把这个问题反给了领导。", "explanation": "这里应该用〈反映〉。“反”单独没有“汇报、告知”的意思，这里的用法不成立。"}, {"text": "他一拳反给了对手。", "explanation": "这里应该用〈还〉。“反”不能表示还击的意思，还击要说〈还〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书反过放在桌上。", "corrected_sentence": "他把书反过来放在桌上。", "error_description": "“反过来”是一个整体，这里漏掉了“来”，应说“反过来放”。正确说法是“他把书反过来放在桌上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把词语念着反。", "corrected_sentence": "他把词语反着念。", "error_description": "“反着”作状语，应放在动词“念”之前。说成“念着反”是语序错误，不符合汉语的状语位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
