INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86395, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“送”是把东西拿给别人，或者陪别人走一段路。", "primary_collocate": null, "pronunciation": "sòng", "ipa": "sʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "爸爸送我一块新手表当生日礼物。", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把信送到了邻居手里。", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨，我开车送你去机场。", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天谁送孩子去幼儿园？", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想送朋友一张音乐会的票。", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送我到地铁站就回去了。", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市会把大米送上门。", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，我们给老人送了水果。", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送给同学一张自己画的画。", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友出国那天，我们都去机场送他。", "target_word": "送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送了", "label": "完成体"}, {"form": "送过", "label": "经历体"}, {"form": "送礼", "label": "复合词"}], "register": "中性", "sense_fingerprint": "送：把东西拿给别人；陪别人走一段路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f4d125-09bd-4a29-83b8-15c3ccd853c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86395, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "送", "is_correct": true, "explanation": "「送」（sòng，第四声）是正确答案，意思是把东西拿给别人或陪别人走一段路。"}, {"text": "松", "is_correct": false, "explanation": "「松」（sōng，第一声）与「送」只有声调不同，意思是松开。"}, {"text": "怂", "is_correct": false, "explanation": "「怂」（sǒng，第三声）与「送」声调不同，意思是胆小、怯懦。"}, {"text": "从", "is_correct": false, "explanation": "「从」（cóng）与「送」声母 c、s 不同，声调也不同，意思是跟随、从。"}, {"text": "纵", "is_correct": false, "explanation": "「纵」（zòng）与「送」声母 z、s 不同，声调相同，意思是放纵、纵然。"}], "explanations": {"送": "「送」（sòng，第四声）是正确答案，意思是把东西拿给别人或陪别人走一段路。", "松": "「松」（sōng，第一声）与「送」只有声调不同，意思是松开。", "怂": "「怂」（sǒng，第三声）与「送」声调不同，意思是胆小、怯懦。", "从": "「从」（cóng）与「送」声母 c、s 不同，声调也不同，意思是跟随、从。", "纵": "「纵」（zòng）与「送」声母 z、s 不同，声调相同，意思是放纵、纵然。"}, "sentence_index": null, "correct_answer": "送"}, "level_3": {"options": [{"text": "送", "is_correct": true, "explanation": "正确：「送」表示把东西交给别人，与「当生日礼物」的句意相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」是丢弃，与「当生日礼物」的赠予意思相反。"}, {"text": "戴", "is_correct": false, "explanation": "配价：「戴」的对象是手表，不能说「戴我一块新手表」来表示把表给我。"}, {"text": "卖", "is_correct": false, "explanation": "配价：「卖」的接受者要用「卖给」，不能直接说「卖我一块手表」。"}], "explanations": {"送": "正确：「送」表示把东西交给别人，与「当生日礼物」的句意相符。", "扔": "语义：「扔」是丢弃，与「当生日礼物」的赠予意思相反。", "戴": "配价：「戴」的对象是手表，不能说「戴我一块新手表」来表示把表给我。", "卖": "配价：「卖」的接受者要用「卖给」，不能直接说「卖我一块手表」。"}, "sentence_index": 0, "correct_answer": "送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我送奶奶在家里看电视。", "explanation": "这里应该用〈陪〉。送表示带人离开或陪人走一段路，在家看电视没有离开也没有行走，不能用「送」。"}, {"text": "他送着球跑进了球场。", "explanation": "这里应该用〈拿〉。拿是用手持着东西，送是把东西交给对方或陪人离开，不能说「送着球跑」。"}, {"text": "妹妹放假回家，全家人去车站送她。", "explanation": "这里应该用〈接〉。妹妹是回家，应该说接；送表示人离开时的送别，用在这里说反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86395, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "送", "is_correct": true, "explanation": "「送」（sòng，第四声）是正确答案，意思是把东西拿给别人或陪别人走一段路。"}, {"text": "聪", "is_correct": false, "explanation": "「聪」（cōng）与「送」声母 c、s 不同，声调也不同，意思是聪明。"}, {"text": "总", "is_correct": false, "explanation": "「总」（zǒng）与「送」声母 z、s 不同，声调也不同，意思是总是、总共。"}, {"text": "丧", "is_correct": false, "explanation": "「丧」（sàng）与「送」韵母 ong、ang 不同，意思是丧失。"}, {"text": "宗", "is_correct": false, "explanation": "「宗」（zōng）与「送」声母 z、s 不同，声调也不同，意思是宗族、宗派。"}], "explanations": {"送": "「送」（sòng，第四声）是正确答案，意思是把东西拿给别人或陪别人走一段路。", "聪": "「聪」（cōng）与「送」声母 c、s 不同，声调也不同，意思是聪明。", "总": "「总」（zǒng）与「送」声母 z、s 不同，声调也不同，意思是总是、总共。", "丧": "「丧」（sàng）与「送」韵母 ong、ang 不同，意思是丧失。", "宗": "「宗」（zōng）与「送」声母 z、s 不同，声调也不同，意思是宗族、宗派。"}, "sentence_index": null, "correct_answer": "送"}, "level_3": {"options": [{"text": "送", "is_correct": true, "explanation": "正确：「送」表示把东西交给对方，与句意「超市送货上门」相符。"}, {"text": "抢", "is_correct": false, "explanation": "语义：「抢」是强行夺取，与「超市会」这种正常经营的语境不符。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：「烧」的对象不能是大米作为可以送去的东西，「烧大米上门」不成立。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」只能接衣服、鞋袜等，不能用于大米。"}], "explanations": {"送": "正确：「送」表示把东西交给对方，与句意「超市送货上门」相符。", "抢": "语义：「抢」是强行夺取，与「超市会」这种正常经营的语境不符。", "烧": "搭配：「烧」的对象不能是大米作为可以送去的东西，「烧大米上门」不成立。", "穿": "搭配：「穿」只能接衣服、鞋袜等，不能用于大米。"}, "sentence_index": 6, "correct_answer": "送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把水送进了杯子。", "explanation": "这里应该用〈倒〉。倒是把液体注入容器，送是把东西交给对方或陪人离开，不说「送水进杯子」。"}, {"text": "朋友回国那天，我们都去机场送他。", "explanation": "这里应该用〈迎〉。朋友是回国，应该说迎接；送表示人离开时的送别，用在这里说反了。"}, {"text": "他送下了帽子，向大家鞠躬。", "explanation": "这里应该用〈摘〉。摘是把戴着的帽子取下来，送是把东西交给对方或陪人离开，不能用来表示脱帽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我开车你送去车站。", "corrected_sentence": "我开车送你去车站。", "error_description": "错误：「你送去车站」；正确：「送你去车站」。「送」的宾语「你」应放在「送」之后，语序颠倒后句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把一张画送了给同学。", "corrected_sentence": "她把一张画送给了同学。", "error_description": "错误：「送了给」；正确：「送给了」。「了」应放在「送给」这个动补结构之后，表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
