INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指单独的一个人，或没有他人陪伴的状态。", "primary_collocate": null, "pronunciation": "yí ge rén", "ipa": "i˧˥ kə ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他一个人住在大城市。", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢一个人看书。", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人去超市买东西。", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间屋子里，他一个人住了三年。", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人在家，我有点儿害怕。", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人走在回家的路上。", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常一个人听音乐。", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天你一个人来的吗？", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人吃饭也很自在。", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人带着孩子过日子。", "target_word": "一个人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "单独一人；没有他人陪伴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2360d38e-578e-4142-a840-d1924b1155a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一个人", "is_correct": true, "explanation": "“他一个人住在大城市”表示单独一人居住，符合句意。"}, {"text": "夫妻", "is_correct": false, "explanation": "语义：“夫妻”指两人，与“他”单独居住的句意矛盾。"}, {"text": "双胞胎", "is_correct": false, "explanation": "语义：“双胞胎”指同时出生的两人，与单数的“他”不符。"}, {"text": "三口人", "is_correct": false, "explanation": "语义：“三口人”指三个人，与单数的“他”矛盾。"}], "explanations": {"一个人": "“他一个人住在大城市”表示单独一人居住，符合句意。", "夫妻": "语义：“夫妻”指两人，与“他”单独居住的句意矛盾。", "双胞胎": "语义：“双胞胎”指同时出生的两人，与单数的“他”不符。", "三口人": "语义：“三口人”指三个人，与单数的“他”矛盾。"}, "sentence_index": 0, "correct_answer": "一个人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子一个人放在角落里。", "explanation": "这里应该用〈单独〉。“一个人”只用于指人，不能指物体，桌子应说“单独”。"}, {"text": "那只狗一个人跑到了山上。", "explanation": "这里应该用〈独自〉。“一个人”只指人，不能指狗，指动物要说〈独自〉。"}, {"text": "这座山一个人立在江边。", "explanation": "这里应该用〈孤零零〉。“一个人”只指人，不能指山，指山要说〈孤零零〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一个人", "is_correct": true, "explanation": "“周末我常常一个人听音乐”表示独自一人，符合句意。"}, {"text": "老两口", "is_correct": false, "explanation": "语义：“老两口”指两位老人，与“我”单独听音乐的句意矛盾。"}, {"text": "情侣", "is_correct": false, "explanation": "语义：“情侣”指两人，与“我”单独听音乐的句意矛盾。"}, {"text": "父子", "is_correct": false, "explanation": "搭配：“父子”是两人的固定关系，不能与“我常常”搭配作主语。"}], "explanations": {"一个人": "“周末我常常一个人听音乐”表示独自一人，符合句意。", "老两口": "语义：“老两口”指两位老人，与“我”单独听音乐的句意矛盾。", "情侣": "语义：“情侣”指两人，与“我”单独听音乐的句意矛盾。", "父子": "搭配：“父子”是两人的固定关系，不能与“我常常”搭配作主语。"}, "sentence_index": 6, "correct_answer": "一个人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一个人和我们一起去超市。", "explanation": "这里“一个人”与“和我们一起”矛盾：“一个人”只表示单独一人，不能与“和我们一起”同说，应去掉其中之一。"}, {"text": "这间教室一个人坐满了。", "explanation": "这里误把“一个人”当作人很多的数量义，它只表示一人，与“坐满”不能搭配，应改用〈大家〉。"}, {"text": "这群羊一个人在草地上吃草。", "explanation": "这里应该用〈独自〉。“一个人”只指人，不能指羊，指动物要说〈独自〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一个人们去医院看病。", "corrected_sentence": "她一个人去医院看病。", "error_description": "“一个人”表示单数，不能加复数词尾“们”。说成“一个人们”是搭配错误，应去掉“们”。正确说法是“她一个人去医院看病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天晚上很一个人散步。", "corrected_sentence": "我每天晚上一个人散步。", "error_description": "“一个人”是数量短语，前面不能加程度副词“很”修饰。这里多加了“很”，应去掉。正确说法是“我每天晚上一个人散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86403, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "远离是“接近”在距离上的反义词，表示距离变远，与“慢慢靠过去”相对。"}, {"text": "购买", "is_correct": false, "explanation": "购买表示买东西，与“接近”没有相对关系。"}, {"text": "保护", "is_correct": false, "explanation": "保护表示护卫、照看，与“接近”没有相对关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集表示聚拢、搜集，与“接近”没有相对关系。"}], "correct_answer": "远离", "explanations": {"远离": "远离是“接近”在距离上的反义词，表示距离变远，与“慢慢靠过去”相对。", "购买": "购买表示买东西，与“接近”没有相对关系。", "保护": "保护表示护卫、照看，与“接近”没有相对关系。", "收集": "收集表示聚拢、搜集，与“接近”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86403, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "远离是“接近”在距离上的反义词，表示距离变远，与“慢慢靠过去”相对。"}, {"text": "发明", "is_correct": false, "explanation": "发明表示创造新事物，与“接近”没有相对关系。"}, {"text": "策划", "is_correct": false, "explanation": "策划表示筹划、谋划，与“接近”没有相对关系。"}, {"text": "修补", "is_correct": false, "explanation": "修补表示修理、补救，与“接近”没有相对关系。"}], "correct_answer": "远离", "explanations": {"远离": "远离是“接近”在距离上的反义词，表示距离变远，与“慢慢靠过去”相对。", "发明": "发明表示创造新事物，与“接近”没有相对关系。", "策划": "策划表示筹划、谋划，与“接近”没有相对关系。", "修补": "修补表示修理、补救，与“接近”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86403, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接近是慢慢靠过去，离得越来越近。", "primary_collocate": null, "pronunciation": "jiē jìn", "ipa": "tɕjɛ˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我慢慢接近那只小鸟，它没有飞走。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，不要接近那条狗。", "target_word": "接近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "船慢慢接近岸边，大家都站了起来。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机接近机场时，要慢慢降低高度。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一步一步接近门口，想听里面的声音。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里，一个人影慢慢接近了我们的帐篷。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "越接近山顶，风就越大，天气也越冷。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猎人悄悄接近鹿，不想让它发现。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车慢慢接近车站，速度越来越慢。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们害怕，不敢接近那个陌生人。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "接近了", "label": "体标"}, {"form": "接近着", "label": "体标"}, {"form": "接近过", "label": "体标"}], "register": "中性", "sense_fingerprint": "接近：慢慢向某处靠过去，距离逐渐变小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40bec50f-c43d-494c-bc06-77387795ad2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接近", "is_correct": true, "explanation": "接近表示慢慢靠过去，与“小鸟没有飞走”的语境相符，句意正确。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题或话题，不能用于小鸟。"}, {"text": "解释", "is_correct": false, "explanation": "语义：解释的对象是道理或事情，不能解释一只小鸟，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译的对象是语言或文字，不能翻译一只小鸟。"}], "explanations": {"接近": "接近表示慢慢靠过去，与“小鸟没有飞走”的语境相符，句意正确。", "讨论": "搭配：“讨论”的对象是问题或话题，不能用于小鸟。", "解释": "语义：解释的对象是道理或事情，不能解释一只小鸟，句意不通。", "翻译": "语义：翻译的对象是语言或文字，不能翻译一只小鸟。"}, "sentence_index": 0, "correct_answer": "接近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "领导接近了这份申请。", "explanation": "这里应该用〈批准〉。批准指同意并认可，接近表示靠近，不能用于申请。"}, {"text": "他马上接近了那封邮件。", "explanation": "这里应该用〈接收〉。接收指把东西收到手里，接近是靠近，不能用于邮件。"}, {"text": "我非常接近你的帮助。", "explanation": "这里应该用〈感谢〉。感谢指表示谢意，接近表示靠近，不能用于帮助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接近", "is_correct": true, "explanation": "接近表示靠近，“越接近山顶，风越大”成立，句意正确。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰是美化的动作，与“风越大、天气越冷”的变化无关。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”用于墙面等表面，不能用于山顶。"}, {"text": "洗涤", "is_correct": false, "explanation": "语义：洗涤是清洗，不能以山顶为对象，句意不通。"}], "explanations": {"接近": "接近表示靠近，“越接近山顶，风越大”成立，句意正确。", "装饰": "语义：装饰是美化的动作，与“风越大、天气越冷”的变化无关。", "粉刷": "搭配：“粉刷”用于墙面等表面，不能用于山顶。", "洗涤": "语义：洗涤是清洗，不能以山顶为对象，句意不通。"}, "sentence_index": 6, "correct_answer": "接近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他默默接近了巨大的压力。", "explanation": "这里应该用〈承受〉。承受指经受、担负，接近表示靠近，不能用于压力。"}, {"text": "她接近了很长时间的寂寞。", "explanation": "这里应该用〈忍受〉。忍受指承受难受的事，接近表示靠近，不能用于寂寞。"}, {"text": "他接近了大家的信任。", "explanation": "这里应该用〈赢得〉。赢得指通过努力获得，接近表示靠近，不能用于信任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "救生艇慢慢接近了的岸边。", "corrected_sentence": "救生艇慢慢接近了岸边。", "error_description": "动态助词“了”不能直接接“的”修饰名词。错误形式：接近了的岸边；正确形式：接近了岸边。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "越接近了海边，空气就越湿润。", "corrected_sentence": "越接近海边，空气就越湿润。", "error_description": "体标错误：“越……就越……”结构中不能用“了”，应说“越接近海边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86404, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "远离是“接近”在距离上的反义词，表示距离变远，与“接近”相对。"}, {"text": "建立", "is_correct": false, "explanation": "建立表示设立、创造，与“接近”没有相对关系。"}, {"text": "保存", "is_correct": false, "explanation": "保存表示留存、保留，与“接近”没有相对关系。"}, {"text": "解释", "is_correct": false, "explanation": "解释表示说明道理，与“接近”没有相对关系。"}], "correct_answer": "远离", "explanations": {"远离": "远离是“接近”在距离上的反义词，表示距离变远，与“接近”相对。", "建立": "建立表示设立、创造，与“接近”没有相对关系。", "保存": "保存表示留存、保留，与“接近”没有相对关系。", "解释": "解释表示说明道理，与“接近”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86404, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "远离是“接近”在距离上的反义词，表示距离变远，与“接近”相对。"}, {"text": "安排", "is_correct": false, "explanation": "安排表示布置、筹划，与“接近”没有相对关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察表示仔细看、留意，与“接近”没有相对关系。"}, {"text": "批准", "is_correct": false, "explanation": "批准表示同意、准许，与“接近”没有相对关系。"}], "correct_answer": "远离", "explanations": {"远离": "远离是“接近”在距离上的反义词，表示距离变远，与“接近”相对。", "安排": "安排表示布置、筹划，与“接近”没有相对关系。", "观察": "观察表示仔细看、留意，与“接近”没有相对关系。", "批准": "批准表示同意、准许，与“接近”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86404, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "靠近；距离不远。", "primary_collocate": null, "pronunciation": "jiē jìn", "ipa": "tɕjɛ˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我家接近学校，走路五分钟就到。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店接近地铁站，来的人很多。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒店接近海边，早上可以去海边散步。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他住的地方接近机场，常常听到飞机的声音。", "target_word": "接近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区接近公园，空气很好。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的教室接近楼梯，下课时很吵。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院接近车站，坐公共汽车很方便。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的房子接近森林，晚上能听到鸟叫。", "target_word": "接近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个村子接近边境，离城市很远。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市接近赤道，一年四季都很热。", "target_word": "接近", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "接近了", "label": "体标"}, {"form": "接近着", "label": "体标"}, {"form": "接近过", "label": "体标"}], "register": "中性", "sense_fingerprint": "接近：位置上靠近，距离不远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40bec50f-c43d-494c-bc06-77387795ad2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接近", "is_correct": true, "explanation": "接近表示距离不远，与“走路五分钟就到”相符，句意正确。"}, {"text": "远离", "is_correct": false, "explanation": "语义：远离表示距离很远，与“走路五分钟就到”矛盾。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题或话题，不能和“家”搭配。"}, {"text": "购买", "is_correct": false, "explanation": "语义：购买表示买东西，与句中的距离无关，句意不通。"}], "explanations": {"接近": "接近表示距离不远，与“走路五分钟就到”相符，句意正确。", "远离": "语义：远离表示距离很远，与“走路五分钟就到”矛盾。", "讨论": "搭配：“讨论”的对象是问题或话题，不能和“家”搭配。", "购买": "语义：购买表示买东西，与句中的距离无关，句意不通。"}, "sentence_index": 0, "correct_answer": "接近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快接近了那笔奖金。", "explanation": "这里应该用〈领取〉。领取指把应得的钱或东西拿到手，接近表示靠近，不能用来说拿到奖金。"}, {"text": "电话已经接近了，请您说话。", "explanation": "这里应该用〈接通〉。接通指电话已经连上，接近只是靠近，不能用来说电话。"}, {"text": "他接近了老师的建议，马上改正了错误。", "explanation": "这里应该用〈接受〉。接受指同意并采纳，接近表示靠近，不能用来说采纳建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接近", "is_correct": true, "explanation": "接近表示距离近，与“坐公共汽车很方便”相符，句意正确。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：逃离表示迅速离开，与“坐车很方便”的近距离语境矛盾。"}, {"text": "出发", "is_correct": false, "explanation": "搭配：“出发”要用“从”引出起点，不能直接带“车站”作宾语。"}, {"text": "对付", "is_correct": false, "explanation": "语义：对付是应付、处理，不表示位置靠近，句意不通。"}], "explanations": {"接近": "接近表示距离近，与“坐公共汽车很方便”相符，句意正确。", "逃离": "语义：逃离表示迅速离开，与“坐车很方便”的近距离语境矛盾。", "出发": "搭配：“出发”要用“从”引出起点，不能直接带“车站”作宾语。", "对付": "语义：对付是应付、处理，不表示位置靠近，句意不通。"}, "sentence_index": 6, "correct_answer": "接近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他接近了那段视频。", "explanation": "这里应该用〈删除〉。删除指把内容去掉，接近表示靠近，不能用来说去掉视频。"}, {"text": "他刚接近了这家公司的业务。", "explanation": "这里应该用〈接手〉。接手指接过别人的工作或业务，接近是靠近，不能用于业务。"}, {"text": "他接近了自己的错误，马上认真地改正。", "explanation": "这里应该用〈承认〉。承认指认可自己做错的事，接近表示靠近，不能用于错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的学校接近在火车站，出门很方便。", "corrected_sentence": "我们的学校接近火车站，出门很方便。", "error_description": "介词错误：“接近”后直接带地点宾语，不能再加“在”。正确说法是“接近火车站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们小区接近到公园，周末可以去散步。", "corrected_sentence": "我们小区接近公园，周末可以去散步。", "error_description": "补语错误：“接近”后不能直接加“到”，应直接带宾语“公园”。正确说法是“接近公园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565af22-63a6-40a4-a2da-cf5d822b07f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
