INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86407, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "森林是有很多很多树的地方。", "primary_collocate": null, "pronunciation": "sēn lín", "ipa": "sən˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "森林里有很多很多树。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小熊住在大森林里。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家后面有一片小森林。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去森林看树和花。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里很安静，只有风的声音。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给我讲了一个森林里的故事。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去过森林吗？", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的路不好走，我们走得很慢。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在森林里找到了一只小鸟。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个森林太大了，我们不敢进去。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "原始森林", "label": "复合"}, {"form": "森林公园", "label": "复合"}], "register": "中性", "sense_fingerprint": "有很多树的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f36a7577-f479-45c5-a74f-422da336fafe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "盒子", "is_correct": false, "explanation": "语义：盒子装不下很多很多树，句子说不通。"}, {"text": "森林", "is_correct": true, "explanation": "正确：“森林”是树木很多的地方，与“里有很多很多树”相符。"}, {"text": "抽屉", "is_correct": false, "explanation": "体貌：抽屉太小，形体装不下很多很多树。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，里面不长树，“冰箱里有很多很多树”不成立。"}], "explanations": {"盒子": "语义：盒子装不下很多很多树，句子说不通。", "森林": "正确：“森林”是树木很多的地方，与“里有很多很多树”相符。", "抽屉": "体貌：抽屉太小，形体装不下很多很多树。", "冰箱": "语义：冰箱是家用电器，里面不长树，“冰箱里有很多很多树”不成立。"}, "sentence_index": 0, "correct_answer": "森林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口有一棵森林，很大。", "explanation": "这里应该用〈片〉。森林是成片的树木，量词用“片”；“棵”只用于单株树。"}, {"text": "工人用森林盖了一间小屋。", "explanation": "这里应该用〈木板〉。森林是有很多树的地方，不是建材；盖小屋要用木板等材料。"}, {"text": "这片森林很小，只有一棵树。", "explanation": "这里的错误在于“只有一棵树”：森林是有很多很多树的地方，只有一棵树不能叫森林。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "配价：“去过”要求一个地点，空气不是可以去的地方。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是声音，不是可以去的地方，“去过音乐”说不通。"}, {"text": "森林", "is_correct": true, "explanation": "正确：“去过森林”是合适的地点宾语，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是可以前往的场所，“去过桌子”不成立。"}], "explanations": {"空气": "配价：“去过”要求一个地点，空气不是可以去的地方。", "音乐": "语义：音乐是声音，不是可以去的地方，“去过音乐”说不通。", "森林": "正确：“去过森林”是合适的地点宾语，与句意相符。", "桌子": "语义：桌子是家具，不是可以前往的场所，“去过桌子”不成立。"}, "sentence_index": 6, "correct_answer": "森林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街道两边种着很多森林。", "explanation": "这里应该用〈树木〉。路边种的是一棵棵单株的树，森林指成片的树林，不能说沿路“种着森林”。"}, {"text": "这片森林很大，街上有很多汽车和红绿灯。", "explanation": "这里应该用〈城市〉。街上的汽车和红绿灯属于城市；森林是有很多很多树的地方，不能这样说。"}, {"text": "这片森林很矮，只有一米高。", "explanation": "这里应该用〈灌木丛〉。灌木丛才矮；森林是有很多很多树的地方，不能说只有一米高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山上有一棵很大的森林。", "corrected_sentence": "这座山上有一片很大的森林。", "error_description": "量词错误：森林应用量词“片”，不能用“棵”。“棵”用于单株树木。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在一片很大森林里找了一下午。", "corrected_sentence": "我们在一片很大的森林里找了一下午。", "error_description": "结构助词漏掉：“很大”修饰“森林”时要加“的”，应说“一片很大的森林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
