INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大片生长着许多树木的地方。", "primary_collocate": null, "pronunciation": "sēn lín", "ipa": "sən˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "这片森林很大，里面有很多高树。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末去森林里走路，空气很好。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有鸟，也有小动物。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下有一大片绿色的森林。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，森林里比城市凉快。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在森林里迷路了。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的树又高又大，我们走了两个小时。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只大鸟在森林上面飞着。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的森林一年比一年大。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想住在安静的森林旁边。", "target_word": "森林", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "原始森林", "label": "复合"}, {"form": "森林公园", "label": "复合"}], "register": "中性", "sense_fingerprint": "大片树木生长的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f36a7577-f479-45c5-a74f-422da336fafe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠干旱，不会有很多高树，与“里面有很多高树”矛盾。"}, {"text": "森林", "is_correct": true, "explanation": "正确：“森林”指大片生长着树木的地方，与“很大”和“很多高树”相符。"}, {"text": "海", "is_correct": false, "explanation": "语义：海是水域，不会长出高树，“里面有很多高树”说不通。"}, {"text": "云", "is_correct": false, "explanation": "体貌：云是气体的聚合，没有能容纳高树的形体，不能说“里面有很多高树”。"}], "explanations": {"沙漠": "语义：沙漠干旱，不会有很多高树，与“里面有很多高树”矛盾。", "森林": "正确：“森林”指大片生长着树木的地方，与“很大”和“很多高树”相符。", "海": "语义：海是水域，不会长出高树，“里面有很多高树”说不通。", "云": "体貌：云是气体的聚合，没有能容纳高树的形体，不能说“里面有很多高树”。"}, "sentence_index": 0, "correct_answer": "森林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山下有一棵大森林，很绿。", "explanation": "这里应该用〈片〉。森林指一大片树木，量词用“片”；“棵”用于单株树，如“一棵大树”。"}, {"text": "工厂用森林做桌子。", "explanation": "这里应该用〈木材〉。森林是生长树木的地方，不是木料；做桌子要用木材。"}, {"text": "这片森林很大，一棵树也没有。", "explanation": "这里应该用〈沙漠〉。沙漠里没有树，森林指生长着许多树木的地方，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "语义：房间里不会长出又高又大的树，句子说不通。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子太小，装不下又高又大的树，也不能走两个小时。"}, {"text": "森林", "is_correct": true, "explanation": "正确：“森林”是树木生长的地方，与“树又高又大”和“走了两个小时”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：冰箱不能作为树生长的场所，“冰箱里的树”不成立。"}], "explanations": {"房间": "语义：房间里不会长出又高又大的树，句子说不通。", "盒子": "语义：盒子太小，装不下又高又大的树，也不能走两个小时。", "森林": "正确：“森林”是树木生长的地方，与“树又高又大”和“走了两个小时”相符。", "冰箱": "配价：冰箱不能作为树生长的场所，“冰箱里的树”不成立。"}, "sentence_index": 6, "correct_answer": "森林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条马路两边种着很多森林。", "explanation": "这里应该用〈树木〉。路边种的是一棵棵单株的树，森林指成片的树林，不能说沿路“种着森林”。"}, {"text": "这片森林很大，有很多高楼。", "explanation": "这里应该用〈城市〉。城市才有很多高楼；森林指生长着许多树木的地方，不能说有很多高楼。"}, {"text": "他想住在一只安静的森林旁边。", "explanation": "这里应该用〈片〉。森林是成片的，量词用“片”；“只”用于动物，不能修饰森林。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "北边有一棵很大的森林。", "corrected_sentence": "北边有一片很大的森林。", "error_description": "量词错误：森林是成片的，应用量词“片”，说“一片很大的森林”；“棵”用于单株树木，不能用来修饰森林。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在一片很大森林里露营。", "corrected_sentence": "我们在一片很大的森林里露营。", "error_description": "结构助词漏掉：“很大”修饰“森林”时要加“的”，应说“一片很大的森林”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
