INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86409, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“啦”放在句子后面，让话听起来高兴、轻松。", "primary_collocate": null, "pronunciation": "la", "ipa": "la", "syllable_count": 1, "sentences": [{"text": "放假啦，我们去玩吧！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好啦，别生气了。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太好啦，明天不用上班！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢啦，下次我请你。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走啦，再见！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好啦好啦，我听你的。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日快乐啦！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来啦来啦，大家请坐。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快看，小鸟飞来啦！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那我先走啦，明天见。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末语气词；使话语高兴轻松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2360d38e-578e-4142-a840-d1924b1155a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86409, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确答案。句末的“啦”让话听起来高兴、轻松，读轻声 la。"}, {"text": "拉", "is_correct": false, "explanation": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动，不是语气词。"}, {"text": "辣", "is_correct": false, "explanation": "辣（là，第四声）与啦（la，轻声）声调不同，意思是辣味。"}, {"text": "喇", "is_correct": false, "explanation": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。"}, {"text": "蜡", "is_correct": false, "explanation": "蜡（là，第四声）与啦（la，轻声）声调不同，意思是蜡烛。"}], "explanations": {"啦": "正确答案。句末的“啦”让话听起来高兴、轻松，读轻声 la。", "拉": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动，不是语气词。", "辣": "辣（là，第四声）与啦（la，轻声）声调不同，意思是辣味。", "喇": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。", "蜡": "蜡（là，第四声）与啦（la，轻声）声调不同，意思是蜡烛。"}, "sentence_index": null, "correct_answer": "啦"}, "level_3": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确。“啦”让话听起来轻快，符合放假时的喜悦。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”是动态助词，须接在动词后表持续，不作句末语气词，“放假着”不成句。"}, {"text": "的", "is_correct": false, "explanation": "语法：“的”不作句末语气词，“放假的”不能独立成句，句子不通。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言语气词，与口语的“我们去玩吧”风格不合。"}], "explanations": {"啦": "正确。“啦”让话听起来轻快，符合放假时的喜悦。", "着": "语法：“着”是动态助词，须接在动词后表持续，不作句末语气词，“放假着”不成句。", "的": "语法：“的”不作句末语气词，“放假的”不能独立成句，句子不通。", "哉": "语域：“哉”是文言语气词，与口语的“我们去玩吧”风格不合。"}, "sentence_index": 0, "correct_answer": "啦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的父亲昨天去世啦。", "explanation": "这里不该用〈啦〉。“啦”让语气轻松愉快，用在去世这样的沉痛事件上，语气完全不合。"}, {"text": "根据规定，请各位遵守纪律啦。", "explanation": "这里不该用〈啦〉。“啦”是口语语气词，正式的规定里不用，风格不合。"}, {"text": "他偷看了我的日记，还告诉了别人啦。", "explanation": "这里误把〈啦〉的轻快语气用在指责性的话上。〈啦〉带有高兴、轻松的口气，与“偷看日记还告诉别人”这种令人气愤的行为相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86409, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确答案。句末的“啦”让话听起来高兴、轻松，读轻声 la。"}, {"text": "拉", "is_correct": false, "explanation": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动。"}, {"text": "腊", "is_correct": false, "explanation": "腊（là，第四声）与啦（la，轻声）声调不同，意思是腊月。"}, {"text": "喇", "is_correct": false, "explanation": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。"}, {"text": "浪", "is_correct": false, "explanation": "浪（làng）比啦（la）多一个韵尾 ng，意思是波浪。"}, {"text": "懒", "is_correct": false, "explanation": "懒（lǎn）比啦（la）多一个韵尾 n，意思是懒惰。"}], "explanations": {"啦": "正确答案。句末的“啦”让话听起来高兴、轻松，读轻声 la。", "拉": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动。", "腊": "腊（là，第四声）与啦（la，轻声）声调不同，意思是腊月。", "喇": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。", "浪": "浪（làng）比啦（la）多一个韵尾 ng，意思是波浪。", "懒": "懒（lǎn）比啦（la）多一个韵尾 n，意思是懒惰。"}, "sentence_index": null, "correct_answer": "啦"}, "level_3": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确。“啦”让祝福听起来欢快、轻松，符合生日的气氛。"}, {"text": "嘛", "is_correct": false, "explanation": "语义：“嘛”表示道理显而易见或劝说，用在祝福句末不通顺，“生日快乐嘛”不是送祝福的说法。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”属于文言，与口语的祝福语不协调，风格不合。"}, {"text": "罢", "is_correct": false, "explanation": "语义：“罢”表示让步或了结，如“算了罢”，用在祝福句末语气不合，句意不通。"}], "explanations": {"啦": "正确。“啦”让祝福听起来欢快、轻松，符合生日的气氛。", "嘛": "语义：“嘛”表示道理显而易见或劝说，用在祝福句末不通顺，“生日快乐嘛”不是送祝福的说法。", "矣": "语域：“矣”属于文言，与口语的祝福语不协调，风格不合。", "罢": "语义：“罢”表示让步或了结，如“算了罢”，用在祝福句末语气不合，句意不通。"}, "sentence_index": 6, "correct_answer": "啦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的小狗昨天丢啦，我们都很难过。", "explanation": "这里不该用〈啦〉。“啦”让语气轻快，而丢了小狗、大家难过的情绪沉重，二者冲突。"}, {"text": "尊敬的各位来宾，欢迎大家啦。", "explanation": "这里不该用〈啦〉。“啦”是口语语气词，正式的欢迎致辞里不用，风格不合。"}, {"text": "他的手术很危险，医生说情况不好啦。", "explanation": "这里不该用〈啦〉。“啦”让话显得轻松，而手术风险和病情不好是严肃的内容，语气不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考完试啦吗，我们去吃饭吧。", "corrected_sentence": "考完试啦，我们去吃饭吧。", "error_description": "错误形式：“考完试啦吗”。“啦”和“吗”都是句末语气词，不能叠用；“吗”还会把陈述变成疑问。正确形式是“考完试啦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下啦班，我们走吧！", "corrected_sentence": "下班啦，我们走吧！", "error_description": "错误形式：“下啦班”。“啦”插在离合词“下班”中间，破坏了词语；正确形式是“下班啦”，“啦”放在整个动宾短语之后的句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
