INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "语气助词，是“了”和“啊”的合音，用在句末，表示感叹或变化。", "primary_collocate": null, "pronunciation": "la", "ipa": "la", "syllable_count": 1, "sentences": [{"text": "下雨啦，快回家吧！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到家啦！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子都长这么高啦！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来啦，花都开了。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经走啦。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好啦，快来吃！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑啦，我们回去吧。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你终于来啦！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束啦，大家可以玩了。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃饱啦，谢谢你。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "了+啊合音；句末表感叹或变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2360d38e-578e-4142-a840-d1924b1155a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确答案。“啦”是“了”和“啊”的合音，句末读轻声 la。"}, {"text": "拉", "is_correct": false, "explanation": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动，不是句末语气词。"}, {"text": "辣", "is_correct": false, "explanation": "辣（là，第四声）与啦（la，轻声）声调不同，意思是辣味。"}, {"text": "喇", "is_correct": false, "explanation": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。"}, {"text": "蜡", "is_correct": false, "explanation": "蜡（là，第四声）与啦（la，轻声）声调不同，意思是蜡烛。"}], "explanations": {"啦": "正确答案。“啦”是“了”和“啊”的合音，句末读轻声 la。", "拉": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动，不是句末语气词。", "辣": "辣（là，第四声）与啦（la，轻声）声调不同，意思是辣味。", "喇": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。", "蜡": "蜡（là，第四声）与啦（la，轻声）声调不同，意思是蜡烛。"}, "sentence_index": null, "correct_answer": "啦"}, "level_3": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确。“啦”表示雨已经下起来了这一变化，并带有提醒、感叹的语气。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”用于是非问句，句末要用问号；“下雨吗，快回家吧”把陈述变成疑问，与催促的语气不合。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”是动态助词，须接在动词后表持续，不作句末语气词，“下雨着”不成句。"}, {"text": "的", "is_correct": false, "explanation": "语法：“的”不作句末语气词，“下雨的”不能独立成句，句子不通。"}], "explanations": {"啦": "正确。“啦”表示雨已经下起来了这一变化，并带有提醒、感叹的语气。", "吗": "语义：“吗”用于是非问句，句末要用问号；“下雨吗，快回家吧”把陈述变成疑问，与催促的语气不合。", "着": "语法：“着”是动态助词，须接在动词后表持续，不作句末语气词，“下雨着”不成句。", "的": "语法：“的”不作句末语气词，“下雨的”不能独立成句，句子不通。"}, "sentence_index": 0, "correct_answer": "啦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直是学生啦。", "explanation": "这里不该用〈啦〉。“啦”表示出现了新的变化，而“一直”说明状态没有改变，两者意思矛盾。"}, {"text": "会议于今天下午召开啦。", "explanation": "这里不该用〈啦〉。“啦”是口语语气词，书面的会议通知里要写“召开了”，不用语气词“啦”。"}, {"text": "中国的首都是北京啦。", "explanation": "这里误把〈啦〉用在一般陈述句末尾。〈啦〉只表示感叹或新出现的变化，“首都是北京”是固定事实，没有感叹也没有变化，不能用〈啦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确答案。“啦”是“了”和“啊”的合音，句末读轻声 la。"}, {"text": "拉", "is_correct": false, "explanation": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动。"}, {"text": "腊", "is_correct": false, "explanation": "腊（là，第四声）与啦（la，轻声）声调不同，意思是腊月。"}, {"text": "喇", "is_correct": false, "explanation": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。"}, {"text": "浪", "is_correct": false, "explanation": "浪（làng）比啦（la）多一个韵尾 ng，意思是波浪。"}, {"text": "懒", "is_correct": false, "explanation": "懒（lǎn）比啦（la）多一个韵尾 n，意思是懒惰。"}], "explanations": {"啦": "正确答案。“啦”是“了”和“啊”的合音，句末读轻声 la。", "拉": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动。", "腊": "腊（là，第四声）与啦（la，轻声）声调不同，意思是腊月。", "喇": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。", "浪": "浪（làng）比啦（la）多一个韵尾 ng，意思是波浪。", "懒": "懒（lǎn）比啦（la）多一个韵尾 n，意思是懒惰。"}, "sentence_index": null, "correct_answer": "啦"}, "level_3": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确。“啦”表示天色已经变黑，这种变化正是“啦”的典型用法。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，与口语的“我们回去吧”风格不协调。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言感叹助词，口语中不用，与句子的语体不合。"}, {"text": "罢", "is_correct": false, "explanation": "语义：“罢”表示让步或了结，如“算了罢”，与“天黑”这一客观陈述的语气不合。"}], "explanations": {"啦": "正确。“啦”表示天色已经变黑，这种变化正是“啦”的典型用法。", "矣": "语域：“矣”是文言语气词，与口语的“我们回去吧”风格不协调。", "哉": "语域：“哉”是文言感叹助词，口语中不用，与句子的语体不合。", "罢": "语义：“罢”表示让步或了结，如“算了罢”，与“天黑”这一客观陈述的语气不合。"}, "sentence_index": 6, "correct_answer": "啦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上都吃饱啦。", "explanation": "这里不该用〈啦〉。“啦”表示刚出现的一次性变化，“每天”说的是习惯，不是新变化。"}, {"text": "这份报告包含了三个章节啦。", "explanation": "这里误把〈啦〉用在平铺直叙的数量陈述上。〈啦〉只表示感叹或新出现的变化，单纯说明章节数量并没有这些意味，不能用〈啦〉。"}, {"text": "这本词典的封面是红色的啦。", "explanation": "这里误把〈啦〉用在平淡的事实描述上。〈啦〉只表示感叹或新出现的变化，封面颜色是一个固定的描述，不能用〈啦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪啦停，我们出去玩吧。", "corrected_sentence": "雪停啦，我们出去玩吧。", "error_description": "错误形式：“雪啦停”。语气词“啦”只能放在句末，不能插在主语和动词之间；正确形式是“雪停啦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我吃饱吗啦，谢谢大家。", "corrected_sentence": "我吃饱啦，谢谢大家。", "error_description": "错误形式：“吗啦”。“吗”是疑问语气词，陈述句中不能与“啦”叠用；正确形式是“吃饱啦”，句末只用“啦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04e81d6-91a6-4bf9-9a33-d1dedced60cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "演员是在电影或舞台上扮演别人的人。", "primary_collocate": null, "pronunciation": "yǎn yuán", "ipa": "jæn˨˩˦ ɥæn˧˥", "syllable_count": 2, "sentences": [{"text": "我姐姐是舞台上的演员。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个演员在电影里演医生。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员的电影我看过很多。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员穿着红衣服站在台上。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员很高，说话也很好听。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员们明天要去学校演出。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好演员要会哭，也要会笑。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不是演员，是写故事的人。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员在后面换衣服，马上就出来。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿长大后想做演员。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "男演员", "label": "复合"}, {"form": "女演员", "label": "复合"}, {"form": "演員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电影或舞台上扮演别人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f36a7577-f479-45c5-a74f-422da336fafe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地毯", "is_correct": false, "explanation": "语义：地毯是铺在地上的织物，不是人，不能说“我姐姐是……地毯”。"}, {"text": "演员", "is_correct": true, "explanation": "正确：“演员”指在舞台上扮演角色的人，与“我姐姐是舞台上的”相符。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光是光线，不是人，不能用来说明“我姐姐”的身份。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“是……的”后接指人名词才合理，“钢琴”不能用来说明“我姐姐”的身份。"}], "explanations": {"地毯": "语义：地毯是铺在地上的织物，不是人，不能说“我姐姐是……地毯”。", "演员": "正确：“演员”指在舞台上扮演角色的人，与“我姐姐是舞台上的”相符。", "灯光": "语义：灯光是光线，不是人，不能用来说明“我姐姐”的身份。", "钢琴": "搭配：“是……的”后接指人名词才合理，“钢琴”不能用来说明“我姐姐”的身份。"}, "sentence_index": 0, "correct_answer": "演员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把演员很高，说话也很好听。", "explanation": "这里应该用〈位〉。“把”用于有柄的东西，如椅子、刀；指人要用“位”或“名”。"}, {"text": "他是一名演员，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。给病人看病的是医生，演员是在电影或舞台上扮演别人的人。"}, {"text": "这本书的演员是一位老人。", "explanation": "这里应该用〈作者〉。写书的人是作者，演员是在电影或舞台上扮演角色的人，不写书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子没有感情，不会哭也不会笑，“要会哭”说不通。"}, {"text": "演员", "is_correct": true, "explanation": "正确：“演员”需要表演情绪，要会哭会笑，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有面部表情，不能做出哭和笑的样子。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能哭也不能笑，与“要会哭”相矛盾。"}], "explanations": {"椅子": "语义：椅子没有感情，不会哭也不会笑，“要会哭”说不通。", "演员": "正确：“演员”需要表演情绪，要会哭会笑，与句意相符。", "石头": "体貌：石头没有面部表情，不能做出哭和笑的样子。", "桌子": "语义：桌子是家具，不能哭也不能笑，与“要会哭”相矛盾。"}, "sentence_index": 6, "correct_answer": "演员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位演员每天在实验室研究新药。", "explanation": "这里应该用〈科学家〉。在实验室研究新药的是科学家，演员是在电影或舞台上扮演别人的人。"}, {"text": "这位演员在比赛中吹哨判罚，很公平。", "explanation": "这里应该用〈裁判〉。在比赛中吹哨判罚的是裁判，演员是在电影或舞台上扮演别人的人。"}, {"text": "演员用镜头拍出了很美的画面。", "explanation": "这里应该用〈摄影师〉。用镜头拍画面的是摄影师，演员不负责拍摄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多演员们在后台化妆。", "corrected_sentence": "很多演员在后台化妆。", "error_description": "“们”不能与“很多”等数量词连用，应说“很多演员”，不说“很多演员们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候想当了演员，后来做了老师。", "corrected_sentence": "他小时候想当演员，后来做了老师。", "error_description": "时态错误：“想”表示希望，动作尚未发生，“当”后不能加“了”，应说“想当演员”，不说“想当了演员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
