INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86415, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当中是在中间，或者是在许多里面。", "primary_collocate": null, "pronunciation": "dāng zhōng", "ipa": "taŋ˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "孩子们在花园当中玩。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在大家当中，一句话也没说。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子在一片树林当中，很安静。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖当中有一个小岛。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在人群当中，我一下子就看到了她。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在雪山当中走了一天，都很累。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河从两座山当中流过。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一堆书当中找到了那张照片。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园当中有一个很大的钟。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路在城市当中，所以车很多。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "当中：在某处的中间或许多事物里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487a10cd-ac34-420d-b7b4-50a652b0befc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当中", "is_correct": true, "explanation": "当中：表示在花园内部，与“在花园当中玩”的空间关系相符。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：“之间”需要两个或两个以上的对象，“花园”只有一个，不能说“在花园之间”。"}, {"text": "上面", "is_correct": false, "explanation": "语义：“上面”指位置在高处，孩子们在花园上面玩与常理不符。"}, {"text": "底下", "is_correct": false, "explanation": "语义：“底下”指在下方，与“在花园里玩”的意思相矛盾。"}], "explanations": {"当中": "当中：表示在花园内部，与“在花园当中玩”的空间关系相符。", "之间": "搭配：“之间”需要两个或两个以上的对象，“花园”只有一个，不能说“在花园之间”。", "上面": "语义：“上面”指位置在高处，孩子们在花园上面玩与常理不符。", "底下": "语义：“底下”指在下方，与“在花园里玩”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "当中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在去北京的当中遇到了大雨。", "explanation": "这里应该用〈途中〉。“去北京的当中”不通顺，表示行进过程中要用“途中”。"}, {"text": "我们当中的距离很远。", "explanation": "这里应该用〈之间〉。当中指在许多人或事物之内，说两者之间的距离要用“之间”。"}, {"text": "我当中很高兴。", "explanation": "这里应该用〈心里〉。当中只表示空间或范围的内部，不能用来描述人的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当中", "is_correct": true, "explanation": "当中：表示从两座山的中间穿过，与“流过”的路线相符。"}, {"text": "对面", "is_correct": false, "explanation": "搭配：“对面”指隔着的另一边，不能说“从两座山对面流过”。"}, {"text": "之上", "is_correct": false, "explanation": "语义：“之上”指在高处，小河从山的上方流过与常理不符。"}, {"text": "上", "is_correct": false, "explanation": "语义：“上”指山的上面，与河流从山间穿过的常规路线不符。"}], "explanations": {"当中": "当中：表示从两座山的中间穿过，与“流过”的路线相符。", "对面": "搭配：“对面”指隔着的另一边，不能说“从两座山对面流过”。", "之上": "语义：“之上”指在高处，小河从山的上方流过与常理不符。", "上": "语义：“上”指山的上面，与河流从山间穿过的常规路线不符。"}, "sentence_index": 6, "correct_answer": "当中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他十点当中到了教室。", "explanation": "这里应该用〈整〉。当中表示在范围内部，不能用来指某一个具体的时间点。"}, {"text": "他一个人当中很孤单。", "explanation": "这里应该用〈独自〉。当中要求在一群人或事物之内，一个人独处时不能用。"}, {"text": "他站在我当中。", "explanation": "这里应该用〈旁边〉。当中指在一群人或事物之内，不能用来指一个人的身边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫在树林里当中睡觉。", "corrected_sentence": "小猫在树林当中睡觉。", "error_description": "错误形式：“树林里当中”；正确形式：“树林当中”。“当中”本身已经表示内部，前面再加“里”会造成重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河在山很当中，风景很美。", "corrected_sentence": "这条河在山当中，风景很美。", "error_description": "错误形式：“很当中”；正确形式：“当中”。“很”不能修饰方位词“当中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
