INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86417, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“年年”是说每一年都这样。", "primary_collocate": null, "pronunciation": "nián nián", "ipa": "niɛn˧˥ niɛn˧˥", "syllable_count": 2, "sentences": [{"text": "年年春节，我们全家都回老家。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年年都给奶奶寄生日礼物。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树年年开花，今年开得最多。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年年夏天，我都去海边住几天。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司年年有新产品。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年年都会种一些花。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年年这个时候，北京都很冷。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年年参加学校的运动会。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年年八月，这里都有很多游客。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们年年去同一个地方旅行。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，指每一年都重复同样的事或情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e76b94-2d0b-469a-847a-d9083859c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86417, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年年", "is_correct": true, "explanation": "正确：年年指每一年都这样，春节一年一次，与“全家都回老家”的周期性相符。"}, {"text": "天天", "is_correct": false, "explanation": "语义：天天指每一天，春节一年只有一次，不可能每天都是春节。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：立刻指马上发生，春节不会“立刻”出现，句子读不通。"}, {"text": "从不", "is_correct": false, "explanation": "语义：从不指从来没有，与后半句“全家都回老家”的意思相矛盾。"}], "explanations": {"年年": "正确：年年指每一年都这样，春节一年一次，与“全家都回老家”的周期性相符。", "天天": "语义：天天指每一天，春节一年只有一次，不可能每天都是春节。", "立刻": "语义：立刻指马上发生，春节不会“立刻”出现，句子读不通。", "从不": "语义：从不指从来没有，与后半句“全家都回老家”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "年年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈年年早上跑步。", "explanation": "这里应该用〈天天〉。年年指每一年都这样，说每天早上跑步要用天天。"}, {"text": "我一看到消息，就年年知道了结果。", "explanation": "这里应该用〈立刻〉。年年指每一年都这样，表示即刻发生的事要用立刻，不能用年年。"}, {"text": "我昨天年年去了超市。", "explanation": "年年指每一年，不能和表示具体某一天的“昨天”连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年年", "is_correct": true, "explanation": "正确：年年指每一年，这个时候是每年固定的时段，与“北京都很冷”的季节特征相符。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：一直表示持续一段时间，不能修饰“这个时候”这样的一个时点。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：立刻表示马上，与季节性的时段不相称，这句话读起来讲不通。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：忽然表示突然发生，与每年都重复的季节规律不符。"}], "explanations": {"年年": "正确：年年指每一年，这个时候是每年固定的时段，与“北京都很冷”的季节特征相符。", "一直": "搭配：一直表示持续一段时间，不能修饰“这个时候”这样的一个时点。", "立刻": "语义：立刻表示马上，与季节性的时段不相称，这句话读起来讲不通。", "忽然": "语义：忽然表示突然发生，与每年都重复的季节规律不符。"}, "sentence_index": 6, "correct_answer": "年年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他年年今晚熬夜到很晚。", "explanation": "年年指每一年，不能和“今晚”这样的具体时间连用，应去掉“年年”。"}, {"text": "她们年年一天吃五顿饭。", "explanation": "年年以“年”为单位，不能和“一天”这样的日单位连用。"}, {"text": "他年年一下子就跑完了马拉松。", "explanation": "年年要求事情每年重复，“一下子就跑完”是一次性完成，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她年年年都去看望外婆。", "corrected_sentence": "她年年都去看望外婆。", "error_description": "叠字错误：〈年年〉只需重叠一次，多写了一个“年”。应说“年年都”，不能说“年年年都”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我年年的都去医院体检。", "corrected_sentence": "我年年都去医院体检。", "error_description": "“的”位置错误：〈年年〉后面不能加“的”，副词〈年年〉要直接与〈都〉连用。应说“年年都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
