INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86418, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，指每一年，逐年。", "primary_collocate": null, "pronunciation": "nián nián", "ipa": "niɛn˧˥ niɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这里的人口年年增加。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的收入年年提高。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年年上涨的房价让人担心。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平年年进步。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的游客年年变多。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子年年长高，衣服总是不够穿。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家工厂的产量年年增长。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水年年减少。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的学生年年增多。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的生意年年变好。", "target_word": "年年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，指逐年变化，常与增加、提高、增长等变化动词连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e76b94-2d0b-469a-847a-d9083859c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年年", "is_correct": true, "explanation": "正确：年年指逐年，人口的增加是按年计算的变化，与整句相符。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：亲自指本人动手，人口的增加不能“亲自”发生，句子读不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔指间或，人口是持续逐年变化的，不能说偶尔增加。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：立刻指马上发生，人口增长是逐年的渐进过程，不能说立刻增加。"}], "explanations": {"年年": "正确：年年指逐年，人口的增加是按年计算的变化，与整句相符。", "亲自": "搭配：亲自指本人动手，人口的增加不能“亲自”发生，句子读不通。", "偶尔": "语义：偶尔指间或，人口是持续逐年变化的，不能说偶尔增加。", "立刻": "语义：立刻指马上发生，人口增长是逐年的渐进过程，不能说立刻增加。"}, "sentence_index": 0, "correct_answer": "年年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月他的汉语水平年年进步。", "explanation": "这里应该用〈逐月〉。年年按年计算，这句说的是这个月的变化，应表达按月逐步变化的意思，不能用年年。"}, {"text": "这家店今天的生意年年变好。", "explanation": "年年指每一年，不能和表示具体某一天的“今天”连用。"}, {"text": "他的汉语水平年年一下子就进步了。", "explanation": "年年表示逐年的渐进变化，“一下子就”表示瞬间完成，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年年", "is_correct": true, "explanation": "正确：年年指逐年，工厂产量的增长是按年计的变化，与整句相符。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：亲自指本人动手，产量不能“亲自”增长。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：非常修饰形容词，不修饰“增长”这样的动词。"}, {"text": "很", "is_correct": false, "explanation": "搭配：很修饰形容词，不直接修饰动词“增长”，句子不成立。"}], "explanations": {"年年": "正确：年年指逐年，工厂产量的增长是按年计的变化，与整句相符。", "亲自": "搭配：亲自指本人动手，产量不能“亲自”增长。", "非常": "搭配：非常修饰形容词，不修饰“增长”这样的动词。", "很": "搭配：很修饰形容词，不直接修饰动词“增长”，句子不成立。"}, "sentence_index": 6, "correct_answer": "年年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的生意年年在一个星期内变好。", "explanation": "年年以“年”为单位逐年变化，这句说的是一个星期内的变化，应表达按周的变化，不能用年年。"}, {"text": "他们的生意年年很快就变好了。", "explanation": "年年指逐年的变化，“很快就”表示迅速完成，二者不能同时用于一个变化。"}, {"text": "他们的生意年年在一天之内变好。", "explanation": "年年以“年”为单位逐年变化，这句说的是一天之内的变化，应表达按日的变化，不能用年年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的房价很年年上涨。", "corrected_sentence": "这座城市的房价年年上涨。", "error_description": "副词误叠：〈年年〉本身是副词，前面不能再加“很”。应说“房价年年上涨”，删去“很”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的利润年年的增长。", "corrected_sentence": "这家公司的利润年年增长。", "error_description": "“的”位置错误：〈年年〉修饰动词时直接放在动词前，中间不能加“的”。应说“年年增长”，不能说“年年的增长”，后者作谓语不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
