INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86420, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "时间单位，一分钟的六十分之一。", "primary_collocate": null, "pronunciation": "miǎo", "ipa": "mjɑʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "一分钟有六十秒。", "target_word": "秒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他跑一百米用了十三秒。", "target_word": "秒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把手洗二十秒。", "target_word": "秒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告只有十五秒。", "target_word": "秒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电梯三十秒后到。", "target_word": "秒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛还剩最后十秒。", "target_word": "秒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机三十秒没有操作就会自动锁屏。", "target_word": "秒", "complexity_tier": "T3", "furigana": "shǒujī sānshí miǎo méiyǒu cāozuò jiù huì zìdòng suǒpíng。", "sentence_source": "generated"}, {"text": "水开了，再煮五十秒。", "target_word": "秒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他游得比我快两秒。", "target_word": "秒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钟表走一格是一秒。", "target_word": "秒", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "秒钟", "label": "复合"}, {"form": "毫秒", "label": "复合"}], "register": "中性", "sense_fingerprint": "秒：时间单位，一分钟的六十分之一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24b4c419-7330-44fc-8baa-3d93001cf48d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秒", "is_correct": true, "explanation": "秒是时间单位，一分钟有六十秒，符合句意。"}, {"text": "刻", "is_correct": false, "explanation": "语义：一刻是十五分钟，一分钟里不可能有六十刻，与句意矛盾。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“个”不计量时间，“六十个”说不通。"}, {"text": "把", "is_correct": false, "explanation": "语义：“把”计量有柄的东西，不能计量时间。"}], "explanations": {"秒": "秒是时间单位，一分钟有六十秒，符合句意。", "刻": "语义：一刻是十五分钟，一分钟里不可能有六十刻，与句意矛盾。", "个": "搭配：“个”不计量时间，“六十个”说不通。", "把": "语义：“把”计量有柄的东西，不能计量时间。"}, "sentence_index": 0, "correct_answer": "秒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟身高五秒。", "explanation": "这里应该用〈厘米〉。身高用“厘米”，〈秒〉不能表示身高。"}, {"text": "这台电脑卖了三十秒。", "explanation": "这里应该用〈元〉。价钱用“元”，〈秒〉不能表示价钱。"}, {"text": "这次比赛他拿了第三秒。", "explanation": "这里应该用〈第三名〉。排名用“第几名”，〈秒〉是时间单位，不能表示名次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秒", "is_correct": true, "explanation": "秒是时间单位，手机三十秒没有操作就会自动锁屏，符合句意。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”计量书册，不能计量时间。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”计量纸张、桌子等，不能计量时间。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”多用于动物或成对物品中的一个，不能计量时间。"}], "explanations": {"秒": "秒是时间单位，手机三十秒没有操作就会自动锁屏，符合句意。", "本": "搭配：“本”计量书册，不能计量时间。", "张": "搭配：“张”计量纸张、桌子等，不能计量时间。", "只": "语义：“只”多用于动物或成对物品中的一个，不能计量时间。"}, "sentence_index": 6, "correct_answer": "秒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他体重五十秒。", "explanation": "这里应该用〈公斤〉。体重用“公斤”，〈秒〉不能表示体重。"}, {"text": "今天的室温是二十秒。", "explanation": "这里应该用〈度〉。室温用“度”，〈秒〉不能表示温度。"}, {"text": "我姐姐今年二十秒了。", "explanation": "这里应该用〈岁〉。年龄用“岁”，〈秒〉不能表示年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3622f44-b81e-40f4-a996-9e284906dc7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
