INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "印刷用的底版；也指报纸的页面。", "primary_collocate": null, "pronunciation": "bǎn", "ipa": "pan˨˩˦", "syllable_count": 1, "sentences": [{"text": "印刷师傅在检查这块版有没有错字。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个版刻得很清楚，印出来很漂亮。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张报纸一共有八个版。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻登在报纸第二版。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育新闻在第五版，你翻一下。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第三版是广告，我没有看。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块版用了很多年，已经坏了。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文章发表在报纸第四版。", "target_word": "版", "complexity_tier": "T3", "furigana": "tā de wénzhāng fābiǎo zài bàozhǐ dì sì bǎn.", "sentence_source": "generated"}, {"text": "工人把做好的版放进机器里。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片太大，占了半个版。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "版本", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，印刷用的底版，或报纸的一个页面，常说“第几版”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8e76b94-2d0b-469a-847a-d9083859c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86422, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "版", "is_correct": true, "explanation": "正确：版指印刷用的底版，读 bǎn（第三声）。"}, {"text": "办", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是办理。"}, {"text": "半", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是一半。"}, {"text": "伴", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是陪伴。"}, {"text": "满", "is_correct": false, "explanation": "mǎn 与 bǎn 声母不同（m 与 b），意思是满的、充满。"}], "explanations": {"版": "正确：版指印刷用的底版，读 bǎn（第三声）。", "办": "bàn（第四声）与 bǎn（第三声）声调不同，意思是办理。", "半": "bàn（第四声）与 bǎn（第三声）声调不同，意思是一半。", "伴": "bàn（第四声）与 bǎn（第三声）声调不同，意思是陪伴。", "满": "mǎn 与 bǎn 声母不同（m 与 b），意思是满的、充满。"}, "sentence_index": null, "correct_answer": "版"}, "level_3": {"options": [{"text": "版", "is_correct": true, "explanation": "正确：版指印刷用的底版，印刷前要检查它有没有错字。"}, {"text": "字", "is_correct": false, "explanation": "搭配：量词〈块〉不能和〈字〉搭配，应说“一个字”。"}, {"text": "墨", "is_correct": false, "explanation": "语义：墨是墨块，不是印刷用的底版，不会“有错字”。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯没有印刷上的错字，这句话读起来讲不通。"}], "explanations": {"版": "正确：版指印刷用的底版，印刷前要检查它有没有错字。", "字": "搭配：量词〈块〉不能和〈字〉搭配，应说“一个字”。", "墨": "语义：墨是墨块，不是印刷用的底版，不会“有错字”。", "灯": "语义：灯没有印刷上的错字，这句话读起来讲不通。"}, "sentence_index": 0, "correct_answer": "版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一版报纸。", "explanation": "这里应该用〈张〉。版是报纸的页面，量报纸要用张。"}, {"text": "今天一版学生都来参加了比赛。", "explanation": "这里应该用〈名〉。版指印刷用的底版或报纸的页面，不是量人的单位，量学生要用名。"}, {"text": "这本书的版有五十页。", "explanation": "这里应该用〈页〉。版不指页数，说书有几页要用页。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86422, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "版", "is_correct": true, "explanation": "正确：版指印刷用的底版，读 bǎn（第三声）。"}, {"text": "扮", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是扮演。"}, {"text": "拌", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是搅拌。"}, {"text": "榜", "is_correct": false, "explanation": "bǎng 与 bǎn 韵母不同（ang 与 an），意思是榜样或榜单。"}, {"text": "饱", "is_correct": false, "explanation": "bǎo 与 bǎn 韵母不同（ao 与 an），意思是吃饱。"}], "explanations": {"版": "正确：版指印刷用的底版，读 bǎn（第三声）。", "扮": "bàn（第四声）与 bǎn（第三声）声调不同，意思是扮演。", "拌": "bàn（第四声）与 bǎn（第三声）声调不同，意思是搅拌。", "榜": "bǎng 与 bǎn 韵母不同（ang 与 an），意思是榜样或榜单。", "饱": "bǎo 与 bǎn 韵母不同（ao 与 an），意思是吃饱。"}, "sentence_index": null, "correct_answer": "版"}, "level_3": {"options": [{"text": "版", "is_correct": true, "explanation": "正确：版指印刷用的底版，“这块版”指一块印版。"}, {"text": "刀", "is_correct": false, "explanation": "搭配：刀的量词应是〈把〉，不能用〈块〉。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不会“用了很多年，已经坏了”，这句话讲不通。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：鞋的量词是〈双〉，不能用〈块〉。"}], "explanations": {"版": "正确：版指印刷用的底版，“这块版”指一块印版。", "刀": "搭配：刀的量词应是〈把〉，不能用〈块〉。", "花": "语义：花不会“用了很多年，已经坏了”，这句话讲不通。", "鞋": "搭配：鞋的量词是〈双〉，不能用〈块〉。"}, "sentence_index": 6, "correct_answer": "版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她买了一版桌子。", "explanation": "这里应该用〈张〉。版不是桌子的量词，量桌子要用张。"}, {"text": "这栋楼印了三版。", "explanation": "版指印刷用的底版或报纸页面，楼房不能“印了三版”，这里的版用法不对。"}, {"text": "这本词典多了一千版。", "explanation": "这里应该表示增加的词条数，版不用来计算词数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条消息登在报纸第六版了上。", "corrected_sentence": "这条消息登在报纸第六版上。", "error_description": "助词误加：“了”不能放在“版”与“上”之间，应说“第六版上”，删去“了”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条消息登在报纸第五版本上。", "corrected_sentence": "这条消息登在报纸第五版上。", "error_description": "多加了“本”：“版本”是另一个词，意为版次或版本，“第五版本上”不通。应说“第五版上”，删去“本”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bc754d1-8e3d-4da1-a47d-2170e0f647fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
