INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86427, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "贷款是向银行借来的钱，以后要还。", "primary_collocate": null, "pronunciation": "dài kuǎn", "ipa": "taɪ˥˩ kʰwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这笔贷款是银行借给我的钱。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的房子还有贷款。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每月都按时还贷款。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贷款还没还完，我不敢乱花钱。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买车的贷款已经还清了。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们有很多贷款要还。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贷款不是自己的钱，以后要还。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有贷款，爸爸一直在努力工作。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用工资还了这个月的贷款。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔贷款一共十万元。", "target_word": "贷款", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔贷款", "label": "量词"}, {"form": "个人贷款", "label": "复合词"}, {"form": "貸款", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从银行借来、以后要还的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f36a7577-f479-45c5-a74f-422da336fafe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86427, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存款", "is_correct": false, "explanation": "搭配：“借给”说的是把钱借出去，存款是存进银行的钱，不能借给别人。"}, {"text": "贷款", "is_correct": true, "explanation": "贷款：银行借给我、以后需要还的钱，与“借给我”相合。"}, {"text": "利息", "is_correct": false, "explanation": "语义：利息是借款的附加费用，句中说的是借来的本金，不是利息。"}, {"text": "押金", "is_correct": false, "explanation": "语义：押金是交给房东或单位暂时保管的钱，不是银行借出的。"}], "explanations": {"存款": "搭配：“借给”说的是把钱借出去，存款是存进银行的钱，不能借给别人。", "贷款": "贷款：银行借给我、以后需要还的钱，与“借给我”相合。", "利息": "语义：利息是借款的附加费用，句中说的是借来的本金，不是利息。", "押金": "语义：押金是交给房东或单位暂时保管的钱，不是银行借出的。"}, "sentence_index": 0, "correct_answer": "贷款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "租房要交一笔贷款。", "explanation": "这里应该用〈押金〉：租房时交给房东、租约结束后退还的钱。贷款是借来的钱，不能用来交给房东。"}, {"text": "他办了一辆贷款。", "explanation": "这里应该用〈笔〉：贷款是一笔钱，“辆”只用于车，不能修饰贷款。"}, {"text": "他因为违章交了一笔贷款。", "explanation": "这里应该用〈罚款〉：因违章而交的钱是罚款。贷款是借来的钱，不能因违章而交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动所得，属于自己的钱，与“不是自己的钱”矛盾。"}, {"text": "贷款", "is_correct": true, "explanation": "贷款：借来的钱，不是自己的钱，以后要还。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是奖励发给的钱，不需要归还，与“以后要还”矛盾。"}, {"text": "罚款", "is_correct": false, "explanation": "搭配：“还”用于借来的钱，罚款是交给别人的，不能说“还罚款”。"}], "explanations": {"工资": "语义：工资是劳动所得，属于自己的钱，与“不是自己的钱”矛盾。", "贷款": "贷款：借来的钱，不是自己的钱，以后要还。", "奖金": "语义：奖金是奖励发给的钱，不需要归还，与“以后要还”矛盾。", "罚款": "搭配：“还”用于借来的钱，罚款是交给别人的，不能说“还罚款”。"}, "sentence_index": 6, "correct_answer": "贷款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他借了一棵贷款。", "explanation": "这里应该用〈笔〉：“棵”用于树木等植物，不能修饰贷款。"}, {"text": "他办了一本贷款。", "explanation": "这里应该用〈笔〉：“本”用于书籍、本子等，不能修饰贷款这种钱款。"}, {"text": "他办了一把贷款。", "explanation": "这里应该用〈笔〉：“把”用于有柄的器具，不能修饰贷款这种钱款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家每个月都还一只贷款。", "corrected_sentence": "我们家每个月都还贷款。", "error_description": "量词错误：“贷款”不能用量词“只”计量，此处应去掉“一只”，写作“还贷款”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把贷款还。", "corrected_sentence": "他把贷款还清了。", "error_description": "“把”字句的动词后需要补语或“了”，“他把贷款还”不完整。应写作“他把贷款还清了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
