INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86433, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "阻止是不让别人做某件事。", "primary_collocate": null, "pronunciation": "zǔ zhǐ", "ipa": "tsu˨˩˦ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈阻止孩子玩手机。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想阻止他喝酒。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师阻止了两个同学吵架。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也阻止不了她去追求自己的梦想。", "target_word": "阻止", "complexity_tier": "T3", "furigana": "shéi yě zǔzhǐ bù liǎo tā qù zhuīqiú zìjǐ de mèngxiǎng.", "sentence_source": "generated"}, {"text": "爸爸阻止我晚上出门。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友阻止他做危险的事。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想走，但是我阻止了他。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生阻止病人吃太多糖。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么阻止我去北京工作？", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人阻止过她一个人去旅行。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻止了", "label": "完成体"}, {"form": "阻止过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "不让别人做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f36a7577-f479-45c5-a74f-422da336fafe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86433, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阻止", "is_correct": true, "explanation": "正确。阻止指不让别人做某件事。"}, {"text": "组织", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，“组织”指把人或事物有计划地集合起来。"}, {"text": "阻滞", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，“阻滞”指受阻而不畅通。"}, {"text": "阻值", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，“阻值”指电路中电阻的大小。"}], "explanations": {"阻止": "正确。阻止指不让别人做某件事。", "组织": "zhī（第一声）与 zhǐ（第三声）声调不同，“组织”指把人或事物有计划地集合起来。", "阻滞": "zhì（第四声）与 zhǐ（第三声）声调不同，“阻滞”指受阻而不畅通。", "阻值": "zhí（第二声）与 zhǐ（第三声）声调不同，“阻值”指电路中电阻的大小。"}, "sentence_index": null, "correct_answer": "阻止"}, "level_3": {"options": [{"text": "阻止", "is_correct": true, "explanation": "正确。“妈妈阻止孩子玩手机”指妈妈不让孩子玩，符合母子之间的管教关系。"}, {"text": "雇", "is_correct": false, "explanation": "语义：“雇”需要雇主与被雇者的关系，母子之间不能用“雇”。"}, {"text": "唆使", "is_correct": false, "explanation": "语义：“唆使”含有煽动、诱导的贬义，与母亲管教孩子的语境不符。"}, {"text": "令", "is_correct": false, "explanation": "语域：“令”是文言色彩的命令词，口语里不说“妈妈令孩子玩手机”。"}], "explanations": {"阻止": "正确。“妈妈阻止孩子玩手机”指妈妈不让孩子玩，符合母子之间的管教关系。", "雇": "语义：“雇”需要雇主与被雇者的关系，母子之间不能用“雇”。", "唆使": "语义：“唆使”含有煽动、诱导的贬义，与母亲管教孩子的语境不符。", "令": "语域：“令”是文言色彩的命令词，口语里不说“妈妈令孩子玩手机”。"}, "sentence_index": 0, "correct_answer": "阻止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过多的作业阻止了他的进步。", "explanation": "这里应该用〈阻碍〉。“阻止”表示不让人做某事，不能用于“进步”这种抽象结果。"}, {"text": "悲伤阻止了他的笑声。", "explanation": "这里应该用〈压住〉。“阻止”指不让人做某件事或车辆前进，笑声不能被“阻止”，只能被压住。"}, {"text": "这场病阻止了他的成长。", "explanation": "这里应该用〈延缓〉。“阻止”的宾语应是人的行动，“成长”是过程，只能被延缓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻止", "is_correct": true, "explanation": "正确。“我阻止了他”与“他想走，但是”的转折相符。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的动作与“想走，但是”的转折语境不搭配，也不表示拦住他。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”的对象需是取得成绩或喜事的人，与“想走”的转折不合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”针对值得称赞的行为，与“想走”的转折语境不符。"}], "explanations": {"阻止": "正确。“我阻止了他”与“他想走，但是”的转折相符。", "咬": "搭配：“咬”的动作与“想走，但是”的转折语境不搭配，也不表示拦住他。", "祝贺": "语义：“祝贺”的对象需是取得成绩或喜事的人，与“想走”的转折不合。", "表扬": "语义：“表扬”针对值得称赞的行为，与“想走”的转折语境不符。"}, "sentence_index": 6, "correct_answer": "阻止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疲劳阻止了他的心跳。", "explanation": "这里应该用〈减慢〉。“阻止”的宾语应是人的行动或车辆的前进，心跳只能被减慢。"}, {"text": "一张照片阻止了她的眼泪。", "explanation": "这里应该用〈止住〉。“阻止”的宾语应是人的行动，眼泪只能被止住。"}, {"text": "一场大风阻止了整个花园。", "explanation": "这里应该用〈破坏〉。“阻止”的宾语应是人的行动，花园不能被“阻止”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的父母阻止他了跟陌生人见面。", "corrected_sentence": "他的父母阻止了他跟陌生人见面。", "error_description": "错误：“阻止他了”，应为“阻止了他”。“了”紧跟动词，表示动作已完成，不能放在宾语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈没有阻止了他去参加比赛。", "corrected_sentence": "妈妈没有阻止他去参加比赛。", "error_description": "错误：“没有阻止了他”，否定句中不能用“了”，应删去“了”，写作“妈妈没有阻止他去参加比赛。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86434, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
