INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "别人；其他的人。", "primary_collocate": null, "pronunciation": "tā rén", "ipa": "tʰa˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "我们要学会尊重他人。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不要随便打听他人的事。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很少谈论他人的缺点。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "帮助他人会让人觉得快乐。", "target_word": "他人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她总是先考虑他人的感受。", "target_word": "他人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事不能怪他人。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别把自己的错误推给他人。", "target_word": "他人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不抢他人的东西。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们应该多关心他人。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他人的看法有时很有用。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "他人：指自己以外的别人，常见于书面语，如尊重他人、关心他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a212e406-1a81-4898-98b4-5a623bfc2f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "“他人”指自己以外的别人，与“尊重”搭配，符合句意。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，这里是陈述句，不能指泛指的别人。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”指说话人这一方，而“尊重”的对象应是别人，二者冲突。"}, {"text": "这个", "is_correct": false, "explanation": "搭配：“尊重”的对象应是人，“这个”指事物，不能用来尊重。"}], "explanations": {"他人": "“他人”指自己以外的别人，与“尊重”搭配，符合句意。", "谁": "语义：“谁”是疑问代词，这里是陈述句，不能指泛指的别人。", "我们": "语义：“我们”指说话人这一方，而“尊重”的对象应是别人，二者冲突。", "这个": "搭配：“尊重”的对象应是人，“这个”指事物，不能用来尊重。"}, "sentence_index": 0, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你最近太累了，他人应该多休息。", "explanation": "这里指说话的对象本人，应用〈自己〉，不能用〈他人〉。“他人”指自己以外的别人，不指正在对话的人。"}, {"text": "这只猫很可爱，大家都很喜欢他人。", "explanation": "这里应该用〈它〉。“他人”只指人，不指动物。"}, {"text": "我今天有点累，他人想一个人待着。", "explanation": "这里指说话的人自己，应用〈自己〉，不能用〈他人〉。“他人”指自己以外的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "“他人”指别的人，与“推给”搭配，符合句意。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“推给自己”与“自己的错误”自相矛盾，“自己”不能接收错误。"}, {"text": "哪里", "is_correct": false, "explanation": "搭配：“推给”的对象应是人，“哪里”指处所，不能接收错误。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，不指人，与“推给”的对象不符。"}], "explanations": {"他人": "“他人”指别的人，与“推给”搭配，符合句意。", "自己": "语义：“推给自己”与“自己的错误”自相矛盾，“自己”不能接收错误。", "哪里": "搭配：“推给”的对象应是人，“哪里”指处所，不能接收错误。", "什么": "语义：“什么”是疑问代词，不指人，与“推给”的对象不符。"}, "sentence_index": 6, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他人，麻烦你把门关一下。", "explanation": "这里是直接称呼对方，应用〈同学〉〈先生〉等称呼。“他人”泛指自己以外的别人，不能用来称呼面前的人。"}, {"text": "张老师刚打来电话，他人说会晚一点到。", "explanation": "这里应该用〈他〉。“他人”泛指自己以外的别人，不用来指刚提到的某个人。"}, {"text": "那位同学很聪明，他人经常帮我讲题。", "explanation": "这里应该用〈他〉。“他人”泛指别人，不用来指已经提到的那位同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不应该议论他人们的私事。", "corrected_sentence": "我们不应该议论他人的私事。", "error_description": "“他人”本身已表示“别人”，不能再加“们”，应说“他人的私事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该听取一个他人的意见。", "corrected_sentence": "我们应该听取他人的意见。", "error_description": "“他人”是代词，不能直接与数量短语“一个”组合修饰名词，应说“他人的意见”，不能说“一个他人的意见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代：与「古代」相对的时代，二者是反义词。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，与「古代」的时间概念没有对立关系。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是材料名词，与「古代」没有反义关系。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是职业名词，与「古代」没有反义关系。"}], "correct_answer": "现代", "explanations": {"现代": "现代：与「古代」相对的时代，二者是反义词。", "太阳": "语义：太阳是天体，与「古代」的时间概念没有对立关系。", "玻璃": "语义：玻璃是材料名词，与「古代」没有反义关系。", "老师": "语义：老师是职业名词，与「古代」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代：与「古代」相对的时代，二者是反义词。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是地理事物，与「古代」不构成反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，与时间概念「古代」没有对立关系。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生是职业名词，与「古代」没有反义关系。"}], "correct_answer": "现代", "explanations": {"现代": "现代：与「古代」相对的时代，二者是反义词。", "海洋": "语义：海洋是地理事物，与「古代」不构成反义关系。", "书包": "语义：书包是物品，与时间概念「古代」没有对立关系。", "医生": "语义：医生是职业名词，与「古代」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "古代是很久很久以前。", "primary_collocate": null, "pronunciation": "gǔ dài", "ipa": "ku˨˩˦ tai˥˩", "syllable_count": 2, "sentences": [{"text": "古代没有手机，人们写信。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一件古代的衣服。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代的夏天没有空调。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在古代，女孩子很少上学。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的城市比现在小得多。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲古代的英雄。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的人怎么过春节？", "target_word": "古代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是古代的生活。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的人看月亮，想起远方的家人。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学里学习古代文学。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "古代人", "label": "复合"}, {"form": "古代史", "label": "复合"}], "register": "中性", "sense_fingerprint": "很久很久以前的时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b315749-fffd-4616-ac36-54b6cb1ab5fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古代", "is_correct": true, "explanation": "古代：很久很久以前的时代，「古代没有手机，人们写信」符合句意。"}, {"text": "现代", "is_correct": false, "explanation": "语义：现代有手机，「现代没有手机，人们写信」与常识相矛盾。"}, {"text": "当代", "is_correct": false, "explanation": "语域：「当代」偏书面和评论语境，口语叙述中不自然；语义上指当今，与「没有手机」不合。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市通常都有手机和通信设施，「城市没有手机」与常识不符。"}], "explanations": {"古代": "古代：很久很久以前的时代，「古代没有手机，人们写信」符合句意。", "现代": "语义：现代有手机，「现代没有手机，人们写信」与常识相矛盾。", "当代": "语域：「当代」偏书面和评论语境，口语叙述中不自然；语义上指当今，与「没有手机」不合。", "城市": "语义：城市通常都有手机和通信设施，「城市没有手机」与常识不符。"}, "sentence_index": 0, "correct_answer": "古代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候在古代读过书。", "explanation": "这里应该用〈童年〉。古代指很久以前的时期，不能用来指个人的童年经历。"}, {"text": "我昨天在古代吃了午饭。", "explanation": "这里应该用〈今天〉。古代指很久以前的时期，不能与说话人当天或近期的事情搭配。"}, {"text": "我古代住过北京。", "explanation": "这里应该用〈以前〉。古代指遥远的历史时期，讲自己的经历要用以前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古代", "is_correct": true, "explanation": "古代：很久很久以前的时代，「古代的人怎么过春节」符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：「数学」不能修饰「人」指一类人，「数学的人」不成立。"}, {"text": "大海", "is_correct": false, "explanation": "语义：「大海的人」不能指一类人，句子无法理解为某个时代的人。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：「星期」是时间单位，不能作「人」的修饰语。"}], "explanations": {"古代": "古代：很久很久以前的时代，「古代的人怎么过春节」符合句意。", "数学": "搭配：「数学」不能修饰「人」指一类人，「数学的人」不成立。", "大海": "语义：「大海的人」不能指一类人，句子无法理解为某个时代的人。", "星期": "搭配：「星期」是时间单位，不能作「人」的修饰语。"}, "sentence_index": 6, "correct_answer": "古代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的古代比较便宜。", "explanation": "这里应该用〈商品〉。古代是时期名词，不能描述价格；说商品便宜要用具体的事物作主语。"}, {"text": "窗台上摆着一个古代。", "explanation": "这里应该用〈花瓶〉。古代是时间概念，不能当作可以摆在窗台上、用「个」计数的具体物品。"}, {"text": "我把古代带回了家。", "explanation": "这里应该用〈纪念品〉。古代是时间概念，不能被拿着带回家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在博物馆看到了古代的的瓷器。", "corrected_sentence": "我在博物馆看到了古代的瓷器。", "error_description": "错误形式：「古代的的瓷器」；正确形式：「古代的瓷器」。「古代」作定语，「的」只用一次，多写一个「的」就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书讲的是古代的的战争。", "corrected_sentence": "这本书讲的是古代的战争。", "error_description": "错误形式：「古代的的战争」；正确形式：「古代的战争」。「古代」作定语，「的」只用一次，多写一个「的」就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代：与「古代」相对的时代，二者是反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，与「古代」没有反义关系。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是一个季节，与历史时代不构成反义关系。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是地点名词，与「古代」的时间概念不对应。"}], "correct_answer": "现代", "explanations": {"现代": "现代：与「古代」相对的时代，二者是反义词。", "桌子": "语义：桌子是家具，与「古代」没有反义关系。", "春天": "语义：春天是一个季节，与历史时代不构成反义关系。", "学校": "语义：学校是地点名词，与「古代」的时间概念不对应。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代：与「古代」相对的时代，二者是反义词。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是地理事物，与「古代」不构成反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，与时间概念「古代」没有对立关系。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生是职业名词，与「古代」没有反义关系。"}], "correct_answer": "现代", "explanations": {"现代": "现代：与「古代」相对的时代，二者是反义词。", "海洋": "语义：海洋是地理事物，与「古代」不构成反义关系。", "书包": "语义：书包是物品，与时间概念「古代」没有对立关系。", "医生": "语义：医生是职业名词，与「古代」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去距离现代较远的时代。", "primary_collocate": null, "pronunciation": "gǔ dài", "ipa": "ku˨˩˦ tai˥˩", "syllable_count": 2, "sentences": [{"text": "古代的人没有电灯。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代的孩子也要读书。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座桥是古代留下来的。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢看讲古代故事的电影。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在古代，皇帝住在很大的宫殿里。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代没有汽车，人们骑马出门。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里有很多古代的钱。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的医生用草药给人看病。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷对古代的历史很感兴趣。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的路不好走，坐车要很多天。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "古代人", "label": "复合"}, {"form": "古代史", "label": "复合"}], "register": "中性", "sense_fingerprint": "距离现代很远的过去时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b315749-fffd-4616-ac36-54b6cb1ab5fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古代", "is_correct": true, "explanation": "古代：过去距离现代较远的时代，符合句意：古时候的人没有电灯。"}, {"text": "现代", "is_correct": false, "explanation": "语义：现代指当今时代，「现代的人没有电灯」与事实相矛盾。"}, {"text": "当代", "is_correct": false, "explanation": "语域：「当代」偏书面和评论语境，口语叙述中不自然；语义上指当今，与「没有电灯」不合。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市的人通常都用电灯，「城市的人没有电灯」与常识相矛盾。"}], "explanations": {"古代": "古代：过去距离现代较远的时代，符合句意：古时候的人没有电灯。", "现代": "语义：现代指当今时代，「现代的人没有电灯」与事实相矛盾。", "当代": "语域：「当代」偏书面和评论语境，口语叙述中不自然；语义上指当今，与「没有电灯」不合。", "城市": "语义：城市的人通常都用电灯，「城市的人没有电灯」与常识相矛盾。"}, "sentence_index": 0, "correct_answer": "古代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我古代是老师。", "explanation": "这里应该用〈从前〉。古代指很久以前的时期，不能用来说自己曾经担任的身份。"}, {"text": "我今天在古代开了会。", "explanation": "这里应该用〈去年〉。古代指很久以前的时期，不能与说话人近期的经历搭配。"}, {"text": "我古代在北京工作过。", "explanation": "这里应该用〈曾经〉。古代指遥远的历史时期，讲个人经历的时间要用曾经。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古代", "is_correct": true, "explanation": "古代：过去很久远的时代，「博物馆里有很多古代的钱」指古代的钱币，符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：「数学」不能修饰「钱」，「数学的钱」无法成立。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：「星期」是时间单位，不能作「钱」的修饰语。"}, {"text": "春天", "is_correct": false, "explanation": "语义：「春天的钱」没有实际所指，与博物馆陈列的情境不符。"}], "explanations": {"古代": "古代：过去很久远的时代，「博物馆里有很多古代的钱」指古代的钱币，符合句意。", "数学": "搭配：「数学」不能修饰「钱」，「数学的钱」无法成立。", "星期": "搭配：「星期」是时间单位，不能作「钱」的修饰语。", "春天": "语义：「春天的钱」没有实际所指，与博物馆陈列的情境不符。"}, "sentence_index": 6, "correct_answer": "古代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室的古代很大。", "explanation": "这里应该用〈宽敞〉。古代是时期名词，不能用来描述空间的大小，说房间大要用宽敞这类形容词。"}, {"text": "我的书包里有一个古代。", "explanation": "这里应该用〈铅笔〉。古代是时间概念，不能当作可以放进书包、用「个」计数的具体物品。"}, {"text": "他把古代放进了冰箱。", "explanation": "这里应该用〈古董〉。古代是时间概念，不能被搬动后放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在书里看到古代的的地图。", "corrected_sentence": "我在书里看到古代的地图。", "error_description": "错误形式：「古代的的地图」；正确形式：「古代的地图」。「古代」作定语，「的」只用一次，多写一个「的」就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人讲古代的的故事给孩子听。", "corrected_sentence": "老人讲古代的故事给孩子听。", "error_description": "错误形式：「古代的的故事」；正确形式：「古代的故事」。「古代」作定语，「的」只用一次，多写一个「的」就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3673146-53d9-4761-a535-539504aacf03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
