INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86447, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86447, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "因而是说因为前面的事，所以有了后面的结果。", "primary_collocate": null, "pronunciation": "yīn ér", "ipa": "in˥ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "昨晚下了大雨，因而今天很凉快。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，因而没来上课。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人年纪大了，因而走路很慢。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯坏了，因而房间里很黑。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有意思，因而我看了两遍。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机票太贵，因而我们坐火车去。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡得太晚，因而早上起不来。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司搬家了，因而电话号码变了。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了带钱，因而没买那件衣服。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没吃早饭，因而肚子很饿。", "target_word": "因而", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "前面是原因，后面是结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f36a7577-f479-45c5-a74f-422da336fafe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86447, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”需与“但/仍”呼应，句中没有让步的后半句。"}, {"text": "因而", "is_correct": true, "explanation": "因而：表示结果，昨晚下大雨使今天凉快。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”引出相反的不利后果，与下雨后凉快的因果不符。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”需与“就”呼应，句中没有“就”。"}], "explanations": {"尽管": "搭配：“尽管”需与“但/仍”呼应，句中没有让步的后半句。", "因而": "因而：表示结果，昨晚下大雨使今天凉快。", "否则": "语义：“否则”引出相反的不利后果，与下雨后凉快的因果不符。", "只要": "搭配：“只要”需与“就”呼应，句中没有“就”。"}, "sentence_index": 0, "correct_answer": "因而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下了雨，因而我们还是去了公园。", "explanation": "这里应该用〈不过〉：表示转折，下雨之后仍然去了公园。因而表示结果，不能引出这种与不利情况相反的行动。"}, {"text": "带好伞，因而淋雨。", "explanation": "这里应该用〈以免〉：表示为了避免某种后果。因而引出的却是“淋雨”，与带伞的目的正好相反。"}, {"text": "他会唱歌，因而会跳舞。", "explanation": "这里应该用〈而且〉：表示递进，会唱歌不是会跳舞的原因。因而表示因果，这里说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不但", "is_correct": false, "explanation": "搭配：“不但”需与“而且/还”呼应，句中没有后半句。"}, {"text": "因而", "is_correct": true, "explanation": "因而：表示结果，他睡得太晚，所以早上起不来。"}, {"text": "要是", "is_correct": false, "explanation": "语义：“要是”表示假设，句中说的是已经发生的情况。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：“只有”需与“才”呼应，句中没有“才”。"}], "explanations": {"不但": "搭配：“不但”需与“而且/还”呼应，句中没有后半句。", "因而": "因而：表示结果，他睡得太晚，所以早上起不来。", "要是": "语义：“要是”表示假设，句中说的是已经发生的情况。", "只有": "搭配：“只有”需与“才”呼应，句中没有“才”。"}, "sentence_index": 6, "correct_answer": "因而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很用功，因而考得不好。", "explanation": "这里应该用〈反而〉：表示与预期相反。因而只表示顺承的结果，说不出“用功却考差”的反差。"}, {"text": "这不是错误，因而是误会。", "explanation": "这里应该用〈而是〉：用于否定之后的更正。因而表示因果，“不是错误”推不出“是误会”。"}, {"text": "我们坐地铁，因而坐公交。", "explanation": "这里应该用〈或者〉：表示二选一。因而引出结果，“坐地铁”与“坐公交”之间没有因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她病好了，所以因而能去上班了。", "corrected_sentence": "她病好了，因而能去上班了。", "error_description": "“因而”与“所以”同表结果，不能叠用；应删去“所以”，写作“她病好了，因而能去上班了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司开了分店，因而的员工多了。", "corrected_sentence": "这家公司开了分店，因而员工多了。", "error_description": "错误：“因而”是连词，不能带“的”修饰名词；应写作“这家公司开了分店，因而员工多了。”，“因而”直接引出结果分句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '234a1517-b96e-40d5-9d90-ededa3e1932f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
