INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86454, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "实在的力量；真正具备的能力。", "primary_collocate": null, "pronunciation": "shí lì", "ipa": "ʂʐ̩˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这支球队的实力很强。", "target_word": "实力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛要靠实力说话。", "target_word": "实力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的实力得到了大家的认可。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司的实力差不多。", "target_word": "实力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想用实力证明自己。", "target_word": "实力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经过努力，我们的实力提高了很多。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别小看这个对手的实力。", "target_word": "实力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在比赛中发挥出了真正的实力。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家银行经济实力很强。", "target_word": "实力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我对自己的实力很有信心。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "实力：团体或个人真正具备的力量，如球队、公司、银行的实力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a212e406-1a81-4898-98b4-5a623bfc2f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86454, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实力", "is_correct": true, "explanation": "“实力”指团体或个人真正具备的力量，是正确答案。"}, {"text": "视力", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是视力（眼睛看东西的能力），与球队的力量不符。"}, {"text": "失利", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是失利（比赛或竞争中失败），不是具备的力量。"}, {"text": "失礼", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，lǐ（第三声）与 lì（第四声）声调也不同，意思是失礼（言行不恭敬）。"}, {"text": "使力", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是用力，指动作，不是真正具备的能力。"}], "explanations": {"实力": "“实力”指团体或个人真正具备的力量，是正确答案。", "视力": "shì（第四声）与 shí（第二声）声调不同，意思是视力（眼睛看东西的能力），与球队的力量不符。", "失利": "shī（第一声）与 shí（第二声）声调不同，意思是失利（比赛或竞争中失败），不是具备的力量。", "失礼": "shī（第一声）与 shí（第二声）声调不同，lǐ（第三声）与 lì（第四声）声调也不同，意思是失礼（言行不恭敬）。", "使力": "shǐ（第三声）与 shí（第二声）声调不同，意思是用力，指动作，不是真正具备的能力。"}, "sentence_index": null, "correct_answer": "实力"}, "level_3": {"options": [{"text": "实力", "is_correct": true, "explanation": "“实力”指球队真正具备的力量，与“很强”搭配，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“强”用于形容能力或力量，不用来形容年龄。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指外表样子，不能说“很强”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”可以说高或低，不能说“球队的价格很强”。"}], "explanations": {"实力": "“实力”指球队真正具备的力量，与“很强”搭配，符合句意。", "年龄": "搭配：“强”用于形容能力或力量，不用来形容年龄。", "外貌": "体貌：外貌指外表样子，不能说“很强”。", "价格": "搭配：“价格”可以说高或低，不能说“球队的价格很强”。"}, "sentence_index": 0, "correct_answer": "实力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的实力很准，买的东西都不错。", "explanation": "这里应该用〈眼光〉。“实力”指力量和能力，不用来说一个人挑选东西的眼光准不准。"}, {"text": "他的实力很好，一顿能吃三碗饭。", "explanation": "这里应该用〈胃口〉。“实力”指实际的能力和力量，不用来说一个人的食量或胃口。"}, {"text": "这座桥的实力很高。", "explanation": "这里应该用〈强度〉。“实力”指人或团体的能力，不用来形容桥梁的承受力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86454, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "实力", "is_correct": true, "explanation": "“实力”指真正具备的力量，是正确答案。"}, {"text": "势力", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是势力（影响或控制别人的力量），侧重权势。"}, {"text": "事理", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）、lǐ（第三声）与 lì（第四声）声调都不同，意思是事情的道理。"}, {"text": "十里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是十里（距离），与力量无关。"}], "explanations": {"实力": "“实力”指真正具备的力量，是正确答案。", "势力": "shì（第四声）与 shí（第二声）声调不同，意思是势力（影响或控制别人的力量），侧重权势。", "事理": "shì（第四声）与 shí（第二声）、lǐ（第三声）与 lì（第四声）声调都不同，意思是事情的道理。", "十里": "lǐ（第三声）与 lì（第四声）声调不同，意思是十里（距离），与力量无关。"}, "sentence_index": null, "correct_answer": "实力"}, "level_3": {"options": [{"text": "实力", "is_correct": true, "explanation": "“实力”指对手真正具备的能力，与“小看”搭配，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“小看”的对象应是对手的能力，“价格”不能被小看。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”是通讯工具，与对手的能力无关。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不能用来指对手的能力。"}], "explanations": {"实力": "“实力”指对手真正具备的能力，与“小看”搭配，符合句意。", "价格": "搭配：“小看”的对象应是对手的能力，“价格”不能被小看。", "电话": "语义：“电话”是通讯工具，与对手的能力无关。", "作业": "语义：“作业”是学习任务，不能用来指对手的能力。"}, "sentence_index": 6, "correct_answer": "实力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的实力很好。", "explanation": "这里应该用〈质量〉。“实力”指人或团体的能力，不用来评价衣服的好坏。"}, {"text": "这次参加比赛的实力很多。", "explanation": "这里应该用〈人数〉。“实力”是抽象的能力，不能用“很多”来计数。"}, {"text": "这幅画的实力很鲜艳。", "explanation": "这里应该用〈颜色〉。“实力”不指色彩，不能用来形容鲜艳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的实力很多。", "corrected_sentence": "这家公司的实力很强。", "error_description": "“实力”是抽象的能力，不能用“很多”计量；应说“实力很强”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的实力的很强。", "corrected_sentence": "他的实力很强。", "error_description": "多余的“的”：“实力”后不应再加“的”接“很强”，应说“他的实力很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbb0132-c39f-47fc-afd1-2f92917ff4a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86455, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民间", "is_correct": true, "explanation": "正确：「民间」与「官方」相对，指政府之外的群众或社会组织，属于反义关系。"}, {"text": "社会", "is_correct": false, "explanation": "「社会」泛指整个人类群体，与「官方」并不构成反义关系。"}, {"text": "民众", "is_correct": false, "explanation": "「民众」指普通群众，只是描述人群，与「官方」没有反义关系。"}, {"text": "企业", "is_correct": false, "explanation": "「企业」指经营性的组织，与「官方」没有反义关系。"}], "correct_answer": "民间", "explanations": {"民间": "正确：「民间」与「官方」相对，指政府之外的群众或社会组织，属于反义关系。", "社会": "「社会」泛指整个人类群体，与「官方」并不构成反义关系。", "民众": "「民众」指普通群众，只是描述人群，与「官方」没有反义关系。", "企业": "「企业」指经营性的组织，与「官方」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86455, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民间", "is_correct": true, "explanation": "正确：「民间」与「官方」相对，指政府之外的群众或社会组织，属于反义关系。"}, {"text": "医院", "is_correct": false, "explanation": "「医院」指提供诊疗服务的机构，与「官方」没有反义关系。"}, {"text": "学校", "is_correct": false, "explanation": "「学校」指教育机构，与「官方」没有反义关系。"}, {"text": "家庭", "is_correct": false, "explanation": "「家庭」指以婚姻和血缘为纽带的生活单位，与「官方」没有反义关系。"}], "correct_answer": "民间", "explanations": {"民间": "正确：「民间」与「官方」相对，指政府之外的群众或社会组织，属于反义关系。", "医院": "「医院」指提供诊疗服务的机构，与「官方」没有反义关系。", "学校": "「学校」指教育机构，与「官方」没有反义关系。", "家庭": "「家庭」指以婚姻和血缘为纽带的生活单位，与「官方」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86455, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "官方是说国家或者政府这一边。", "primary_collocate": null, "pronunciation": "guān fāng", "ipa": "kuan˥ fɑŋ˥", "syllable_count": 2, "sentences": [{"text": "官方和民间都很关心这件事。", "target_word": "官方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "官方的看法和老百姓不一样。", "target_word": "官方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "官方要帮助生活困难的人。", "target_word": "官方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事，官方还没说话。", "target_word": "官方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "官方和公司一起做了这个计划。", "target_word": "官方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "官方一直关注着这个问题。", "target_word": "官方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官方说的话，大家都很重视。", "target_word": "官方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "官方花钱修了一条新路。", "target_word": "官方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛是官方办的，不是民间办的。", "target_word": "官方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "官方正在听大家的意见。", "target_word": "官方", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "官方网站", "label": "复合"}, {"form": "官方消息", "label": "复合"}], "register": "正式", "sense_fingerprint": "国家或政府一方，与民间相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "官方", "is_correct": true, "explanation": "正确：「官方」指国家或政府一方，可以关心这件事。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无生命的物质，不会「关心」事情。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：「关心」需要有感情的主体，椅子不能做主语。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不会关心这件事。"}], "explanations": {"官方": "正确：「官方」指国家或政府一方，可以关心这件事。", "空气": "语义：空气是无生命的物质，不会「关心」事情。", "椅子": "配价：「关心」需要有感情的主体，椅子不能做主语。", "小说": "语义：小说是文学作品，不会关心这件事。"}, "sentence_index": 0, "correct_answer": "官方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位官方很热心，常常帮助邻居。", "explanation": "这里应该用〈官员〉。「官方」指政府一方，不指个人，不能用「这位」来称呼一个人。"}, {"text": "这家官方卖的衣服很便宜。", "explanation": "这里应该用〈商店〉。「官方」不是商店，不能用「这家」来指一个卖衣服的地方。"}, {"text": "这是我家的官方花园，别人不能进来。", "explanation": "这里应该用〈私人〉。「官方」指政府一方，不能用来形容私人的花园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "官方", "is_correct": true, "explanation": "正确：「官方」指国家或政府一方，它说的话大家都重视。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会说话，「说的话」不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：「说」需要能说话的主体，窗户不能做主语。"}, {"text": "孺子", "is_correct": false, "explanation": "语域：「孺子」是文言用词，与日常口语的语境不符。"}], "explanations": {"官方": "正确：「官方」指国家或政府一方，它说的话大家都重视。", "石头": "语义：石头不会说话，「说的话」不成立。", "窗户": "配价：「说」需要能说话的主体，窗户不能做主语。", "孺子": "语域：「孺子」是文言用词，与日常口语的语境不符。"}, "sentence_index": 6, "correct_answer": "官方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的建议由官方提出，但政府完全不知道。", "explanation": "矛盾：「官方」指政府一方，既说是官方提出，又说政府不知道，前后矛盾。"}, {"text": "我妈妈是一个官方，每天在家做饭。", "explanation": "这里应该用〈妈妈〉。「官方」指政府一方，不指个人，不能用来指妈妈。"}, {"text": "我的官方哥哥今年五岁。", "explanation": "这里应该用〈哥哥〉。「官方」指政府一方，不指个人，不能用来指哥哥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天看到一本官方消息。", "corrected_sentence": "我昨天看到一则官方消息。", "error_description": "量词错误：「本」用于书册，「消息」应搭配「则」或「条」，「一本官方消息」应改为「一则官方消息」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个比赛是官方主办，很正规。", "corrected_sentence": "这个比赛是官方主办的，很正规。", "error_description": "「的」漏掉：「是……的」句式强调施事，应说「是官方主办的」，不能只说「是官方主办」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
