INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86457, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小孩是年纪还小的人。", "primary_collocate": null, "pronunciation": "xiǎo hái", "ipa": "ɕiɑʊ˨˩ xaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "院子里有一个小孩。", "target_word": "小孩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩比大人矮。", "target_word": "小孩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小孩很可爱。", "target_word": "小孩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩要上学，我要上班。", "target_word": "小孩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给小孩买了一件新衣服。", "target_word": "小孩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩看见狗，就跑开了。", "target_word": "小孩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小孩穿着红色的毛衣。", "target_word": "小孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把玩具给了那个小孩。", "target_word": "小孩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我五岁的时候，也是个小孩。", "target_word": "小孩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共汽车上，小孩坐在妈妈的旁边。", "target_word": "小孩", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小孩儿", "label": "儿化"}, {"form": "小孩子", "label": "复合"}], "register": "口语", "sense_fingerprint": "年纪还小的人，与大人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a80a73-35d5-4323-a9ea-7981b33b5d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDE