INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86457, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小孩", "is_correct": true, "explanation": "正确：「小孩」指年纪还小的人，可以出现在院子里。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是抽象概念，不能存在于院子里。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不能作为院子里的存在物。"}, {"text": "人群", "is_correct": false, "explanation": "搭配：「人群」数量要说「一群」，不能说「一个人群」。"}], "explanations": {"小孩": "正确：「小孩」指年纪还小的人，可以出现在院子里。", "友谊": "语义：友谊是抽象概念，不能存在于院子里。", "时间": "语义：时间是抽象概念，不能作为院子里的存在物。", "人群": "搭配：「人群」数量要说「一群」，不能说「一个人群」。"}, "sentence_index": 0, "correct_answer": "小孩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小孩已经五十岁了，每天去公园下棋。", "explanation": "「小孩」指年纪还小的人，不能用来指五十岁的人。"}, {"text": "这只母鸡孵出了几个小孩，都很可爱。", "explanation": "这里应该用〈小鸡〉。「小孩」指人，不能用来指动物的幼崽。"}, {"text": "那个小孩是我的导师，每周指导我的论文。", "explanation": "「小孩」指年纪还小的人，不能用来指指导我论文的导师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小孩", "is_correct": true, "explanation": "正确：「小孩」指年纪还小的人，可以穿着红色的毛衣。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是没有生命的物品，不会穿毛衣。"}, {"text": "石头", "is_correct": false, "explanation": "配价：「穿着」需要能穿衣服的人作主语，石头不能做它的主语。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是电器，不会穿毛衣。"}], "explanations": {"小孩": "正确：「小孩」指年纪还小的人，可以穿着红色的毛衣。", "椅子": "语义：椅子是没有生命的物品，不会穿毛衣。", "石头": "配价：「穿着」需要能穿衣服的人作主语，石头不能做它的主语。", "电视": "语义：电视是电器，不会穿毛衣。"}, "sentence_index": 6, "correct_answer": "小孩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公共汽车上，那个小孩是我的老师，正在给我讲课。", "explanation": "「小孩」指年纪还小的人，不能用来指正在给我讲课的老师。"}, {"text": "公共汽车上，我的父亲是一个小孩，坐在妈妈的旁边。", "explanation": "「小孩」指年纪还小的人，不能用来指自己的父亲。"}, {"text": "公共汽车上，小孩已经七十岁，坐在妈妈的旁边。", "explanation": "「小孩」指年纪还小的人，不能用来指七十岁的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三个小孩们在院子里玩。", "corrected_sentence": "三个小孩在院子里玩。", "error_description": "多余的复数标记：「三个」已表示确切数量，「小孩」后面不能再加「们」，应说「三个小孩」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个很聪明小孩在院子里玩。", "corrected_sentence": "那个很聪明的小孩在院子里玩。", "error_description": "修饰语与中心语之间漏掉「的」：「很聪明」修饰「小孩」时需要加「的」，应说「很聪明的小孩」，不能说「很聪明小孩」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b025bbb0-888c-40d5-962f-1c0522ba5f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
